-- Source: kpogfmwsxwikfilxhcqh; apply only to payroll-staging (suxncpnerzfkjhkhjwbd).
-- No production rows, Auth accounts, tokens, or stored files are copied.
-- Existing tables/data are preserved. New objects use the production definitions.
-- check_function_bodies=false permits forward references, as in a schema dump;
-- function bodies and authenticated dashboard calls are verified after creation.
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '120s';
SET LOCAL search_path = public, extensions;
SET LOCAL check_function_bodies = false;
SELECT pg_advisory_xact_lock(hashtext('tng-payroll-staging-schema-parity-20260905'));
CREATE SCHEMA IF NOT EXISTS private;
REVOKE ALL ON SCHEMA private FROM PUBLIC, anon, authenticated, service_role;


