DO $parity$
BEGIN
  IF to_regprocedure('"private"."notify_coe_approvers_after_update"()') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION private.notify_coe_approvers_after_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
begin
  if old.status is distinct from new.status
     and new.status::text in (''Pending'', ''Pending HR Manager Approval'') then
    perform private.coe_notify_approvers(new.id);
  end if;
  return new;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"private"."resolve_coe_notifications_after_update"()') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION private.resolve_coe_notifications_after_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
begin
  if old.status is distinct from new.status
     and new.status::text in (''Approved'', ''Rejected'', ''Returned for Revision'') then
    update public.notifications
       set is_read = true
     where related_entity_id = new.id::text
       and type = ''COE_UPDATE''
       and title not in (
         ''COE Request Approved'',
         ''COE Request Rejected'',
         ''COE Request Returned for Revision''
       );

    insert into public.notifications(
      user_id, type, title, message, link, is_read, related_entity_id, dedupe_key
    )
    values (
      new.employee_id::text,
      ''COE_UPDATE'',
      case new.status::text
        when ''Approved'' then ''COE Request Approved''
        when ''Rejected'' then ''COE Request Rejected''
        else ''COE Request Returned for Revision''
      end,
      case new.status::text
        when ''Approved'' then ''Your Certificate of Employment request has been approved.''
        when ''Rejected'' then format(''Your Certificate of Employment request has been rejected. Reason: %s'', coalesce(new.rejection_reason, ''''))
        else format(''Your Certificate of Employment request was returned for revision. Notes: %s'', coalesce(new.return_reason, ''''))
      end,
      format(''/employees/coe/requests?requestId=%s'', new.id),
      false,
      new.id::text,
      format(''coe-decision:%s:%s'', new.id, lower(new.status::text))
    )
    on conflict (user_id, dedupe_key) do update
      set type = excluded.type,
          title = excluded.title,
          message = excluded.message,
          link = excluded.link,
          is_read = false,
          related_entity_id = excluded.related_entity_id,
          created_at = now();
  end if;
  return new;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"private"."ensure_coe_approval_snapshot"()') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION private.ensure_coe_approval_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  document_value jsonb;
  action_value text;
begin
  action_value := case when new.status::text = ''Approved'' then ''approve'' else ''reject'' end;

  if new.status::text in (''Approved'', ''Rejected'')
     and (tg_op = ''INSERT'' or old.status is distinct from new.status)
     and not private.is_coe_approval_authorized(
       public.current_hris_user_id(), new.employee_id, action_value
     ) then
    raise exception ''You do not have permission to approve or reject this COE request.'' using errcode = ''42501'';
  end if;

  if new.status::text = ''Approved''
     and (new.template_snapshot is null or new.employee_snapshot is null) then
    new.approved_at := coalesce(new.approved_at, now());
    document_value := private.build_coe_document(new);
    new.template_id := nullif(document_value->>''templateId'', '''')::uuid;
    new.template_snapshot := document_value->''template'';
    new.employee_snapshot := document_value->''employee'';
    new.snapshot_created_at := now();
    new.generation_source := document_value->>''generationSource'';
    new.fallback_reason := document_value->>''fallbackReason'';
    new.generated_document_url := coalesce(
      nullif(new.generated_document_url, ''''),
      ''coe://request/'' || new.id::text || ''/document''
    );
  end if;
  return new;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."return_coe_request"(uuid, text)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.return_coe_request(p_request_id uuid, p_reason text)
 RETURNS coe_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  actor_id uuid := public.current_hris_user_id();
  actor_email text;
  request_row public.coe_requests;
  reason_value text := btrim(coalesce(p_reason, ''''));
begin
  if actor_id is null then
    raise exception ''Authentication is required.'' using errcode = ''42501'';
  end if;
  if length(reason_value) < 1 then
    raise exception ''Revision notes are required to return a COE request.'';
  end if;

  select * into request_row
  from public.coe_requests
  where id = p_request_id
  for update;
  if request_row.id is null then
    raise exception ''COE request not found.'' using errcode = ''P0002'';
  end if;
  if request_row.status::text not in (''Pending'', ''Pending HR Manager Approval'') then
    raise exception ''Only a pending COE request can be returned.'';
  end if;
  if not private.is_coe_approval_authorized(actor_id, request_row.employee_id, ''return'') then
    raise exception ''Only the configured HR Manager or HR Staff authority can return this COE request.'' using errcode = ''42501'';
  end if;

  update public.coe_requests
     set status = ''Returned for Revision'',
         return_reason = reason_value,
         returned_by = actor_id,
         returned_at = now(),
         rejection_reason = null,
         updated_at = now()
   where id = p_request_id
   returning * into request_row;

  select email into actor_email from public.hris_users where id = actor_id;
  insert into public.audit_logs(user_id, user_email, action, entity, entity_id, details)
  values (
    actor_id::text,
    actor_email,
    ''RETURN'',
    ''COERequest'',
    p_request_id::text,
    format(''Returned COE request for revision. Notes: %s'', reason_value)
  );

  return request_row;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."archive_coe_template"(uuid)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.archive_coe_template(p_template_id uuid)
 RETURNS coe_templates
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  actor_id uuid := public.current_hris_user_id();
  actor_email text;
  saved_row public.coe_templates;
begin
  if actor_id is null or not (
    public.is_hr_or_admin()
    or public.has_feature_permission(''COE'', ''manage'')
    or public.has_feature_permission(''COE'', ''edit'')
  ) then
    raise exception ''You do not have permission to archive COE templates.'' using errcode = ''42501'';
  end if;

  update public.coe_templates
     set status = ''Archived'', is_active = false, recommended_purposes = ''{}''::text[],
         archived_at = now(), archived_by = actor_id, updated_at = now(), version = version + 1
   where id = p_template_id
   returning * into saved_row;
  if saved_row.id is null then
    raise exception ''COE template not found.'' using errcode = ''P0002'';
  end if;

  select email into actor_email from public.hris_users where id = actor_id;
  insert into public.audit_logs(user_id, user_email, action, entity, entity_id, details)
  values (
    actor_id::text, actor_email, ''UPDATE'', ''COETemplate'', saved_row.id::text,
    format(''Archived COE template "%s"; existing document snapshots remain unchanged.'', saved_row.name)
  );
  return saved_row;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"private"."resolve_reporting_manager_id"(text)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION private.resolve_reporting_manager_id(p_reference text)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''''
AS $function$
  select manager.id
  from public.hris_users manager
  where nullif(btrim(p_reference), '''') is not null
    and lower(coalesce(manager.status, '''')) = ''active''
    and coalesce(manager.is_duplicate, false) = false
    and (
      p_reference = manager.id::text
      or p_reference = manager.auth_user_id::text
      or p_reference = nullif(manager.employee_id, '''')
      or lower(p_reference) = lower(manager.full_name)
    )
  order by manager.id
  limit 1
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"private"."reconcile_time_request_assignment"(text, uuid, uuid, boolean)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION private.reconcile_time_request_assignment(p_request_type text, p_request_id uuid, p_previous_manager_id uuid DEFAULT NULL::uuid, p_force_notify boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  v_employee_id uuid;
  v_employee_name text;
  v_status text;
  v_saved_manager_id uuid;
  v_current_manager_id uuid;
  v_previous_manager_id uuid;
  v_manager_changed boolean;
  v_has_open_notification boolean;
  v_actor_id uuid := public.current_hris_user_id();
  v_actor_email text;
  v_title text;
  v_message text;
  v_link text;
  v_dedupe_key text;
begin
  if p_request_id is null then
    return;
  end if;

  case lower(p_request_type)
    when ''leave'' then
      select request.employee_id, request.employee_name, request.status::text,
             request.direct_manager_id
        into v_employee_id, v_employee_name, v_status, v_saved_manager_id
      from public.leave_requests request
      where request.id = p_request_id;
    when ''wfh'' then
      select request.employee_id, request.employee_name, request.status::text,
             request.direct_manager_id
        into v_employee_id, v_employee_name, v_status, v_saved_manager_id
      from public.wfh_requests request
      where request.id = p_request_id;
    when ''overtime'' then
      select request.employee_id, request.employee_name, request.status::text,
             request.direct_manager_id
        into v_employee_id, v_employee_name, v_status, v_saved_manager_id
      from public.ot_requests request
      where request.id = p_request_id;
    else
      return;
  end case;

  if v_employee_id is null then
    return;
  end if;

  if lower(p_request_type) = ''leave'' then
    if v_status not in (''Pending'', ''PendingGM'') then return; end if;
    v_title := ''Leave request reassigned for approval'';
    v_message := format(''%s''''s leave request is pending your approval after a reporting-line change.'', coalesce(v_employee_name, ''An employee''));
  elsif lower(p_request_type) = ''wfh'' then
    if v_status not in (''WFH_PENDING_DEPT_HEAD_APPROVAL'', ''WFH_PENDING_GM_APPROVAL'') then return; end if;
    v_title := ''WFH request reassigned for approval'';
    v_message := format(''%s''''s WFH request is pending your approval after a reporting-line change.'', coalesce(v_employee_name, ''An employee''));
  else
    if v_status not in (''Submitted'', ''PendingGM'') then return; end if;
    v_title := ''OT request reassigned for approval'';
    v_message := format(''%s''''s overtime request is pending your approval after a reporting-line change.'', coalesce(v_employee_name, ''An employee''));
  end if;

  v_current_manager_id := private.resolve_direct_manager_id(v_employee_id);
  v_previous_manager_id := coalesce(v_saved_manager_id, p_previous_manager_id);
  v_manager_changed := v_previous_manager_id is distinct from v_current_manager_id;

  if v_manager_changed and v_previous_manager_id is not null then
    update public.notifications notification
       set is_read = true,
           link = ''/approvals'',
           message = case
             when coalesce(notification.message, '''') like ''%no longer assigned to you%''
               then notification.message
             else coalesce(notification.message, '''') || '' This request is no longer assigned to you.''
           end
     where notification.related_entity_id = p_request_id::text
       and notification.is_read = false
       and (
         notification.user_id = v_previous_manager_id::text
         or exists (
           select 1
           from public.hris_users previous_manager
           where previous_manager.id = v_previous_manager_id
             and notification.user_id = previous_manager.auth_user_id::text
         )
       );

    update public.time_request_approval_assignments assignment
       set status = ''Skipped'',
           decision_note = ''Direct reporting manager changed'',
           decided_at = now(),
           updated_at = now()
     where assignment.request_type = lower(p_request_type)
       and assignment.request_id = p_request_id
       and assignment.approver_user_id = v_previous_manager_id
       and assignment.status = ''Pending'';
  end if;

  if lower(p_request_type) = ''leave'' then
    update public.leave_requests
       set direct_manager_id = v_current_manager_id,
           approver_configuration_required = v_current_manager_id is null,
           approval_configuration_note = case
             when v_current_manager_id is null then ''Approver Configuration Required''
             else null
           end
     where id = p_request_id;
  elsif lower(p_request_type) = ''wfh'' then
    update public.wfh_requests
       set direct_manager_id = v_current_manager_id,
           approver_configuration_required = v_current_manager_id is null,
           approval_configuration_note = case
             when v_current_manager_id is null then ''Approver Configuration Required''
             else null
           end
     where id = p_request_id;
  else
    update public.ot_requests
       set direct_manager_id = v_current_manager_id,
           approver_configuration_required = v_current_manager_id is null,
           approval_configuration_note = case
             when v_current_manager_id is null then ''Approver Configuration Required''
             else null
           end
     where id = p_request_id;
  end if;

  if v_current_manager_id is not null then
    v_link := format(''/approvals?type=%s&item=%s'', lower(p_request_type), p_request_id);
    v_dedupe_key := format(''time-request-current-assignment:%s:%s:%s'', lower(p_request_type), p_request_id, v_current_manager_id);

    select exists (
      select 1
      from public.notifications notification
      where notification.user_id = v_current_manager_id::text
        and notification.related_entity_id = p_request_id::text
        and notification.dedupe_key = v_dedupe_key
        and notification.is_read = false
    ) into v_has_open_notification;

    if p_force_notify or v_manager_changed or not v_has_open_notification then
      insert into public.notifications(
        user_id, type, title, message, link, is_read, related_entity_id, dedupe_key
      ) values (
        v_current_manager_id::text,
        ''APPROVAL_REQUIRED'',
        v_title,
        v_message,
        v_link,
        false,
        p_request_id::text,
        v_dedupe_key
      )
      on conflict (user_id, dedupe_key) do update
        set type = excluded.type,
            title = excluded.title,
            message = excluded.message,
            link = excluded.link,
            is_read = false,
            related_entity_id = excluded.related_entity_id,
            created_at = now();
    end if;
  end if;

  if v_manager_changed then
    select employee.email into v_actor_email
    from public.hris_users employee
    where employee.id = v_actor_id;

    insert into public.audit_logs(user_id, user_email, action, entity, entity_id, details)
    values (
      coalesce(v_actor_id::text, ''system''),
      coalesce(v_actor_email, ''system@thenextperience.com''),
      ''REASSIGN'',
      ''TimeRequestRouting'',
      p_request_id::text,
      format(''Reporting line changed for %s request. Direct manager reassigned from %s to %s; request status and history were preserved.'', lower(p_request_type), coalesce(v_previous_manager_id::text, ''none''), coalesce(v_current_manager_id::text, ''none''))
    );
  end if;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"private"."reconcile_time_requests_after_reporting_line_change"()') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION private.reconcile_time_requests_after_reporting_line_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  v_previous_manager_id uuid := private.resolve_reporting_manager_id(old.reports_to);
  request_row record;
begin
  if old.reports_to is not distinct from new.reports_to then
    return new;
  end if;

  for request_row in
    select ''leave''::text as request_type, request.id
    from public.leave_requests request
    where request.employee_id = new.id
      and request.status::text in (''Pending'', ''PendingGM'')
    union all
    select ''wfh''::text as request_type, request.id
    from public.wfh_requests request
    where request.employee_id = new.id
      and request.status::text in (''WFH_PENDING_DEPT_HEAD_APPROVAL'', ''WFH_PENDING_GM_APPROVAL'')
    union all
    select ''overtime''::text as request_type, request.id
    from public.ot_requests request
    where request.employee_id = new.id
      and request.status::text in (''Submitted'', ''PendingGM'')
  loop
    perform private.reconcile_time_request_assignment(
      request_row.request_type,
      request_row.id,
      v_previous_manager_id,
      true
    );
  end loop;

  return new;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."register_user_profile"(uuid, text, text, text, text, text, text, boolean, text, uuid, text, uuid, text, date, date, text, text, text, text, text, text, text, text, text, text)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.register_user_profile(p_auth_user_id uuid, p_email text, p_first_name text, p_last_name text, p_full_name text, p_role text, p_status text, p_is_photo_enrolled boolean, p_business_unit text, p_business_unit_id uuid, p_department text, p_department_id uuid, p_position text, p_birth_date date, p_date_hired date, p_sss_no text, p_pagibig_no text, p_philhealth_no text, p_tin text, p_emergency_contact_name text, p_emergency_contact_relationship text, p_emergency_contact_phone text, p_bank_name text, p_bank_account_number text, p_bank_account_type text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  auth_email text;
  canonical_business_unit public.business_units%rowtype;
  canonical_department public.departments%rowtype;
  new_hris_user_id uuid;
begin
  if p_auth_user_id is null or nullif(trim(p_email), '''') is null then
    raise exception ''A valid authentication identity and email are required.'' using errcode = ''22023'';
  end if;

  select lower(trim(au.email))
    into auth_email
  from auth.users au
  where au.id = p_auth_user_id
    and au.deleted_at is null;

  if auth_email is null then
    raise exception ''The authentication identity does not exist.'' using errcode = ''42501'';
  end if;

  if auth_email <> lower(trim(p_email)) then
    raise exception ''The profile email does not match the authentication identity.'' using errcode = ''42501'';
  end if;

  if exists (
    select 1
    from public.hris_users u
    where u.auth_user_id = p_auth_user_id
       or lower(u.email) = auth_email
  ) then
    raise exception ''A profile already exists for this account.'' using errcode = ''23505'';
  end if;

  if nullif(trim(p_first_name), '''') is null
     or nullif(trim(p_last_name), '''') is null
     or nullif(trim(p_full_name), '''') is null
     or nullif(trim(p_position), '''') is null then
    raise exception ''First name, last name, full name, and position are required.'' using errcode = ''22023'';
  end if;

  if p_business_unit_id is not null then
    select * into canonical_business_unit
    from public.business_units bu
    where bu.id = p_business_unit_id;
  elsif nullif(trim(p_business_unit), '''') is not null then
    select * into canonical_business_unit
    from public.business_units bu
    where lower(trim(bu.name)) = lower(trim(p_business_unit))
    order by bu.id
    limit 1;
  end if;

  if canonical_business_unit.id is null then
    raise exception ''Select a valid business unit.'' using errcode = ''22023'';
  end if;

  if p_department_id is not null then
    select * into canonical_department
    from public.departments d
    where d.id = p_department_id
      and d.business_unit_id = canonical_business_unit.id;
  elsif nullif(trim(p_department), '''') is not null then
    select * into canonical_department
    from public.departments d
    where d.business_unit_id = canonical_business_unit.id
      and lower(trim(d.name)) = lower(trim(p_department))
    order by d.id
    limit 1;
  end if;

  if canonical_department.id is null then
    raise exception ''Select a valid department for the chosen business unit.'' using errcode = ''22023'';
  end if;

  if not exists (
    select 1 from public.roles r where r.id = ''Employee'' and r.is_active
  ) then
    raise exception ''The approved Employee role is unavailable.'' using errcode = ''55000'';
  end if;

  insert into public.hris_users (
    auth_user_id,
    email,
    first_name,
    last_name,
    full_name,
    role,
    status,
    is_photo_enrolled,
    business_unit,
    business_unit_id,
    department,
    department_id,
    position,
    birth_date,
    date_hired,
    sss_no,
    pagibig_no,
    philhealth_no,
    tin,
    emergency_contact_name,
    emergency_contact_relationship,
    emergency_contact_phone,
    bank_name,
    bank_account_number,
    bank_account_type,
    data_access_scope,
    dashboard_type,
    permission_updated_at
  ) values (
    p_auth_user_id,
    auth_email,
    trim(p_first_name),
    trim(p_last_name),
    trim(p_full_name),
    ''Employee'',
    ''Inactive'',
    coalesce(p_is_photo_enrolled, false),
    canonical_business_unit.name,
    canonical_business_unit.id,
    canonical_department.name,
    canonical_department.id,
    trim(p_position),
    p_birth_date,
    p_date_hired,
    nullif(trim(p_sss_no), ''''),
    nullif(trim(p_pagibig_no), ''''),
    nullif(trim(p_philhealth_no), ''''),
    nullif(trim(p_tin), ''''),
    nullif(trim(p_emergency_contact_name), ''''),
    nullif(trim(p_emergency_contact_relationship), ''''),
    nullif(trim(p_emergency_contact_phone), ''''),
    nullif(trim(p_bank_name), ''''),
    nullif(trim(p_bank_account_number), ''''),
    coalesce(nullif(trim(p_bank_account_type), ''''), ''Savings''),
    jsonb_build_object(''type'', ''SELF''),
    ''employee'',
    now()
  )
  returning id into new_hris_user_id;

  insert into public.user_roles (
    user_id,
    role_id,
    is_primary,
    scope_type,
    allowed_business_unit_ids,
    dashboard_type,
    is_active
  ) values (
    new_hris_user_id,
    ''Employee'',
    true,
    ''SELF'',
    ''{}''::uuid[],
    ''employee'',
    true
  );

  insert into public.rbac_cache_versions (user_id, version, updated_at)
  values (new_hris_user_id, 1, now())
  on conflict (user_id) do nothing;

  insert into public.rbac_audit_log (
    actor_user_id,
    target_user_id,
    action,
    entity_type,
    entity_id,
    before_value,
    after_value
  ) values (
    null,
    new_hris_user_id,
    ''SELF_REGISTRATION'',
    ''user_role_assignment'',
    new_hris_user_id::text,
    null,
    jsonb_build_object(
      ''assignedRole'', ''Employee'',
      ''assignedStatus'', ''Inactive'',
      ''scopeType'', ''SELF'',
      ''dashboardType'', ''employee'',
      ''requestedRole'', p_role,
      ''requestedStatus'', p_status,
      ''authUserId'', p_auth_user_id,
      ''email'', auth_email
    )
  );
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"private"."is_active_time_request_approver"(uuid, text, uuid)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION private.is_active_time_request_approver(p_actor_id uuid, p_request_type text, p_request_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  v_employee_id uuid;
  v_current_manager_id uuid;
  v_status text;
  v_manager_stage boolean := false;
begin
  if p_actor_id is null or p_request_id is null then return false; end if;

  case lower(p_request_type)
    when ''leave'' then
      select request.employee_id, request.status::text
        into v_employee_id, v_status
      from public.leave_requests request
      where request.id = p_request_id;
      v_manager_stage := v_status in (''Pending'', ''PendingGM'');
    when ''wfh'' then
      select request.employee_id, request.status::text
        into v_employee_id, v_status
      from public.wfh_requests request
      where request.id = p_request_id;
      v_manager_stage := v_status in (''WFH_PENDING_DEPT_HEAD_APPROVAL'', ''WFH_PENDING_GM_APPROVAL'');
    when ''overtime'' then
      select request.employee_id, request.status::text
        into v_employee_id, v_status
      from public.ot_requests request
      where request.id = p_request_id;
      v_manager_stage := v_status in (''Submitted'', ''PendingGM'');
    else
      return false;
  end case;

  if v_employee_id is null then return false; end if;
  v_current_manager_id := private.resolve_direct_manager_id(v_employee_id);

  if v_manager_stage and (
    p_actor_id = v_current_manager_id
    or private.is_direct_reporting_manager(p_actor_id, v_employee_id)
  ) then
    return true;
  end if;

  return exists (
    select 1
    from public.time_request_approval_assignments assignment
    where assignment.request_type = lower(p_request_type)
      and assignment.request_id = p_request_id
      and assignment.approver_user_id = p_actor_id
      and assignment.status = ''Pending''
  );
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."current_hris_reports_to"()') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.current_hris_reports_to()
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''public''
AS $function$
  SELECT reports_to FROM public.hris_users WHERE auth_user_id = auth.uid() LIMIT 1;
$function$
';
