$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."get_my_pending_job_requisition_approvals"()') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.get_my_pending_job_requisition_approvals()
 RETURNS TABLE(id uuid, req_code text, title text, business_unit_id uuid, department_id uuid, status text, created_at timestamp with time zone, current_step text, step_order integer)
 LANGUAGE sql
 STABLE
 SET search_path TO ''''
AS $function$
  with actor as (
    select public.current_hris_user_id() as id
    where auth.uid() is not null
  )
  select
    requisition.id,
    requisition.req_code,
    requisition.title,
    requisition.business_unit_id,
    requisition.department_id,
    requisition.status::text,
    requisition.created_at,
    coalesce(
      nullif(step.value ->> ''roleSnapshot'', ''''),
      nullif(step.value ->> ''role'', ''''),
      nullif(step.value ->> ''userName'', ''''),
      nullif(step.value ->> ''name'', ''''),
      ''Approval step '' || step.ordinality::text
    ) as current_step,
    coalesce(
      nullif(step.value ->> ''order'', '''')::integer,
      step.ordinality::integer - 1
    ) as step_order
  from actor
  join public.job_requisitions requisition
    on requisition.status = ''PendingApproval''::public.job_requisition_status
  cross join lateral jsonb_array_elements(coalesce(requisition.routing_steps, ''[]''::jsonb))
    with ordinality as step(value, ordinality)
  where actor.id is not null
    and coalesce(step.value ->> ''userId'', step.value ->> ''user_id'') = actor.id::text
    and lower(trim(coalesce(step.value ->> ''status'', ''''))) = ''pending''
  order by requisition.created_at desc
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"private"."resolve_coe_template"(uuid, text, uuid)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION private.resolve_coe_template(p_business_unit_id uuid, p_purpose text, p_requested_template_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  normalized_purpose text := private.normalize_coe_purpose(p_purpose);
  resolved_id uuid;
begin
  if p_business_unit_id is null or normalized_purpose is null then
    return null;
  end if;

  if p_requested_template_id is not null then
    select t.id into resolved_id
    from public.coe_templates t
    where t.id = p_requested_template_id
      and t.business_unit_id = p_business_unit_id
      and t.is_active
      and t.status = ''Published''
      and (
        coalesce(array_length(t.purposes, 1), 0) = 0
        or normalized_purpose = any(t.purposes)
      );
    return resolved_id;
  end if;

  select t.id into resolved_id
  from public.coe_templates t
  where t.business_unit_id = p_business_unit_id
    and t.is_active
    and t.status = ''Published''
    and (
      coalesce(array_length(t.purposes, 1), 0) = 0
      or normalized_purpose = any(t.purposes)
    )
  order by
    case when normalized_purpose = any(coalesce(t.recommended_purposes, ''{}''::text[])) then 0 else 1 end,
    t.updated_at desc,
    t.created_at desc,
    t.id
  limit 1;

  return resolved_id;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"private"."normalize_coe_purpose"(text)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION private.normalize_coe_purpose(p_purpose text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''''
AS $function$
  select case p_purpose
    when ''TRAVEL'' then ''VISA_TRAVEL''
    when ''VISA_APPLICATION'' then ''VISA_TRAVEL''
    when ''SCHOOL_APPLICATION'' then ''SCHOOL_EDUCATION''
    when ''LEGAL_PURPOSES'' then ''GOVERNMENT_LEGAL''
    else p_purpose
  end
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"private"."ensure_coe_request_template"()') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION private.ensure_coe_request_template()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  employee_business_unit_id uuid;
  request_business_unit_id uuid;
  resolved_template_id uuid;
begin
  if new.status::text not in (''Pending HR Manager Approval'', ''Pending'') then
    return new;
  end if;

  if new.purpose::text = ''OTHERS''
     and nullif(btrim(coalesce(new.other_purpose_detail, '''')), '''') is null then
    raise exception ''A custom purpose is required for an Other COE request.'' using errcode = ''23514'';
  end if;

  select u.business_unit_id into employee_business_unit_id
  from public.hris_users u
  where u.id = new.employee_id;

  request_business_unit_id := coalesce(new.employee_business_unit_id, employee_business_unit_id);
  if request_business_unit_id is null then
    raise exception ''The employee must have a business unit before requesting a COE.'' using errcode = ''23514'';
  end if;
  new.employee_business_unit_id := request_business_unit_id;

  if new.template_id is not null then
    resolved_template_id := private.resolve_coe_template(
      request_business_unit_id,
      new.purpose::text,
      new.template_id
    );
    if resolved_template_id is null then
      raise exception ''The selected COE template is not active for this business unit and purpose.'' using errcode = ''23514'';
    end if;
  else
    resolved_template_id := private.resolve_coe_template(
      request_business_unit_id,
      new.purpose::text,
      null
    );
    if resolved_template_id is null then
      raise exception ''No active COE template is configured for this business unit and purpose.'' using errcode = ''23514'';
    end if;
  end if;

  new.template_id := resolved_template_id;
  return new;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."get_coe_review_document"(uuid, uuid)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.get_coe_review_document(p_request_id uuid, p_template_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  actor_id uuid := public.current_hris_user_id();
  request_row public.coe_requests;
  employee_business_unit_id uuid;
  request_business_unit_id uuid;
  selected_template_id uuid;
  document_value jsonb;
begin
  if actor_id is null then
    raise exception ''Authentication is required.'' using errcode = ''42501'';
  end if;

  select * into request_row
  from public.coe_requests
  where id = p_request_id;
  if request_row.id is null then
    raise exception ''COE request not found.'' using errcode = ''P0002'';
  end if;
  if request_row.status::text not in (''Pending'', ''Pending HR Manager Approval'') then
    raise exception ''Only a pending COE request can be reviewed.'';
  end if;
  if not private.is_coe_approval_authorized(actor_id, request_row.employee_id, ''approve'') then
    raise exception ''You do not have permission to review this COE request.'' using errcode = ''42501'';
  end if;

  select u.business_unit_id into employee_business_unit_id
  from public.hris_users u
  where u.id = request_row.employee_id;
  request_business_unit_id := coalesce(request_row.employee_business_unit_id, employee_business_unit_id);

  if p_template_id is not null then
    selected_template_id := private.resolve_coe_template(
      request_business_unit_id,
      request_row.purpose::text,
      p_template_id
    );
    if selected_template_id is null then
      raise exception ''The selected COE template is not active for this business unit and purpose.'' using errcode = ''23514'';
    end if;
  else
    selected_template_id := private.resolve_coe_template(
      request_business_unit_id,
      request_row.purpose::text,
      request_row.template_id
    );
    if selected_template_id is null then
      selected_template_id := private.resolve_coe_template(
        request_business_unit_id,
        request_row.purpose::text,
        null
      );
    end if;
  end if;

  if selected_template_id is null then
    raise exception ''No active COE template is configured for this business unit and purpose.'' using errcode = ''23514'';
  end if;

  request_row.template_id := selected_template_id;
  document_value := private.build_coe_document(request_row);

  return jsonb_build_object(
    ''request'', to_jsonb(request_row) - ''template_snapshot'' - ''employee_snapshot'',
    ''template'', document_value->''template'',
    ''employee'', document_value->''employee'',
    ''meta'', jsonb_build_object(
      ''generationSource'', document_value->>''generationSource'',
      ''fallbackReason'', document_value->>''fallbackReason'',
      ''snapshotCreatedAt'', null,
      ''documentVersion'', request_row.document_version
    )
  );
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."approve_coe_request_with_review"(uuid, uuid, text)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.approve_coe_request_with_review(p_request_id uuid, p_template_id uuid, p_content_override text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  actor_id uuid := public.current_hris_user_id();
  actor_email text;
  request_row public.coe_requests;
  employee_business_unit_id uuid;
  request_business_unit_id uuid;
  selected_template_id uuid;
  content_value text := nullif(btrim(coalesce(p_content_override, '''')), '''');
  content_was_edited boolean := false;
  document_value jsonb;
  approved_time timestamptz := now();
begin
  if actor_id is null then
    raise exception ''Authentication is required.'' using errcode = ''42501'';
  end if;

  select * into request_row
  from public.coe_requests
  where id = p_request_id
  for update;
  if request_row.id is null then
    raise exception ''COE request not found.'' using errcode = ''P0002'';
  end if;
  if request_row.status::text not in (''Pending'', ''Pending HR Manager Approval'') then
    raise exception ''Only a pending COE request can be approved.'';
  end if;
  if not private.is_coe_approval_authorized(actor_id, request_row.employee_id, ''approve'') then
    raise exception ''Only the configured HR approval authority can approve this COE request.'' using errcode = ''42501'';
  end if;

  select u.business_unit_id into employee_business_unit_id
  from public.hris_users u
  where u.id = request_row.employee_id;
  request_business_unit_id := coalesce(request_row.employee_business_unit_id, employee_business_unit_id);
  selected_template_id := private.resolve_coe_template(
    request_business_unit_id,
    request_row.purpose::text,
    p_template_id
  );
  if selected_template_id is null then
    raise exception ''The selected COE template is not active for this business unit and purpose.'' using errcode = ''23514'';
  end if;

  if content_value is not null then
    if length(content_value) > 50000 then
      raise exception ''The edited COE content is too long.'' using errcode = ''22001'';
    end if;
    if content_value ~* ''<[[:space:]]*(script|iframe|object|embed|form)''
       or content_value ~* ''javascript[[:space:]]*:''
       or content_value ~* ''[[:space:]]on[a-z]+[[:space:]]*='' then
      raise exception ''The edited COE content contains unsupported HTML.'' using errcode = ''22023'';
    end if;
    content_was_edited := true;
  end if;

  request_row.template_id := selected_template_id;
  request_row.approved_at := approved_time;
  document_value := private.build_coe_document(request_row);
  if content_was_edited then
    document_value := jsonb_set(document_value, ''{template,body}'', to_jsonb(content_value), true);
  end if;

  update public.coe_requests
     set status = ''Approved'',
         approved_by = actor_id,
         approved_at = approved_time,
         rejection_reason = null,
         return_reason = null,
         returned_by = null,
         returned_at = null,
         generated_document_url = ''coe://request/'' || p_request_id::text || ''/document'',
         template_id = selected_template_id,
         template_snapshot = document_value->''template'',
         employee_snapshot = document_value->''employee'',
         snapshot_created_at = approved_time,
         generation_source = document_value->>''generationSource'',
         fallback_reason = document_value->>''fallbackReason'',
         document_version = greatest(document_version, 1),
         approval_content_edited = content_was_edited,
         updated_at = approved_time
   where id = p_request_id
   returning * into request_row;

  select email into actor_email
  from public.hris_users
  where id = actor_id;

  insert into public.audit_logs(user_id, user_email, action, entity, entity_id, details)
  values (
    actor_id::text,
    actor_email,
    ''APPROVE'',
    ''COERequest'',
    p_request_id::text,
    format(
      ''Approved and sent COE after review (template=%s, template_name=%s, content_edited=%s, approved_at=%s).'',
      selected_template_id,
      coalesce(document_value->''template''->>''name'', ''Certificate of Employment''),
      content_was_edited,
      approved_time
    )
  );

  return jsonb_build_object(
    ''request'', to_jsonb(request_row),
    ''template'', document_value->''template'',
    ''employee'', document_value->''employee'',
    ''meta'', jsonb_build_object(
      ''generationSource'', document_value->>''generationSource'',
      ''fallbackReason'', document_value->>''fallbackReason'',
      ''snapshotCreatedAt'', request_row.snapshot_created_at,
      ''documentVersion'', request_row.document_version
    )
  );
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."admin_replace_role_authority"(text, jsonb, jsonb)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.admin_replace_role_authority(p_role text, p_sensitive_matrix jsonb, p_workflow_matrix jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare actor_id uuid := public.current_hris_user_id(); linked_role text;
begin
  if actor_id is null or not public.has_active_role(''Admin'') then
    raise exception ''Forbidden: Admin authority-management permission is required.'' using errcode = ''42501'';
  end if;
  if p_role in (''Recruiter'',''test role'') or not exists (select 1 from public.roles where id=p_role and is_active) then
    raise exception ''Unknown or inactive role.'';
  end if;
  linked_role := case when p_role=''Board of Director'' then ''HR Manager'' when p_role=''HR Manager'' then ''Board of Director'' end;

  if exists (
    select 1 from jsonb_each(p_sensitive_matrix) entry
    cross join lateral jsonb_array_elements_text(entry.value) action
    where action not in (''view'',''edit'',''download'',''export'')
  ) then raise exception ''Sensitive-data matrix contains an invalid action.''; end if;
  if exists (
    select 1 from jsonb_each(p_workflow_matrix) entry
    cross join lateral jsonb_array_elements_text(entry.value) action
    where action not in (''submit'',''review'',''approve'',''reject'',''return'',''cancel'',''finalize'')
  ) then raise exception ''Workflow matrix contains an invalid action.''; end if;

  delete from public.role_sensitive_permissions where role_id in (p_role,coalesce(linked_role,p_role));
  insert into public.role_sensitive_permissions(role_id,field_key,permissions,updated_at)
  select target.role_id, entry.key, array(select jsonb_array_elements_text(entry.value)), now()
  from jsonb_each(p_sensitive_matrix) entry
  cross join lateral (values (p_role),(linked_role)) target(role_id)
  where target.role_id is not null and jsonb_array_length(entry.value) > 0;

  delete from public.role_workflow_permissions where role_id in (p_role,coalesce(linked_role,p_role));
  insert into public.role_workflow_permissions(role_id,workflow_key,actions,updated_at)
  select target.role_id, entry.key, array(select jsonb_array_elements_text(entry.value)), now()
  from jsonb_each(p_workflow_matrix) entry
  cross join lateral (values (p_role),(linked_role)) target(role_id)
  where target.role_id is not null and jsonb_array_length(entry.value) > 0;

  perform public.assert_bod_hr_manager_parity();
  insert into public.rbac_audit_log(actor_user_id,action,entity_type,entity_id,after_value)
  values(actor_id,''REPLACE_ROLE_AUTHORITY'',''role'',p_role,
    jsonb_build_object(''sensitive'',p_sensitive_matrix,''workflows'',p_workflow_matrix));
  update public.rbac_cache_versions set version=version+1,updated_at=now();
  return true;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."admin_replace_role_permissions"(text, jsonb)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.admin_replace_role_permissions(p_role text, p_matrix jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare actor_id uuid := public.current_hris_user_id(); linked_role text;
begin
  if actor_id is null or not public.has_active_role(''Admin'') then
    raise exception ''Forbidden: Admin permission-management authority is required.'' using errcode = ''42501'';
  end if;
  if p_role in (''Recruiter'',''test role'') or not exists (select 1 from public.roles where id=p_role and is_active) then
    raise exception ''Unknown or inactive role.'';
  end if;
  linked_role := case when p_role=''Board of Director'' then ''HR Manager'' when p_role=''HR Manager'' then ''Board of Director'' end;
  delete from public.role_permissions where role_id in (p_role,coalesce(linked_role,p_role));
  insert into public.role_permissions(role_id,resource_id,permissions,updated_at)
  select target.role_id, entry.key, array(select jsonb_array_elements_text(entry.value)), now()
  from jsonb_each(p_matrix) entry
  cross join lateral (values (p_role),(linked_role)) target(role_id)
  where target.role_id is not null
    and exists(select 1 from public.resources r where r.id=entry.key and r.is_active);
  perform public.assert_bod_hr_manager_parity();
  insert into public.rbac_audit_log(actor_user_id,action,entity_type,entity_id,after_value)
  values(actor_id,''REPLACE_ROLE_PERMISSIONS'',''role'',p_role,p_matrix);
  update public.rbac_cache_versions set version=version+1,updated_at=now();
  return true;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."is_system_admin"()') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.is_system_admin()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''''
AS $function$ select public.has_active_role(''Admin'') $function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."assert_bod_hr_manager_parity"()') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.assert_bod_hr_manager_parity()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  mismatch_count integer;
begin
  select count(*) into mismatch_count
  from (
    (select resource_id, permissions from public.role_permissions where role_id = ''Board of Director''
     except
     select resource_id, permissions from public.role_permissions where role_id = ''HR Manager'')
    union all
    (select resource_id, permissions from public.role_permissions where role_id = ''HR Manager''
     except
     select resource_id, permissions from public.role_permissions where role_id = ''Board of Director'')
    union all
    (select field_key, permissions from public.role_sensitive_permissions where role_id = ''Board of Director''
     except
     select field_key, permissions from public.role_sensitive_permissions where role_id = ''HR Manager'')
    union all
    (select field_key, permissions from public.role_sensitive_permissions where role_id = ''HR Manager''
     except
     select field_key, permissions from public.role_sensitive_permissions where role_id = ''Board of Director'')
    union all
    (select workflow_key, actions from public.role_workflow_permissions
      where role_id = ''Board of Director'' and workflow_key <> ''COE''
     except
     select workflow_key, actions from public.role_workflow_permissions
      where role_id = ''HR Manager'' and workflow_key <> ''COE'')
    union all
    (select workflow_key, actions from public.role_workflow_permissions
      where role_id = ''HR Manager'' and workflow_key <> ''COE''
     except
     select workflow_key, actions from public.role_workflow_permissions
      where role_id = ''Board of Director'' and workflow_key <> ''COE'')
  ) differences;
  if mismatch_count > 0 then
    raise exception ''Board of Director and HR Manager authority parity failed (% differences)'', mismatch_count;
  end if;
  return true;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."admin_set_user_roles"(uuid, text[], text, text, uuid[], text)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.admin_set_user_roles(p_target_user_id uuid, p_role_ids text[], p_primary_role text, p_scope_type text, p_allowed_business_unit_ids uuid[] DEFAULT ''{}''::uuid[], p_dashboard_type text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  v_actor_id uuid := public.current_hris_user_id();
  v_before_state jsonb;
  v_after_state jsonb;
  v_max_roles integer := 1;
  v_requested_role_id text;
  v_final_admins integer;
  v_cache_version bigint;
  v_dashboard_type text;
begin
  if v_actor_id is null or not public.has_active_role(''Admin'') then
    raise exception ''Forbidden: Admin role assignment authority is required.'' using errcode = ''42501'';
  end if;
  if v_actor_id = p_target_user_id then
    raise exception ''Self-promotion and self-role changes are not permitted.'' using errcode = ''42501'';
  end if;
  if not exists (select 1 from public.hris_users target where target.id = p_target_user_id) then
    raise exception ''The selected user does not exist.'' using errcode = ''22023'';
  end if;
  if coalesce(cardinality(p_role_ids), 0) = 0 then
    raise exception ''At least one active role is required.'' using errcode = ''22023'';
  end if;
  if p_scope_type not in (''SELF'',''DIRECT_REPORTS'',''DEPARTMENT'',''HOME_ONLY'',''SPECIFIC'',''GLOBAL'') then
    raise exception ''Invalid data scope: %'', p_scope_type using errcode = ''22023'';
  end if;
  if p_scope_type = ''SPECIFIC'' and coalesce(cardinality(p_allowed_business_unit_ids), 0) = 0 then
    raise exception ''Selected business-unit scope requires at least one business unit.'' using errcode = ''22023'';
  end if;
  if p_dashboard_type is not null and p_dashboard_type not in (''executive'',''hr'',''admin'',''admin_it'',''manager'',''employee'') then
    raise exception ''Invalid dashboard type: %'', p_dashboard_type using errcode = ''22023'';
  end if;
  if p_primary_role is null or not (p_primary_role = any(p_role_ids)) then
    raise exception ''The primary role must be included in assigned roles.'' using errcode = ''22023'';
  end if;
  if cardinality(p_role_ids) <> cardinality(array(select distinct unnest(p_role_ids))) then
    raise exception ''Duplicate role assignments are not permitted.'' using errcode = ''22023'';
  end if;

  select coalesce(allowlist.max_active_roles, 1)
  into v_max_roles
  from (select p_target_user_id as id) target
  left join public.user_multi_role_allowlist allowlist on allowlist.user_id = target.id;
  if cardinality(p_role_ids) > v_max_roles then
    raise exception ''This account is approved for at most % active role(s).'', v_max_roles using errcode = ''22023'';
  end if;
  if exists (
    select 1
    from unnest(p_role_ids) requested(requested_role_id)
    left join public.roles catalog on catalog.id = requested.requested_role_id
    where catalog.id is null or not catalog.is_active
  ) then
    raise exception ''One or more requested roles are unknown or inactive.'' using errcode = ''22023'';
  end if;

  select jsonb_build_object(
    ''profile'', jsonb_build_object(''role'', target.role, ''dashboardType'', target.dashboard_type, ''dataScope'', target.data_access_scope),
    ''roles'', coalesce((select jsonb_agg(to_jsonb(existing_role)) from public.user_roles existing_role where existing_role.user_id = target.id and existing_role.is_active), ''[]''::jsonb)
  ) into v_before_state
  from public.hris_users target where target.id = p_target_user_id;

  if exists (
    select 1 from public.user_roles existing_role
    where existing_role.user_id = p_target_user_id
      and existing_role.role_id = ''Admin''
      and existing_role.is_active
  ) and not (''Admin'' = any(p_role_ids)) then
    select count(distinct existing_role.user_id)
    into v_final_admins
    from public.user_roles existing_role
    join public.hris_users active_user on active_user.id = existing_role.user_id
    where existing_role.role_id = ''Admin''
      and existing_role.is_active
      and lower(active_user.status) = ''active'';
    if v_final_admins <= 1 then
      raise exception ''Cannot remove the final active Admin.'' using errcode = ''22023'';
    end if;
  end if;

  select coalesce(p_dashboard_type, catalog.dashboard_type)
  into v_dashboard_type
  from public.roles catalog where catalog.id = p_primary_role;

  perform set_config(''app.rbac_role_update'', ''allowed'', true);
  update public.user_roles existing_role
  set is_active = false, is_primary = false, updated_at = now(), updated_by = v_actor_id
  where existing_role.user_id = p_target_user_id;

  foreach v_requested_role_id in array p_role_ids loop
    insert into public.user_roles (
      user_id, role_id, is_primary, scope_type, allowed_business_unit_ids,
      dashboard_type, is_active, assigned_by, updated_by
    ) values (
      p_target_user_id, v_requested_role_id, v_requested_role_id = p_primary_role,
      p_scope_type, coalesce(p_allowed_business_unit_ids, ''{}''),
      v_dashboard_type, true, v_actor_id, v_actor_id
    )
    on conflict (user_id, role_id) do update set
      is_primary = excluded.is_primary,
      scope_type = excluded.scope_type,
      allowed_business_unit_ids = excluded.allowed_business_unit_ids,
      dashboard_type = excluded.dashboard_type,
      is_active = true,
      updated_at = now(),
      updated_by = v_actor_id;
  end loop;

  update public.hris_users target
  set role = p_primary_role,
      dashboard_type = v_dashboard_type,
      data_access_scope = jsonb_build_object(
        ''type'', p_scope_type,
        ''allowedBuIds'', coalesce(to_jsonb(p_allowed_business_unit_ids), ''[]''::jsonb)
      ),
      permission_updated_at = now(),
      permission_updated_by = v_actor_id,
      permission_diagnostic = null
  where target.id = p_target_user_id;

  insert into public.rbac_cache_versions(user_id, version, updated_at)
  values (p_target_user_id, 2, now())
  on conflict (user_id) do update
    set version = public.rbac_cache_versions.version + 1, updated_at = now()
  returning version into v_cache_version;

  select jsonb_build_object(
    ''profile'', jsonb_build_object(''role'', target.role, ''dashboardType'', target.dashboard_type, ''dataScope'', target.data_access_scope),
    ''roles'', coalesce((select jsonb_agg(to_jsonb(saved_role)) from public.user_roles saved_role where saved_role.user_id = target.id and saved_role.is_active), ''[]''::jsonb)
  ) into v_after_state
  from public.hris_users target where target.id = p_target_user_id;

  insert into public.rbac_audit_log(
    actor_user_id, target_user_id, action, entity_type, entity_id, before_value, after_value
  ) values (
    v_actor_id, p_target_user_id, ''SET_USER_ROLES'', ''user'', p_target_user_id::text,
    v_before_state, v_after_state
  );

  insert into public.notifications(user_id, type, title, message, link, related_entity_id)
  values (
    p_target_user_id::text,
    ''SYSTEM_ALERT'',
    ''Your HRIS access was updated'',
    ''An administrator updated your role, access scope, or dashboard. Refresh the app to load the new configuration.'',
    ''/my-profile'',
    p_target_user_id::text
  );

  return jsonb_build_object(
    ''success'', true,
    ''targetUserId'', p_target_user_id,
    ''roles'', p_role_ids,
    ''primaryRole'', p_primary_role,
    ''scopeType'', p_scope_type,
    ''allowedBusinessUnitIds'', coalesce(to_jsonb(p_allowed_business_unit_ids), ''[]''::jsonb),
    ''dashboardType'', v_dashboard_type,
    ''cacheVersion'', v_cache_version,
    ''effectiveConfiguration'', v_after_state,
    ''refreshRequired'', true
  );
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."ensure_evaluation_calendar_periods"(integer)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.ensure_evaluation_calendar_periods(p_year integer)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''''
AS $function$
declare
  month_number integer;
  period_start date;
  period_end date;
  current_year integer := extract(year from current_date)::integer;
begin
  if not (select public.is_hr_or_admin()) then
    raise exception ''You do not have permission to manage evaluation timelines.'';
  end if;

  if p_year < current_year - 25 or p_year > current_year + 5 then
    raise exception ''Evaluation year is outside the supported range.'';
  end if;

  perform pg_advisory_xact_lock(hashtext(''evaluation-calendar-periods''), p_year);

  for month_number in 1..12 loop
    period_start := make_date(p_year, month_number, 1);
    period_end := (period_start + interval ''1 month - 1 day'')::date;

    insert into public.evaluation_timelines(name, type, rollout_date, end_date, status)
    select to_char(period_start, ''FMMonth YYYY''), ''Monthly'', period_start, period_end, ''Active''
    where not exists (
      select 1
      from public.evaluation_timelines timeline
      where lower(timeline.type) = ''monthly''
        and timeline.rollout_date = period_start
        and timeline.end_date = period_end
    );
  end loop;

  for month_number in 0..3 loop
    period_start := make_date(p_year, 1 + (month_number * 3), 1);
    period_end := (period_start + interval ''3 months - 1 day'')::date;

    insert into public.evaluation_timelines(name, type, rollout_date, end_date, status)
    select format(''Q%s %s'', month_number + 1, p_year), ''Quarterly'', period_start, period_end, ''Active''
    where not exists (
      select 1
      from public.evaluation_timelines timeline
      where lower(timeline.type) = ''quarterly''
        and timeline.rollout_date = period_start
        and timeline.end_date = period_end
    );
  end loop;

  period_start := make_date(p_year, 1, 1);
  period_end := make_date(p_year, 12, 31);

  insert into public.evaluation_timelines(name, type, rollout_date, end_date, status)
  select format(''Annual Review %s'', p_year), ''Annual'', period_start, period_end, ''Active''
  where not exists (
    select 1
    from public.evaluation_timelines timeline
    where lower(timeline.type) = ''annual''
      and timeline.rollout_date = period_start
      and timeline.end_date = period_end
  );

  insert into public.evaluation_timelines(name, type, rollout_date, end_date, status)
  select format(''Onboarding %s'', p_year), ''Onboarding'', period_start, period_end, ''Active''
  where not exists (
    select 1
    from public.evaluation_timelines timeline
    where lower(timeline.type) = ''onboarding''
      and timeline.rollout_date = period_start
      and timeline.end_date = period_end
  );
end;
$function$
';
  END IF;
END
$parity$;


