DO $parity$
BEGIN
  IF to_regprocedure('"private"."can_current_user_access_evaluation"(uuid)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION private.can_current_user_access_evaluation(p_evaluation_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''''
AS $function$
  select
    (select public.is_hr_or_admin())
    or (select public.is_manager_or_above())
    or exists (
      select 1
      from public.evaluations evaluation
      where evaluation.id = p_evaluation_id
        and (select public.current_hris_user_id()) = any(evaluation.target_employee_ids)
    )
    or exists (
      select 1
      from public.evaluation_evaluators assignment
      left join public.hris_users current_user_profile
        on current_user_profile.id = (select public.current_hris_user_id())
       and lower(current_user_profile.status) = ''active''
      where assignment.evaluation_id = p_evaluation_id
        and (
          (lower(assignment.type) = ''individual'' and assignment.user_id = current_user_profile.id)
          or (
            lower(assignment.type) = ''group''
            and (assignment.business_unit_id is null or assignment.business_unit_id = current_user_profile.business_unit_id)
            and (assignment.department_id is null or assignment.department_id = current_user_profile.department_id)
          )
        )
    );
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"private"."enforce_job_offer_workspace_integrity"()') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION private.enforce_job_offer_workspace_integrity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  material_changed boolean := false;
begin
  perform pg_advisory_xact_lock(hashtextextended(new.application_id::text, 0));

  if tg_op = ''INSERT''
    or new.application_id is distinct from old.application_id
    or (old.status in (''Declined'', ''Expired'') and new.status in (''Draft'', ''Sent'', ''Viewed'', ''Accepted'', ''Signed'', ''Accepted and Signed'', ''Converted'')) then
    if exists (
      select 1
      from public.job_offers existing
      where existing.application_id = new.application_id
        and existing.id is distinct from new.id
        and existing.status in (''Draft'', ''Sent'', ''Viewed'', ''Accepted'', ''Signed'', ''Accepted and Signed'', ''Converted'')
    ) then
      raise exception ''This application already has a current offer. Open the existing offer instead.''
        using errcode = ''23505'';
    end if;
  end if;

  if tg_op = ''UPDATE'' then
    material_changed := row(
      new.application_id,
      new.base_pay,
      new.allowance_json,
      new.start_date,
      new.probation_months,
      new.employment_type,
      new.employment_type_custom_name,
      new.employment_end_date,
      new.reporting_to,
      new.job_description,
      new.offer_expiration_date,
      new.require_signature,
      new.offer_template_id,
      new.offer_template_snapshot,
      new.offer_details - ''emailDelivery'' - ''welcomeEmail''
    ) is distinct from row(
      old.application_id,
      old.base_pay,
      old.allowance_json,
      old.start_date,
      old.probation_months,
      old.employment_type,
      old.employment_type_custom_name,
      old.employment_end_date,
      old.reporting_to,
      old.job_description,
      old.offer_expiration_date,
      old.require_signature,
      old.offer_template_id,
      old.offer_template_snapshot,
      old.offer_details - ''emailDelivery'' - ''welcomeEmail''
    );

    if old.status = ''Draft'' and new.status = ''Sent'' then
      if old.approval_status <> ''Approved'' then
        raise exception ''This offer must complete the approval workflow before it can be sent.''
          using errcode = ''42501'';
      end if;
      if material_changed then
        raise exception ''This offer changed after approval. Save it as a draft and request approval again.''
          using errcode = ''42501'';
      end if;
    elsif old.status = ''Draft'' and new.status = ''Draft''
      and old.approval_status = ''Approved'' and material_changed then
      new.approval_status := ''Not Requested'';
      new.approval_request_id := null;
    elsif old.status in (''Sent'', ''Viewed'', ''Accepted'', ''Signed'', ''Accepted and Signed'', ''Converted'')
      and (material_changed or new.status = ''Draft'') then
      raise exception ''Published offer content is immutable. Create a revised version instead.''
        using errcode = ''42501'';
    end if;
  end if;

  return new;
end;
$function$
';
  END IF;
END
$parity$;


