DO $parity$
BEGIN
  IF to_regprocedure('"public"."save_interview_rating"(uuid, jsonb)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.save_interview_rating(p_rating_id uuid, p_form_data jsonb)
 RETURNS job_interview_rating_records
 LANGUAGE plpgsql
AS $function$
declare
  actor_id uuid := public.current_hris_user_id();
  actor_email text;
  is_admin boolean := public.has_recruitment_admin_access();
  rating_row public.job_interview_rating_records%rowtype;
  old_status text;
  safe_form_data jsonb := coalesce(p_form_data, ''{}''::jsonb);
begin
  select * into rating_row from public.job_interview_rating_records where id = p_rating_id for update;
  if not found then raise exception ''Interview rating was not found''; end if;
  if actor_id is null or (rating_row.reviewer_user_id <> actor_id and not is_admin) then
    raise exception ''You are not authorized to edit this interview rating'';
  end if;
  if rating_row.status in (''Submitted'', ''Locked'') or rating_row.locked_at is not null then
    raise exception ''Submitted interview ratings are locked'';
  end if;
  old_status := rating_row.status;
  if not is_admin then
    safe_form_data := safe_form_data || jsonb_build_object(
      ''candidate_date'', coalesce(rating_row.form_data->''candidate_date'', ''null''::jsonb),
      ''position_applied_for'', coalesce(rating_row.form_data->''position_applied_for'', ''null''::jsonb),
      ''applicant_name'', coalesce(rating_row.form_data->''applicant_name'', ''null''::jsonb),
      ''interviewer_name'', coalesce(rating_row.form_data->''interviewer_name'', ''null''::jsonb),
      ''interviewer_position'', coalesce(rating_row.form_data->''interviewer_position'', ''null''::jsonb)
    );
  end if;
  perform set_config(''tng.interview_rating_action'', ''save'', true);
  update public.job_interview_rating_records
  set form_data = safe_form_data,
      status = case when status = ''Not Started'' then ''Draft'' else status end,
      updated_at = now()
  where id = p_rating_id;
  select * into rating_row from public.job_interview_rating_records where id = p_rating_id;
  select email into actor_email from public.hris_users where id = actor_id;
  insert into public.audit_logs (user_id, user_email, action, entity, entity_id, details)
  values (actor_id::text, actor_email, ''INTERVIEW_RATING_DRAFT_SAVED'', ''job_interview_rating_records'', p_rating_id::text,
    jsonb_build_object(''previous_status'', old_status, ''new_status'', rating_row.status)::text);
  return rating_row;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."create_job_offer_revision"(uuid)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.create_job_offer_revision(p_offer_id uuid)
 RETURNS job_offers
 LANGUAGE plpgsql
 SET search_path TO ''''
AS $function$
declare
  prior_offer public.job_offers%rowtype;
  revised_offer public.job_offers%rowtype;
  actor_id uuid := public.current_hris_user_id();
  next_revision integer;
  base_offer_number text;
begin
  if actor_id is null then
    raise exception ''An authenticated HRIS user is required.'' using errcode = ''42501'';
  end if;

  select *
  into prior_offer
  from public.job_offers
  where id = p_offer_id
  for update;

  if not found then
    raise exception ''Offer not found or not accessible.'' using errcode = ''P0002'';
  end if;

  if prior_offer.status not in (''Sent'', ''Viewed'') then
    raise exception ''Only a sent or viewed offer awaiting a candidate response can be revised.'' using errcode = ''22023'';
  end if;

  update public.job_offers
  set status = ''Expired'',
      last_saved_at = now(),
      updated_at = now()
  where id = prior_offer.id
  returning * into prior_offer;

  next_revision := greatest(prior_offer.revision, 2);
  base_offer_number := regexp_replace(prior_offer.offer_number, ''-R[0-9]+$'', '''');

  insert into public.job_offers (
    application_id,
    offer_number,
    base_pay,
    allowance_json,
    start_date,
    probation_months,
    employment_type,
    status,
    reporting_to,
    job_description,
    created_by_user_id,
    offer_details,
    draft_step,
    offer_expiration_date,
    logo_url,
    logo_path,
    last_saved_at,
    recipient_email,
    email_subject,
    email_message,
    revision,
    require_signature,
    offer_template_id,
    offer_template_name,
    offer_template_snapshot,
    approval_status,
    approval_request_id,
    employment_type_custom_name,
    employment_end_date,
    supersedes_offer_id
  ) values (
    prior_offer.application_id,
    base_offer_number || ''-R'' || next_revision::text,
    prior_offer.base_pay,
    prior_offer.allowance_json,
    prior_offer.start_date,
    prior_offer.probation_months,
    prior_offer.employment_type,
    ''Draft'',
    prior_offer.reporting_to,
    prior_offer.job_description,
    actor_id,
    prior_offer.offer_details - ''candidateResponse'' - ''emailDelivery'' - ''welcomeEmail'',
    prior_offer.draft_step,
    prior_offer.offer_expiration_date,
    prior_offer.logo_url,
    prior_offer.logo_path,
    now(),
    prior_offer.recipient_email,
    prior_offer.email_subject,
    prior_offer.email_message,
    next_revision,
    prior_offer.require_signature,
    prior_offer.offer_template_id,
    prior_offer.offer_template_name,
    prior_offer.offer_template_snapshot,
    ''Not Requested'',
    null,
    prior_offer.employment_type_custom_name,
    prior_offer.employment_end_date,
    prior_offer.id
  )
  returning * into revised_offer;

  return revised_offer;
end;
$function$
';
  END IF;
END
$parity$;


