$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"private"."refresh_incident_nte_summary"(uuid)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION private.refresh_incident_nte_summary(p_incident_report_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  total_employees integer;
  employees_with_nte integer;
  active_ntes integer;
  all_nte_ids uuid[];
  status_counts jsonb;
  next_stage text;
begin
  select cardinality(ir.involved_employee_ids)
  into total_employees
  from public.incident_reports ir
  where ir.id = p_incident_report_id;

  if total_employees is null then return; end if;

  select
    count(distinct n.recipient_employee_id) filter (
      where n.status not in (''Rejected''::public.nte_status, ''Closed''::public.nte_status)
    ),
    count(*) filter (
      where n.status not in (''Rejected''::public.nte_status, ''Closed''::public.nte_status)
    ),
    coalesce(array_agg(n.id order by n.created_at, n.id), ''{}''::uuid[])
  into employees_with_nte, active_ntes, all_nte_ids
  from public.ntes n
  where n.incident_report_id = p_incident_report_id;

  select coalesce(jsonb_object_agg(status_text, status_count), ''{}''::jsonb)
  into status_counts
  from (
    select n.status::text status_text, count(*) status_count
    from public.ntes n
    where n.incident_report_id = p_incident_report_id
    group by n.status::text
  ) counts;

  next_stage := case
    when exists (
      select 1 from public.ntes n
      where n.incident_report_id = p_incident_report_id
        and n.status = ''PendingApproval''::public.nte_status
    ) then ''nte-for-approval''
    when exists (
      select 1 from public.ntes n
      where n.incident_report_id = p_incident_report_id
        and n.status = ''Draft''::public.nte_status
    ) then ''nte-draft''
    when exists (
      select 1 from public.ntes n
      where n.incident_report_id = p_incident_report_id
        and n.status = ''Issued''::public.nte_status
    ) then ''nte-sent''
    when exists (
      select 1 from public.ntes n
      where n.incident_report_id = p_incident_report_id
        and n.status in (''Response Submitted''::public.nte_status, ''Waiver''::public.nte_status)
    ) then ''hr-review-response''
    when exists (
      select 1 from public.ntes n
      where n.incident_report_id = p_incident_report_id
        and n.status = ''Hearing Scheduled''::public.nte_status
    ) then ''scheduled-hearing''
    when exists (
      select 1 from public.ntes n
      where n.incident_report_id = p_incident_report_id
        and n.status = ''Approved''::public.nte_status
    ) then ''nte-for-approval''
    when exists (
      select 1 from public.ntes n
      where n.incident_report_id = p_incident_report_id
        and n.status = ''Rejected''::public.nte_status
    ) then ''ir-review''
    when employees_with_nte = 0 then ''ir-review''
    when employees_with_nte < total_employees then ''nte-partial''
    else ''employee-processing-complete''
  end;

  update public.incident_reports
  set nte_ids = all_nte_ids,
      nte_processing_complete = total_employees > 0 and employees_with_nte >= total_employees,
      nte_processing_summary = jsonb_build_object(
        ''totalEmployees'', total_employees,
        ''employeesWithNte'', employees_with_nte,
        ''activeNtes'', active_ntes,
        ''statusCounts'', status_counts,
        ''processingIncomplete'', employees_with_nte < total_employees
      ),
      pipeline_stage = case
        when status in (''Closed''::public.ir_status, ''NoAction''::public.ir_status) then pipeline_stage
        else next_stage
      end,
      updated_at = now()
  where id = p_incident_report_id;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."normalize_job_candidate_document_type"()') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.normalize_job_candidate_document_type()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''public'', ''pg_temp''
AS $function$
begin
  if new.document_type = ''Other Supporting Document'' then
    if lower(new.file_name) ~ ''(^|[^a-z])(resume|curriculum[ _-]*vitae)([^a-z]|$)''
       or lower(new.file_name) ~ ''(^|[^a-z])cv([^a-z]|$)'' then
      new.document_type := ''Resume'';
    elsif lower(new.file_name) ~ ''interview[^a-z0-9]*rating|rating[^a-z0-9]*interview'' then
      new.document_type := ''Interview Rating'';
    end if;
  end if;
  return new;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"private"."populate_offer_approval_request_scope"()') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION private.populate_offer_approval_request_scope()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  linked_application_id uuid;
  linked_candidate_id uuid;
  linked_job_post_id uuid;
  linked_requisition_id uuid;
begin
  select offer.application_id,
         application.candidate_id,
         application.job_post_id,
         application.requisition_id
  into linked_application_id, linked_candidate_id, linked_job_post_id, linked_requisition_id
  from public.job_offers offer
  join public.job_applications application on application.id = offer.application_id
  where offer.id = new.offer_id;

  if linked_application_id is null then
    raise exception ''Offer application was not found'' using errcode = ''22023'';
  end if;

  new.application_id := linked_application_id;
  new.candidate_id := linked_candidate_id;
  new.job_post_id := linked_job_post_id;
  new.requisition_id := linked_requisition_id;
  return new;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."update_job_candidate_document_type"(uuid, text)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.update_job_candidate_document_type(p_document_id uuid, p_document_type text)
 RETURNS job_candidate_documents
 LANGUAGE plpgsql
 SET search_path TO ''''
AS $function$
declare
  actor_id uuid := (select public.current_hris_user_id());
  actor_email text;
  document_row public.job_candidate_documents%rowtype;
  previous_type text;
  normalized_type text;
begin
  if actor_id is null or not (select public.has_recruitment_admin_access()) then
    raise exception ''Only authorized recruitment users can classify candidate documents'' using errcode = ''42501'';
  end if;

  normalized_type := case lower(btrim(coalesce(p_document_type, '''')))
    when ''resume'' then ''Resume''
    when ''interview rating'' then ''Interview Rating''
    when ''offer'' then ''Offer''
    when ''other supporting document'' then ''Other Supporting Document''
    else null
  end;
  if normalized_type is null then
    raise exception ''Invalid candidate document type'' using errcode = ''22023'';
  end if;

  select * into document_row
  from public.job_candidate_documents
  where id = p_document_id
  for update;
  if not found then
    raise exception ''Candidate document was not found'' using errcode = ''22023'';
  end if;

  if exists (
    select 1
    from public.job_offer_approval_requests request
    cross join lateral jsonb_array_elements(coalesce(request.attachment_snapshot, ''[]''::jsonb)) attachment
    where attachment->>''source'' = ''candidate_document''
      and attachment->>''sourceId'' = document_row.id::text
  ) then
    raise exception ''A document already recorded in an approval package cannot be reclassified'' using errcode = ''55000'';
  end if;

  previous_type := document_row.document_type;
  if previous_type = normalized_type then
    return document_row;
  end if;

  update public.job_candidate_documents
  set document_type = normalized_type,
      metadata = jsonb_set(
        coalesce(metadata, ''{}''::jsonb),
        ''{classificationHistory}'',
        coalesce(metadata->''classificationHistory'', ''[]''::jsonb)
          || jsonb_build_array(jsonb_build_object(
            ''from'', previous_type,
            ''to'', normalized_type,
            ''changedBy'', actor_id,
            ''changedAt'', now()
          )),
        true
      )
  where id = document_row.id
  returning * into document_row;

  select email into actor_email from public.hris_users where id = actor_id;
  insert into public.audit_logs(user_id, user_email, action, entity, entity_id, details)
  values (
    actor_id::text,
    actor_email,
    ''CANDIDATE_DOCUMENT_RECLASSIFIED'',
    ''job_candidate_documents'',
    document_row.id::text,
    jsonb_build_object(
      ''candidate_id'', document_row.candidate_id,
      ''application_id'', document_row.application_id,
      ''file_name'', document_row.file_name,
      ''previous_type'', previous_type,
      ''new_type'', normalized_type
    )::text
  );

  return document_row;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"private"."sync_approved_offer_application_stage"()') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION private.sync_approved_offer_application_stage()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  actor_id uuid := (select public.current_hris_user_id());
  actor_email text;
  prior_stage text;
begin
  if new.approval_status = ''Approved''
     and old.approval_status is distinct from new.approval_status then
    select stage into prior_stage
    from public.job_applications
    where id = new.application_id
    for update;

    update public.job_applications
    set stage = ''Offer'', updated_at = now()
    where id = new.application_id
      and stage not in (''Offer'', ''Hired'', ''Rejected'', ''Withdrawn'');

    if found and actor_id is not null then
      select email into actor_email from public.hris_users where id = actor_id;
      insert into public.audit_logs(user_id, user_email, action, entity, entity_id, details)
      values (
        actor_id::text,
        actor_email,
        ''OFFER_APPROVAL_APPLICATION_STAGE_ADVANCED'',
        ''job_applications'',
        new.application_id::text,
        jsonb_build_object(
          ''offer_id'', new.id,
          ''approval_request_id'', new.approval_request_id,
          ''previous_stage'', prior_stage,
          ''new_stage'', ''Offer''
        )::text
      );
    end if;
  end if;
  return new;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"private"."refresh_evaluation_assignment_status"(uuid, uuid)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION private.refresh_evaluation_assignment_status(p_evaluation_id uuid, p_employee_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
begin
  update public.evaluation_assignments assignment
  set status = case
        when assignment.status = ''Cancelled'' then ''Cancelled''
        when cardinality(assignment.evaluator_user_ids) = 0 then ''Pending''
        when not exists (
          select 1
          from unnest(assignment.evaluator_user_ids) evaluator_id
          where not exists (
            select 1
            from public.evaluation_submissions submission
            where submission.evaluation_id = assignment.evaluation_id
              and submission.subject_employee_id = assignment.employee_id
              and submission.rater_id = evaluator_id
          )
        ) then ''Completed''
        when exists (
          select 1
          from public.evaluation_submissions submission
          where submission.evaluation_id = assignment.evaluation_id
            and submission.subject_employee_id = assignment.employee_id
            and submission.rater_id = any(assignment.evaluator_user_ids)
        ) then ''In Progress''
        else ''Pending''
      end,
      completed_at = case
        when cardinality(assignment.evaluator_user_ids) > 0
          and not exists (
            select 1
            from unnest(assignment.evaluator_user_ids) evaluator_id
            where not exists (
              select 1
              from public.evaluation_submissions submission
              where submission.evaluation_id = assignment.evaluation_id
                and submission.subject_employee_id = assignment.employee_id
                and submission.rater_id = evaluator_id
            )
          )
        then coalesce((
          select max(submission.submitted_at)
          from public.evaluation_submissions submission
          where submission.evaluation_id = assignment.evaluation_id
            and submission.subject_employee_id = assignment.employee_id
            and submission.rater_id = any(assignment.evaluator_user_ids)
        ), now())
        else null
      end
  where assignment.evaluation_id = p_evaluation_id
    and assignment.employee_id = p_employee_id;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"private"."refresh_evaluation_assignment_members"(uuid)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION private.refresh_evaluation_assignment_members(p_evaluation_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  assignment_row record;
begin
  update public.evaluation_assignments assignment
  set evaluator_config = coalesce((
        select jsonb_agg(jsonb_build_object(
          ''id'', evaluator.id,
          ''type'', upper(evaluator.type),
          ''weight'', evaluator.weight,
          ''user_id'', evaluator.user_id,
          ''business_unit_id'', evaluator.business_unit_id,
          ''department_id'', evaluator.department_id,
          ''is_anonymous'', evaluator.is_anonymous,
          ''exclude_subject'', evaluator.exclude_subject
        ) order by evaluator.id)
        from public.evaluation_evaluators evaluator
        where evaluator.evaluation_id = assignment.evaluation_id
      ), ''[]''::jsonb),
      evaluator_user_ids = coalesce((
        select array_agg(distinct eligible_user.id order by eligible_user.id)
        from public.evaluation_evaluators evaluator
        join public.hris_users eligible_user
          on lower(eligible_user.status) = ''active''
         and (
           (evaluator.type = ''Individual'' and eligible_user.id = evaluator.user_id)
           or (
             evaluator.type = ''Group''
             and (evaluator.business_unit_id is null or eligible_user.business_unit_id = evaluator.business_unit_id)
             and (evaluator.department_id is null or eligible_user.department_id = evaluator.department_id)
             and not (coalesce(evaluator.exclude_subject, true) and eligible_user.id = assignment.employee_id)
           )
         )
        where evaluator.evaluation_id = assignment.evaluation_id
      ), ''{}''::uuid[])
  where assignment.evaluation_id = p_evaluation_id;

  for assignment_row in
    select assignment.employee_id
    from public.evaluation_assignments assignment
    where assignment.evaluation_id = p_evaluation_id
  loop
    perform private.refresh_evaluation_assignment_status(p_evaluation_id, assignment_row.employee_id);
  end loop;

  insert into public.notifications(
    user_id, type, title, message, link, related_entity_id, is_read, dedupe_key
  )
  select distinct
    evaluator_id::text,
    ''EVALUATION_ASSIGNED'',
    ''Evaluation Assigned'',
    format(''You have been assigned to complete %s.'', evaluation.name),
    format(''/evaluation/perform/%s'', evaluation.id),
    evaluation.id::text,
    false,
    format(''evaluation:%s:evaluator'', evaluation.id)
  from public.evaluation_assignments assignment
  join public.evaluations evaluation on evaluation.id = assignment.evaluation_id
  cross join lateral unnest(assignment.evaluator_user_ids) evaluator_id
  where assignment.evaluation_id = p_evaluation_id
  on conflict (user_id, dedupe_key) do nothing;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"private"."sync_evaluation_assignment_members"()') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION private.sync_evaluation_assignment_members()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
begin
  if tg_op = ''DELETE'' then
    perform private.refresh_evaluation_assignment_members(old.evaluation_id);
    return old;
  end if;

  if tg_op = ''UPDATE'' and old.evaluation_id is distinct from new.evaluation_id then
    perform private.refresh_evaluation_assignment_members(old.evaluation_id);
  end if;
  perform private.refresh_evaluation_assignment_members(new.evaluation_id);
  return new;
end;
$function$
';
  END IF;
END
