DO $parity$
BEGIN
  IF to_regprocedure('"public"."capture_job_offer_history"()') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.capture_job_offer_history()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''public''
AS $function$
begin
  if tg_op = ''UPDATE'' then
    insert into public.job_offer_history (
      offer_id, action, status, revision, snapshot, changed_by_user_id
    ) values (
      old.id,
      case when old.status is distinct from new.status then ''STATUS_CHANGE'' else ''EDIT'' end,
      new.status,
      new.revision,
      to_jsonb(new),
      new.sent_by_user_id
    );
  elsif tg_op = ''INSERT'' then
    insert into public.job_offer_history (
      offer_id, action, status, revision, snapshot, changed_by_user_id
    ) values (
      new.id, ''CREATE'', new.status, new.revision, to_jsonb(new), new.created_by_user_id
    );
  end if;
  return new;
end;
$function$
';
  END IF;
END
