DO $parity$
BEGIN
  IF to_regprocedure('"public"."accept_and_sign_job_offer"(uuid, text, text, text, timestamp with time zone, jsonb)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.accept_and_sign_job_offer(p_offer_id uuid, p_signature_name text, p_signature_type text, p_signature_path text, p_responded_at timestamp with time zone, p_offer_details jsonb)
 RETURNS job_offers
 LANGUAGE plpgsql
 SET search_path TO ''''
AS $function$
declare
  accepted_offer public.job_offers;
begin
  update public.job_offers
  set status = ''Accepted and Signed'',
      accepted_at = coalesce(accepted_at, p_responded_at),
      signed_at = p_responded_at,
      signature_name = p_signature_name,
      signature_type = p_signature_type,
      signature_path = p_signature_path,
      offer_details = p_offer_details,
      last_saved_at = p_responded_at
  where id = p_offer_id
    and status in (''Sent'', ''Viewed'')
  returning * into accepted_offer;

  -- Make duplicate browser submissions idempotent without creating another response.
  if accepted_offer.id is null then
    select * into accepted_offer
    from public.job_offers
    where id = p_offer_id
      and status in (''Signed'', ''Accepted and Signed'');
  end if;

  if accepted_offer.id is null then
    raise exception ''This offer has already been answered.'' using errcode = ''P0001'';
  end if;

  return accepted_offer;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."can_access_hris_user"(uuid)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.can_access_hris_user(p_target_user_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  viewer public.hris_users;
  target_user public.hris_users;
  scope jsonb;
  scope_type text;
begin
  select * into viewer
  from public.hris_users
  where id = public.current_hris_user_id();

  select * into target_user
  from public.hris_users
  where id = p_target_user_id;

  if viewer.id is null or target_user.id is null then return false; end if;
  if viewer.id = target_user.id then return true; end if;

  -- Admin-only global directory access. This uses active server-resolved roles
  -- and permissions; it is not based on an email or frontend claim.
  if public.has_active_role(''Admin'')
     and public.has_feature_permission(''UserManagement'', ''view'') then
    return true;
  end if;

  if not public.has_feature_permission(''Employees'', ''view'')
     and not public.has_feature_permission(''EmployeeList'', ''view'')
     and not public.has_feature_permission(''UserManagement'', ''view'') then
    return false;
  end if;

  scope := public.current_data_scope();
  scope_type := scope->>''type'';
  if scope_type = ''GLOBAL'' then return true; end if;
  if scope_type = ''SPECIFIC'' then
    return target_user.business_unit_id::text in (
      select jsonb_array_elements_text(scope->''allowedBuIds'')
    );
  end if;
  if scope_type = ''HOME_ONLY'' then
    return viewer.business_unit_id is not null
      and viewer.business_unit_id = target_user.business_unit_id;
  end if;
  if scope_type = ''DEPARTMENT'' then
    return viewer.department_id is not null
      and viewer.department_id = target_user.department_id;
  end if;
  if scope_type = ''DIRECT_REPORTS'' then
    return target_user.reports_to in (
      viewer.id::text,
      viewer.auth_user_id::text,
      viewer.employee_id,
      viewer.full_name
    );
  end if;
  return false;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"private"."bump_rbac_cache_for_user"(uuid)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION private.bump_rbac_cache_for_user(p_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
begin
  if p_user_id is null then return; end if;
  insert into public.rbac_cache_versions (user_id, version, updated_at)
  values (p_user_id, 2, now())
  on conflict (user_id) do update
  set version = public.rbac_cache_versions.version + 1,
      updated_at = now();
end;
$function$
';
  END IF;
END
