DO $parity$
BEGIN
  IF to_regprocedure('"private"."sync_announcement_recipients"()') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION private.sync_announcement_recipients()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
begin
  with eligible as (
    select distinct u.id
    from public.hris_users u
    left join public.user_roles ur on ur.user_id = u.id and ur.is_active
    where lower(coalesce(u.status, '''')) = ''active''
      and (new.business_unit_id is null or u.business_unit_id = new.business_unit_id)
      and (
        lower(new.target_group) = ''all''
        or (lower(new.target_group) = ''management'' and coalesce(ur.role_id, u.role) in (
          ''Board of Director'', ''GeneralManager'', ''Business Unit Manager'', ''Manager'', ''Operations Director'', ''HR Manager''
        ))
        or (lower(new.target_group) = ''hr'' and (
          coalesce(ur.role_id, u.role) in (''HR Staff'', ''HR Manager'')
          or lower(coalesce(u.department, '''')) like ''%human resource%''
          or lower(coalesce(u.department, '''')) = ''hr''
        ))
        or (lower(new.target_group) = ''operations'' and (
          coalesce(ur.role_id, u.role) in (''Operations Director'', ''Business Unit Manager'', ''Manager'')
          or lower(coalesce(u.department, '''')) like ''%operation%''
        ))
        or (lower(new.target_group) = ''finance'' and (
          coalesce(ur.role_id, u.role) = ''Finance Staff''
          or lower(coalesce(u.department, '''')) like ''%finance%''
        ))
        or lower(coalesce(u.department, '''')) = lower(new.target_group)
      )
  ), inserted as (
    insert into public.announcement_recipients(announcement_id, user_id, notified_at)
    select new.id, eligible.id, now()
    from eligible
    on conflict (announcement_id, user_id) do nothing
    returning user_id
  )
  insert into public.notifications(user_id, type, title, message, link, related_entity_id)
  select
    inserted.user_id::text,
    ''ANNOUNCEMENT_PUBLISHED'',
    case when new.type::text = ''Policy'' then ''New policy announcement'' else ''New announcement'' end,
    new.title,
    ''/helpdesk/announcements?announcementId='' || new.id::text,
    new.id::text
  from inserted;

  return new;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."mark_announcement_read"(uuid)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.mark_announcement_read(p_announcement_id uuid)
 RETURNS announcement_recipients
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  v_actor_id uuid := public.current_hris_user_id();
  v_recipient public.announcement_recipients%rowtype;
begin
  if v_actor_id is null then
    raise exception using errcode = ''42501'', message = ''Authentication is required.'';
  end if;

  update public.announcement_recipients
  set read_at = coalesce(read_at, now())
  where announcement_id = p_announcement_id and user_id = v_actor_id
  returning * into v_recipient;

  if not found then
    raise exception using errcode = ''42501'', message = ''This announcement is not assigned to your account.'';
  end if;

  return v_recipient;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."admin_set_account_lifecycle"(uuid, text, text, boolean)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.admin_set_account_lifecycle(p_target_user_id uuid, p_action text, p_reason text, p_mark_duplicate boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  actor_id uuid := public.current_hris_user_id();
  target_row public.hris_users;
  current_auth_ban timestamptz;
  normalized_action text := lower(trim(coalesce(p_action, '''')));
begin
  if actor_id is null or not public.has_active_role(''Admin'') then
    raise exception ''Forbidden: Admin authority is required.'' using errcode = ''42501'';
  end if;

  select * into target_row
  from public.hris_users
  where id = p_target_user_id
  for update;
  if target_row.id is null then
    raise exception ''Account not found.'' using errcode = ''P0002'';
  end if;
  if normalized_action = ''reactivate'' and lower(target_row.status) = ''active'' then
    raise exception ''The account is already active. No authentication restriction was changed.'';
  end if;
  if normalized_action = ''inactivate'' and lower(target_row.status) = ''inactive'' then
    raise exception ''The account is already inactive.'';
  end if;

  if normalized_action = ''reactivate'' and target_row.auth_user_id is not null then
    select u.banned_until into current_auth_ban
    from auth.users u
    where u.id = target_row.auth_user_id
    for update;

    if current_auth_ban is not null
       and current_auth_ban > now()
       and current_auth_ban <> ''9999-12-31 23:59:59+00''::timestamptz then
      update public.hris_users
      set pre_deactivation_banned_until = current_auth_ban
      where id = p_target_user_id;
    end if;
  end if;

  return public.admin_set_account_lifecycle_core_20260824(
    p_target_user_id,
    p_action,
    p_reason,
    p_mark_duplicate
  );
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"private"."build_coe_document"(coe_requests)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION private.build_coe_document(p_request coe_requests)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  employee_row public.hris_users;
  template_row public.coe_templates;
  business_unit_name text;
  business_unit_color text;
  department_name text;
  purpose_text text;
  source_value text := ''template'';
  fallback_value text;
  template_value jsonb;
  employee_value jsonb;
  request_business_unit_id uuid;
begin
  select u.* into employee_row
  from public.hris_users u
  where u.id = p_request.employee_id;

  request_business_unit_id := coalesce(p_request.employee_business_unit_id, employee_row.business_unit_id);

  select bu.name, bu.color
    into business_unit_name, business_unit_color
  from public.business_units bu
  where bu.id = request_business_unit_id;

  select d.name into department_name
  from public.departments d
  where d.id = coalesce(p_request.employee_department_id, employee_row.department_id);

  if p_request.template_id is not null then
    select t.* into template_row
    from public.coe_templates t
    where t.id = p_request.template_id
      and t.business_unit_id = request_business_unit_id
    limit 1;
  end if;

  if template_row.id is null then
    select t.* into template_row
    from public.coe_templates t
    where t.business_unit_id = request_business_unit_id
    order by
      case when t.is_active and t.status = ''Published'' then 0
           when t.status = ''Published'' then 1
           when t.status = ''Draft'' then 2
           else 3 end,
      t.updated_at desc,
      t.created_at desc
    limit 1;
  end if;

  purpose_text := case p_request.purpose::text
    when ''LOAN_APPLICATION'' then ''loan application''
    when ''VISA_TRAVEL'' then ''visa/travel''
    when ''TRAVEL'' then ''visa/travel''
    when ''VISA_APPLICATION'' then ''visa/travel''
    when ''SCHOOL_EDUCATION'' then ''school/education''
    when ''SCHOOL_APPLICATION'' then ''school/education''
    when ''GOVERNMENT_LEGAL'' then ''government/legal''
    when ''LEGAL_PURPOSES'' then ''government/legal''
    when ''GENERAL_EMPLOYMENT'' then ''general employment''
    when ''OTHERS'' then coalesce(nullif(btrim(p_request.other_purpose_detail), ''''), ''personal purposes'')
    else lower(replace(p_request.purpose::text, ''_'', '' ''))
  end;

  employee_value := jsonb_build_object(
    ''id'', p_request.employee_id,
    ''name'', coalesce(nullif(employee_row.full_name, ''''), p_request.employee_name, ''Employee''),
    ''email'', employee_row.email,
    ''position'', coalesce(nullif(employee_row.position, ''''), nullif(p_request.employee_position, ''''), employee_row.role, ''''),
    ''department'', coalesce(department_name, employee_row.department, ''''),
    ''departmentId'', coalesce(p_request.employee_department_id, employee_row.department_id),
    ''businessUnit'', coalesce(business_unit_name, employee_row.business_unit, ''TNG''),
    ''businessUnitId'', request_business_unit_id,
    ''dateHired'', employee_row.date_hired,
    ''endDate'', employee_row.end_date,
    ''employmentStatus'', coalesce(nullif(employee_row.employment_status, ''''), employee_row.status, ''''),
    ''salary'', coalesce(employee_row.salary_basic, employee_row.rate_amount),
    ''purpose'', purpose_text,
    ''issueDate'', coalesce(p_request.approved_at, now()),
    ''requestDate'', p_request.date_requested
  );

  if template_row.id is not null then
    template_value := jsonb_build_object(
      ''id'', template_row.id,
      ''businessUnitId'', template_row.business_unit_id,
      ''businessUnitName'', coalesce(business_unit_name, ''TNG''),
      ''name'', template_row.name,
      ''description'', template_row.description,
      ''documentTitle'', template_row.document_title,
      ''logoUrl'', template_row.logo_url,
      ''address'', coalesce(template_row.address, ''''),
      ''body'', template_row.body,
      ''signatoryName'', template_row.signatory_name,
      ''signatoryPosition'', template_row.signatory_position,
      ''signatureUrl'', template_row.signature_url,
      ''footerText'', template_row.footer_text,
      ''styleKey'', template_row.style_key,
      ''primaryColor'', coalesce(nullif(template_row.primary_color, ''''), nullif(business_unit_color, ''''), ''#1e3a8a''),
      ''accentColor'', template_row.accent_color,
      ''fontFamily'', template_row.font_family,
      ''layoutSettings'', template_row.layout_settings,
      ''purposes'', to_jsonb(template_row.purposes),
      ''recommendedPurposes'', to_jsonb(template_row.recommended_purposes),
      ''version'', template_row.version,
      ''presetKey'', template_row.preset_key
    );
  else
    source_value := ''fallback'';
    fallback_value := format(
      ''No COE template was available for business unit %s; the protected system fallback was used.'',
      coalesce(business_unit_name, request_business_unit_id::text, ''unknown'')
    );
    template_value := jsonb_build_object(
      ''id'', null,
      ''businessUnitId'', request_business_unit_id,
      ''businessUnitName'', coalesce(business_unit_name, employee_row.business_unit, ''TNG''),
      ''name'', ''Safe Fallback COE'',
      ''description'', ''System fallback used only when no same-business-unit template is available.'',
      ''documentTitle'', ''Certificate of Employment'',
      ''logoUrl'', null,
      ''address'', '''',
      ''body'', ''<p>This is to certify that <strong>{{employee_name}}</strong> is employed by <strong>{{business_unit}}</strong> as <strong>{{position}}</strong> in the {{department}} department from {{date_hired}} {{end_date}}.</p><p>This certification is issued at the employee''''s request for {{purpose}}.</p><p>Issued on {{date_today}}.</p>'',
      ''signatoryName'', ''Human Resources Department'',
      ''signatoryPosition'', ''Authorized Signatory'',
      ''signatureUrl'', null,
      ''footerText'', ''Official document generated by TNG HRIS'',
      ''styleKey'', ''classic-corporate'',
      ''primaryColor'', coalesce(nullif(business_unit_color, ''''), ''#1e3a8a''),
      ''accentColor'', ''#64748b'',
      ''fontFamily'', ''Times New Roman'',
      ''layoutSettings'', jsonb_build_object(
        ''marginTopMm'', 20, ''marginRightMm'', 20, ''marginBottomMm'', 20,
        ''marginLeftMm'', 20, ''lineHeight'', 1.6, ''textAlignment'', ''justify'',
        ''logoAlignment'', ''center'', ''logoHeightMm'', 24
      ),
      ''purposes'', ''[]''::jsonb,
      ''recommendedPurposes'', ''[]''::jsonb,
      ''version'', 1,
      ''presetKey'', ''protected-fallback''
    );
  end if;

  return jsonb_build_object(
    ''templateId'', template_row.id,
    ''generationSource'', source_value,
    ''fallbackReason'', fallback_value,
    ''template'', template_value,
    ''employee'', employee_value
  );
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."admin_set_account_lifecycle_core_20260824"(uuid, text, text, boolean)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.admin_set_account_lifecycle_core_20260824(p_target_user_id uuid, p_action text, p_reason text, p_mark_duplicate boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  actor_id uuid := public.current_hris_user_id();
  actor_email text;
  target_row public.hris_users;
  before_state jsonb;
  after_state jsonb;
  auth_banned_before timestamptz;
  auth_banned_after timestamptz;
  active_admin_count integer;
  revoked_session_count integer := 0;
  revoked_refresh_token_count integer := 0;
  normalized_action text := lower(trim(coalesce(p_action, '''')));
begin
  if actor_id is null or not public.has_active_role(''Admin'') then
    raise exception ''Forbidden: Admin authority is required.'' using errcode = ''42501'';
  end if;
  if actor_id = p_target_user_id then
    raise exception ''You cannot change the lifecycle status of your own account.'' using errcode = ''42501'';
  end if;
  if length(trim(coalesce(p_reason, ''''))) < 5 then
    raise exception ''A reason of at least 5 characters is required.'';
  end if;
  if normalized_action not in (''inactivate'', ''reactivate'') then
    raise exception ''Unsupported account lifecycle action: %'', p_action;
  end if;

  select * into target_row
  from public.hris_users
  where id = p_target_user_id
  for update;
  if target_row.id is null then
    raise exception ''Account not found.'' using errcode = ''P0002'';
  end if;
  if normalized_action = ''reactivate'' and target_row.end_date is not null then
    raise exception ''This employee has an End Date. Reactivate the employee from the Employee profile so employment and account status remain consistent.'';
  end if;

  if normalized_action = ''inactivate'' and exists (
    select 1 from public.user_roles ur
    where ur.user_id = p_target_user_id and ur.role_id = ''Admin'' and ur.is_active
  ) then
    select count(distinct ur.user_id) into active_admin_count
    from public.user_roles ur
    join public.hris_users u on u.id = ur.user_id
    where ur.role_id = ''Admin'' and ur.is_active and lower(u.status) = ''active'';
    if active_admin_count <= 1 then
      raise exception ''Cannot inactivate the final active Admin.'' using errcode = ''42501'';
    end if;
  end if;

  if target_row.auth_user_id is not null then
    select u.banned_until into auth_banned_before
    from auth.users u
    where u.id = target_row.auth_user_id
    for update;
    if not found then
      raise exception ''The linked authentication account was not found; no changes were saved.'';
    end if;
  end if;

  select email into actor_email from public.hris_users where id = actor_id;
  before_state := jsonb_build_object(
    ''status'', target_row.status,
    ''isDuplicate'', target_row.is_duplicate,
    ''reason'', target_row.account_lifecycle_reason,
    ''authBannedUntil'', auth_banned_before,
    ''accountAccess'', case
      when target_row.auth_user_id is null then ''No linked auth account''
      when lower(target_row.status) <> ''active'' then ''Disabled''
      when auth_banned_before is not null and auth_banned_before > now() then ''Disabled''
      else ''Enabled''
    end
  );

  if normalized_action = ''inactivate'' then
    if target_row.auth_user_id is not null then
      update auth.users
      set banned_until = ''9999-12-31 23:59:59+00''::timestamptz,
          updated_at = now()
      where id = target_row.auth_user_id;

      update auth.refresh_tokens
      set revoked = true,
          updated_at = now()
      where user_id = target_row.auth_user_id::text
        and not revoked;
      get diagnostics revoked_refresh_token_count = row_count;

      delete from auth.sessions where user_id = target_row.auth_user_id;
      get diagnostics revoked_session_count = row_count;
      auth_banned_after := ''9999-12-31 23:59:59+00''::timestamptz;
    end if;

    update public.hris_users
    set status = ''Inactive'',
        is_duplicate = coalesce(p_mark_duplicate, false),
        pre_deactivation_banned_until = case
          when lower(status) = ''active'' then auth_banned_before
          else coalesce(pre_deactivation_banned_until, auth_banned_before)
        end,
        account_lifecycle_reason = trim(p_reason),
        account_inactivated_at = now(),
        account_inactivated_by = actor_id,
        duplicate_marked_at = case when p_mark_duplicate then now() else duplicate_marked_at end,
        duplicate_marked_by = case when p_mark_duplicate then actor_id else duplicate_marked_by end
    where id = p_target_user_id;
  else
    auth_banned_after := case
      when target_row.pre_deactivation_banned_until is not null
        and target_row.pre_deactivation_banned_until > now()
      then target_row.pre_deactivation_banned_until
      else null
    end;

    if target_row.auth_user_id is not null then
      update auth.users
      set banned_until = auth_banned_after,
          updated_at = now()
      where id = target_row.auth_user_id;

      update auth.refresh_tokens
      set revoked = true,
          updated_at = now()
      where user_id = target_row.auth_user_id::text
        and not revoked;
      get diagnostics revoked_refresh_token_count = row_count;

      delete from auth.sessions where user_id = target_row.auth_user_id;
      get diagnostics revoked_session_count = row_count;
    end if;

    update public.hris_users
    set status = ''Active'',
        is_duplicate = false,
        pre_deactivation_banned_until = null,
        account_lifecycle_reason = trim(p_reason),
        account_reactivated_at = now(),
        account_reactivated_by = actor_id
    where id = p_target_user_id;
  end if;

  select jsonb_build_object(
    ''status'', u.status,
    ''isDuplicate'', u.is_duplicate,
    ''reason'', u.account_lifecycle_reason,
    ''authBannedUntil'', auth_banned_after,
    ''accountAccess'', case
      when u.auth_user_id is null then ''No linked auth account''
      when auth_banned_after is not null and auth_banned_after > now() then ''Disabled''
      else ''Enabled; fresh sign-in required''
    end
  ) into after_state
  from public.hris_users u
  where u.id = p_target_user_id;

  insert into public.audit_logs(user_id, user_email, action, entity, entity_id, details)
  values (
    actor_id::text,
    actor_email,
    upper(normalized_action),
    ''UserAccount'',
    p_target_user_id::text,
    jsonb_build_object(
      ''sourceModule'', ''Admin/UserManagement'',
      ''reason'', trim(p_reason),
      ''employeeName'', target_row.full_name,
      ''email'', target_row.email,
      ''businessUnit'', target_row.business_unit,
      ''before'', before_state,
      ''after'', after_state,
      ''revokedSessions'', revoked_session_count,
      ''revokedRefreshTokens'', revoked_refresh_token_count
    )::text
  );
  return after_state;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"private"."conditional_time_approval_config"()') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION private.conditional_time_approval_config()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''''
AS $function$
  select coalesce(
    (select config_value from public.approver_configs where config_key=''conditional_time_approvals''),
    jsonb_build_object(
      ''user_ids'',''[]''::jsonb,''user_names'',''[]''::jsonb,''required_user_ids'',''[]''::jsonb,
      ''required_bod_approvals'',1,''leave_days_per_remaining_month'',1,
      ''wfh_days_per_month'',4,''weekly_total_hours'',50
    )
  )
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"private"."is_direct_reporting_manager"(uuid, uuid)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION private.is_direct_reporting_manager(p_actor_id uuid, p_employee_id uuid)
