DO $parity$
BEGIN
  IF to_regprocedure('"public"."can_manage_employee_documents"(uuid)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.can_manage_employee_documents(p_target_user_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
