DO $parity$
BEGIN
  IF to_regprocedure('"public"."submit_employee_award"(uuid, uuid, text, uuid, uuid, uuid[])') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.submit_employee_award(p_employee_id uuid, p_award_template_id uuid, p_notes text, p_business_unit_id uuid, p_department_id uuid, p_approver_ids uuid[])
 RETURNS employee_awards
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
