  steps jsonb := ''[]''::jsonb;
  created_award public.employee_awards;
  step_order integer := 0;
  bod_count integer := 0;
begin
  if actor_id is null or not (
    public.is_hr_or_admin()
    or public.has_feature_permission(''Evaluation'', ''manage'')
    or public.has_feature_permission(''Evaluation'', ''create'')
  ) then
    raise exception ''You do not have permission to submit awards.'' using errcode = ''42501'';
  end if;
  if coalesce(cardinality(p_approver_ids), 0) = 0 then
    raise exception ''At least one active Board of Director approver is required.'';
  end if;
  if not exists (select 1 from public.hris_users where id = p_employee_id and lower(status::text) = ''active'') then
    raise exception ''The selected employee is unavailable or inactive.'';
  end if;
  if not exists (
    select 1 from public.award_templates
    where id = p_award_template_id and is_active and template_status = ''published''
  ) then
    raise exception ''The selected award template is unavailable or not published.'';
  end if;

  select full_name, business_unit_id, department_id
    into employee_name, employee_business_unit_id, employee_department_id
  from public.hris_users where id = p_employee_id;
  if p_business_unit_id is not null and p_business_unit_id is distinct from employee_business_unit_id then
    raise exception ''The selected employee does not belong to that business unit.'';
  end if;
  if p_department_id is not null and p_department_id is distinct from employee_department_id then
    raise exception ''The selected employee does not belong to that department.'';
  end if;
  select title into template_title from public.award_templates where id = p_award_template_id;

  foreach selected_approver_id in array p_approver_ids loop
    if selected_approver_id is null or exists (
      select 1 from jsonb_array_elements(steps) step where step->>''userId'' = selected_approver_id::text
    ) then continue; end if;
    role_snapshot := private.workflow_user_role_snapshot(selected_approver_id);
    if role_snapshot not in (''Board of Director'',''GeneralManager'',''Manager'',''Business Unit Manager'') then
      raise exception ''Award approvers must be an active BOD, General Manager, Manager, or Business Unit Manager.'';
    end if;
    select full_name into approver_name from public.hris_users where id = selected_approver_id;
    step_order := step_order + 1;
    if role_snapshot = ''Board of Director'' then bod_count := bod_count + 1; end if;
    steps := steps || jsonb_build_array(jsonb_build_object(
      ''userId'', selected_approver_id,
      ''userName'', approver_name,
      ''status'', ''Pending'',
      ''order'', step_order,
      ''roleSnapshot'', role_snapshot,
      ''isBod'', role_snapshot = ''Board of Director'',
      ''isRequired'', true
    ));
  end loop;
  if bod_count = 0 then
    raise exception ''At least one active Board of Director approver is required.'';
  end if;

  insert into public.employee_awards(
    employee_id, award_template_id, notes, business_unit_id, department_id,
    certificate_snapshot_url, created_by_user_id, status, submitted_at, level,
    approver_id, approver_steps
  ) values (
    p_employee_id, p_award_template_id, nullif(btrim(p_notes), ''''), employee_business_unit_id, employee_department_id,
    null, actor_id, ''PendingApproval'', now(), ''Bronze'', (steps->0->>''userId'')::uuid, steps
  ) returning * into created_award;

  for selected_approver_id in select (step->>''userId'')::uuid from jsonb_array_elements(steps) step loop
    perform private.award_notify(
      selected_approver_id, ''AWARD_APPROVAL_REQUEST'', ''Award Approval Needed'',
      format(''%s was nominated for "%s". Please review.'', employee_name, template_title),
      created_award.id, ''award-approval:'' || created_award.id::text || '':'' || selected_approver_id::text
    );
  end loop;
  perform private.award_audit(''CREATE'', created_award.id, format(
    ''Submitted %s for %s with immutable approval snapshot; %s approver(s), %s BOD.'',
    template_title, employee_name, step_order, bod_count
  ));
  return created_award;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"private"."workflow_user_has_role"(uuid, text)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION private.workflow_user_has_role(p_user_id uuid, p_role text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''''
AS $function$
  select exists (
    select 1 from public.hris_users user_row
    where user_row.id = p_user_id
      and lower(user_row.status::text) = ''active''
      and (
        user_row.role::text = p_role
        or exists (
          select 1 from public.user_roles assignment
          where assignment.user_id = user_row.id
            and assignment.role_id::text = p_role
            and assignment.is_active
        )
      )
  )
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"private"."workflow_user_role_snapshot"(uuid)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION private.workflow_user_role_snapshot(p_user_id uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''''
AS $function$
  select case
    when private.workflow_user_has_role(p_user_id, ''Board of Director'') then ''Board of Director''
    when private.workflow_user_has_role(p_user_id, ''HR Manager'') then ''HR Manager''
    when private.workflow_user_has_role(p_user_id, ''GeneralManager'') then ''GeneralManager''
    when private.workflow_user_has_role(p_user_id, ''Business Unit Manager'') then ''Business Unit Manager''
    when private.workflow_user_has_role(p_user_id, ''Manager'') then ''Manager''
    else null
  end
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."enforce_employee_award_bod_gate"()') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.enforce_employee_award_bod_gate()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''''
AS $function$
begin
  if new.status::text in (''Approved'',''Issued'') and old.status::text not in (''Approved'',''Issued'') then
    if not exists (
      select 1 from jsonb_array_elements(coalesce(new.approver_steps, ''[]''::jsonb)) step
      where (coalesce((step->>''isBod'')::boolean, false) or step->>''roleSnapshot'' = ''Board of Director'')
        and lower(step->>''status'') = ''approved''
    ) then
      raise exception ''At least one completed Board of Director approval is required before an award can be finalized.'';
    end if;
  end if;
  return new;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"private"."has_assigned_feature_permission"(uuid, text, text)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION private.has_assigned_feature_permission(p_user_id uuid, p_resource text, p_action text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''''
AS $function$
  select exists (
    select 1
    from public.user_roles ur
    join public.roles r on r.id = ur.role_id and r.is_active
    join public.role_permissions rp on rp.role_id = ur.role_id
    join public.resources res on res.id = rp.resource_id and res.is_active
    where ur.user_id = p_user_id
      and ur.is_active
      and rp.resource_id = p_resource
      and (p_action = any(rp.permissions) or ''manage'' = any(rp.permissions))
  )
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"private"."prepare_asset_request_workflow"()') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION private.prepare_asset_request_workflow()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  actor_id uuid := public.current_hris_user_id();
  resolved_manager_id uuid;
begin
  if new.request_type::text <> ''Request'' then
    return new;
  end if;

  if actor_id is null then
    raise exception ''Sign in before submitting an asset request.'' using errcode = ''42501'';
  end if;
  if new.employee_id <> actor_id and not public.is_system_admin() and not public.is_hr_or_admin() then
    raise exception ''Asset requests can only be submitted for your own account.'' using errcode = ''42501'';
  end if;

  resolved_manager_id := private.resolve_direct_manager_id(new.employee_id);
  if resolved_manager_id is null then
    raise exception ''A direct reporting manager must be assigned before this asset request can be submitted.'' using errcode = ''23514'';
  end if;
  if resolved_manager_id = new.employee_id then
    raise exception ''The requester cannot be their own direct reporting manager.'' using errcode = ''23514'';
  end if;

  new.manager_id := resolved_manager_id;
  new.status := ''Pending''::public.asset_request_status;
  new.approval_stage := ''DIRECT_MANAGER'';
  new.required_bod_approvals := private.asset_request_required_bod_approvals();
  new.bod_approval_count := 0;
  new.manager_approved_by := null;
  new.manager_approved_at := null;
  new.approved_at := null;
  new.rejected_at := null;
  new.rejection_reason := null;
  new.approval_issue := null;
  return new;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"private"."initialize_asset_request_workflow"()') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION private.initialize_asset_request_workflow()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  actor_id uuid := coalesce(public.current_hris_user_id(), new.employee_id);
  actor_role text;
  manager_assignment_id uuid;
begin
  if new.request_type::text <> ''Request'' then
    return new;
  end if;

  select coalesce(actor.role, ''Employee'') into actor_role
  from public.hris_users actor where actor.id = actor_id;

  insert into public.asset_request_approval_assignments(
    request_id, approval_stage, approver_user_id, approver_role, status, assigned_at
  ) values (
    new.id, ''DIRECT_MANAGER'', new.manager_id, ''Direct Reporting Manager'', ''Pending'', new.requested_at
  )
  on conflict (request_id, approval_stage, approver_user_id)
  do update set status = ''Pending''
  returning id into manager_assignment_id;

  insert into public.asset_request_approval_history(
    request_id, assignment_id, actor_user_id, actor_role, approval_stage, action, comments, created_at
  ) values (
    new.id, manager_assignment_id, actor_id, coalesce(actor_role, ''Employee''),
    ''DIRECT_MANAGER'', ''Submitted'', ''Submitted for direct manager approval.'', new.requested_at
  );

  insert into public.notifications(
    user_id, type, title, message, link, related_entity_id, is_read, dedupe_key
  ) values (
    new.manager_id::text,
    ''ASSET_REQUEST_SUBMITTED'',
    ''Asset Request Awaiting Manager Approval'',
    format(''%s requested %s.'', new.employee_name, new.asset_description),
    ''/approvals?type=asset&item='' || new.id::text,
    new.id::text,
    false,
    ''asset-request:'' || new.id::text || '':DIRECT_MANAGER:'' || new.manager_id::text
  ) on conflict (user_id, dedupe_key) do nothing;

  insert into public.audit_logs(user_id, user_email, action, entity, entity_id, details)
  select actor_id::text, actor.email, ''SUBMIT'', ''AssetRequest'', new.id::text,
    jsonb_build_object(
      ''approvalStage'', ''DIRECT_MANAGER'',
      ''managerId'', new.manager_id,
      ''requiredBodApprovals'', new.required_bod_approvals
    )::text
  from public.hris_users actor where actor.id = actor_id;

  return new;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."get_asset_request_approval_config"()') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.get_asset_request_approval_config()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''''
AS $function$
  select jsonb_build_object(
    ''required_bod_approvals'', private.asset_request_required_bod_approvals(),
    ''active_bod_count'', (
      select count(*)
      from public.hris_users candidate
      where private.is_asset_request_bod(candidate.id)
    )
  )
  where auth.uid() is not null
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."process_asset_request_approval"(uuid, text, text)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.process_asset_request_approval(p_request_id uuid, p_action text, p_comments text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  actor_id uuid := public.current_hris_user_id();
  actor_row public.hris_users;
  request_row public.asset_requests;
  current_assignment public.asset_request_approval_assignments;
  normalized_action text := upper(btrim(coalesce(p_action, '''')));
  approved_bod_count smallint;
  active_bod_count integer;
  completed boolean := false;
begin
  if actor_id is null then
    raise exception ''Sign in before processing an asset request.'' using errcode = ''42501'';
  end if;
  select * into actor_row from public.hris_users where id = actor_id;
  if actor_row.id is null or lower(btrim(coalesce(actor_row.status, ''''))) <> ''active'' then
    raise exception ''Only an active HRIS user can process an asset request.'' using errcode = ''42501'';
  end if;
  if normalized_action not in (''APPROVE'', ''REJECT'') then
    raise exception ''Action must be APPROVE or REJECT.'' using errcode = ''22023'';
  end if;
  if normalized_action = ''REJECT'' and nullif(btrim(coalesce(p_comments, '''')), '''') is null then
    raise exception ''A rejection reason is required.'' using errcode = ''22023'';
  end if;

  select * into request_row
  from public.asset_requests
  where id = p_request_id
  for update;
  if request_row.id is null or request_row.request_type::text <> ''Request'' then
    raise exception ''Asset request not found.'' using errcode = ''P0002'';
  end if;
  if request_row.status::text <> ''Pending'' or request_row.approval_stage not in (''DIRECT_MANAGER'', ''BOD'') then
    raise exception ''This asset request is no longer awaiting approval.'' using errcode = ''22023'';
  end if;

  select * into current_assignment
  from public.asset_request_approval_assignments assignment
  where assignment.request_id = request_row.id
    and assignment.approval_stage = request_row.approval_stage
    and assignment.approver_user_id = actor_id
  for update;

  if current_assignment.id is null then
    if request_row.approval_stage = ''BOD'' and exists (
      select 1 from public.asset_request_approval_assignments assignment
      where assignment.request_id = request_row.id
        and assignment.approval_stage = ''BOD''
        and assignment.approver_user_id = actor_id
        and assignment.status = ''Approved''
    ) then
      raise exception ''You already approved this asset request.'' using errcode = ''22023'';
    end if;
    raise exception ''This asset request is not assigned to you at the current stage.'' using errcode = ''42501'';
  end if;
  if current_assignment.status = ''Approved'' and request_row.approval_stage = ''BOD'' then
    raise exception ''You already approved this asset request.'' using errcode = ''22023'';
  end if;
  if current_assignment.status <> ''Pending'' then
    raise exception ''This approval task has already been processed.'' using errcode = ''22023'';
  end if;
  if request_row.approval_stage = ''DIRECT_MANAGER'' and request_row.manager_id <> actor_id then
    raise exception ''Only the employee''''s direct reporting manager can complete the first approval.'' using errcode = ''42501'';
  end if;
  if request_row.approval_stage = ''BOD'' and not private.is_asset_request_bod(actor_id) then
    raise exception ''Only an active Board of Director user can complete this approval.'' using errcode = ''42501'';
  end if;

  if normalized_action = ''REJECT'' then
    update public.asset_request_approval_assignments
    set status = ''Rejected'', acted_at = now(), comments = btrim(p_comments)
    where id = current_assignment.id;

    update public.asset_request_approval_assignments
    set status = ''Closed'', acted_at = now(), comments = ''Closed after rejection by another required approver.''
    where request_id = request_row.id and status = ''Pending'' and id <> current_assignment.id;

    perform set_config(''app.asset_request_workflow_mutation'', ''on'', true);
    update public.asset_requests
    set status = ''Rejected''::public.asset_request_status,
        approval_stage = ''REJECTED'',
        manager_notes = case when request_row.approval_stage = ''DIRECT_MANAGER'' then btrim(p_comments) else manager_notes end,
        rejection_reason = btrim(p_comments),
        rejected_at = now(),
        approval_issue = null,
        updated_at = now()
    where id = request_row.id;
    perform set_config(''app.asset_request_workflow_mutation'', '''', true);

    insert into public.asset_request_approval_history(
      request_id, assignment_id, actor_user_id, actor_role, approval_stage, action, comments
    ) values (
      request_row.id, current_assignment.id, actor_id,
      case when request_row.approval_stage = ''DIRECT_MANAGER'' then ''Direct Reporting Manager'' else ''Board of Director'' end,
      request_row.approval_stage, ''Rejected'', btrim(p_comments)
    );

    update public.notifications
    set is_read = true
    where related_entity_id = request_row.id::text
      and dedupe_key like ''asset-request:'' || request_row.id::text || '':%'';

    insert into public.notifications(
      user_id, type, title, message, link, related_entity_id, is_read, dedupe_key
    ) values (
      request_row.employee_id::text,
      ''ASSET_UPDATE'',
      ''Asset Request Rejected'',
      format(''Your asset request for %s was rejected: %s'', request_row.asset_description, btrim(p_comments)),
      ''/employees/asset-management/asset-requests?requestId='' || request_row.id::text,
      request_row.id::text,
      false,
      ''asset-request:'' || request_row.id::text || '':REJECTED''
    ) on conflict (user_id, dedupe_key) do update
      set message = excluded.message, link = excluded.link, is_read = false, created_at = now();
  elsif request_row.approval_stage = ''DIRECT_MANAGER'' then
    select count(*) into active_bod_count
    from public.hris_users candidate
    where private.is_asset_request_bod(candidate.id);
    if active_bod_count < request_row.required_bod_approvals then
      raise exception ''This request needs % active BOD approvers, but only % are available.'', request_row.required_bod_approvals, active_bod_count using errcode = ''23514'';
    end if;

    update public.asset_request_approval_assignments
    set status = ''Approved'', acted_at = now(), comments = nullif(btrim(coalesce(p_comments, '''')), '''')
    where id = current_assignment.id;

    insert into public.asset_request_approval_assignments(
      request_id, approval_stage, approver_user_id, approver_role, status
    )
    select request_row.id, ''BOD'', candidate.id, ''Board of Director'', ''Pending''
    from public.hris_users candidate
    where private.is_asset_request_bod(candidate.id)
    on conflict (request_id, approval_stage, approver_user_id) do nothing;

    perform set_config(''app.asset_request_workflow_mutation'', ''on'', true);
    update public.asset_requests
    set approval_stage = ''BOD'',
        manager_approved_by = actor_id,
        manager_approved_at = now(),
        manager_notes = nullif(btrim(coalesce(p_comments, '''')), ''''),
        approval_issue = null,
        updated_at = now()
    where id = request_row.id;
    perform set_config(''app.asset_request_workflow_mutation'', '''', true);

    insert into public.asset_request_approval_history(
      request_id, assignment_id, actor_user_id, actor_role, approval_stage, action, comments
    ) values (
      request_row.id, current_assignment.id, actor_id, ''Direct Reporting Manager'',
      ''DIRECT_MANAGER'', ''Approved'', nullif(btrim(coalesce(p_comments, '''')), '''')
    );

    update public.notifications
    set is_read = true
    where user_id = actor_id::text
      and dedupe_key = ''asset-request:'' || request_row.id::text || '':DIRECT_MANAGER:'' || actor_id::text;

    insert into public.notifications(
      user_id, type, title, message, link, related_entity_id, is_read, dedupe_key
    )
    select assignment.approver_user_id::text,
           ''ASSET_REQUEST_SUBMITTED'',
           ''Asset Request Awaiting BOD Approval'',
           format(''%s requested %s. 0 of %s BOD approvals recorded.'', request_row.employee_name, request_row.asset_description, request_row.required_bod_approvals),
           ''/approvals?type=asset&item='' || request_row.id::text,
           request_row.id::text,
           false,
           ''asset-request:'' || request_row.id::text || '':BOD:'' || assignment.approver_user_id::text
    from public.asset_request_approval_assignments assignment
    where assignment.request_id = request_row.id
      and assignment.approval_stage = ''BOD''
      and assignment.status = ''Pending''
    on conflict (user_id, dedupe_key) do update
      set message = excluded.message, link = excluded.link, is_read = false, created_at = now();
  else
    update public.asset_request_approval_assignments
    set status = ''Approved'', acted_at = now(), comments = nullif(btrim(coalesce(p_comments, '''')), '''')
    where id = current_assignment.id;

    select count(distinct assignment.approver_user_id)::smallint into approved_bod_count
    from public.asset_request_approval_assignments assignment
    where assignment.request_id = request_row.id
      and assignment.approval_stage = ''BOD''
      and assignment.status = ''Approved'';
    completed := approved_bod_count >= request_row.required_bod_approvals;

    if completed then
      update public.asset_request_approval_assignments
      set status = ''Closed'', acted_at = now(), comments = ''Closed after the required BOD approvals were completed.''
      where request_id = request_row.id
        and approval_stage = ''BOD''
        and status = ''Pending'';
    end if;

    perform set_config(''app.asset_request_workflow_mutation'', ''on'', true);
    update public.asset_requests
    set bod_approval_count = approved_bod_count,
        status = case when completed then ''Approved''::public.asset_request_status else status end,
        approval_stage = case when completed then ''COMPLETED'' else ''BOD'' end,
        approved_at = case when completed then now() else approved_at end,
        approval_issue = null,
        updated_at = now()
    where id = request_row.id;
    perform set_config(''app.asset_request_workflow_mutation'', '''', true);

    insert into public.asset_request_approval_history(
      request_id, assignment_id, actor_user_id, actor_role, approval_stage, action, comments
    ) values (
      request_row.id, current_assignment.id, actor_id, ''Board of Director'',
      ''BOD'', ''Approved'', nullif(btrim(coalesce(p_comments, '''')), '''')
    );

    update public.notifications
    set is_read = true
    where user_id = actor_id::text
      and dedupe_key = ''asset-request:'' || request_row.id::text || '':BOD:'' || actor_id::text;

    if completed then
      update public.notifications
      set is_read = true
      where related_entity_id = request_row.id::text
        and dedupe_key like ''asset-request:'' || request_row.id::text || '':BOD:%'';

      insert into public.notifications(
        user_id, type, title, message, link, related_entity_id, is_read, dedupe_key
      ) values (
        request_row.employee_id::text,
        ''ASSET_UPDATE'',
        ''Asset Request Approved'',
        format(''Your asset request for %s completed all required approvals.'', request_row.asset_description),
        ''/employees/asset-management/asset-requests?requestId='' || request_row.id::text,
        request_row.id::text,
        false,
        ''asset-request:'' || request_row.id::text || '':APPROVED''
      ) on conflict (user_id, dedupe_key) do update
        set message = excluded.message, link = excluded.link, is_read = false, created_at = now();
    else
      update public.notifications notification
      set message = format(''%s requested %s. %s of %s BOD approvals recorded.'', request_row.employee_name, request_row.asset_description, approved_bod_count, request_row.required_bod_approvals),
          is_read = false,
          created_at = now()
      where notification.related_entity_id = request_row.id::text
        and notification.dedupe_key like ''asset-request:'' || request_row.id::text || '':BOD:%''
        and notification.user_id <> actor_id::text;
    end if;
  end if;

  insert into public.audit_logs(user_id, user_email, action, entity, entity_id, details)
  values (
    actor_id::text,
    actor_row.email,
    normalized_action,
    ''AssetRequest'',
    request_row.id::text,
    jsonb_build_object(
      ''stage'', request_row.approval_stage,
      ''comments'', nullif(btrim(coalesce(p_comments, '''')), ''''),
      ''requiredBodApprovals'', request_row.required_bod_approvals,
      ''bodApprovalCount'', coalesce(approved_bod_count, request_row.bod_approval_count),
      ''completed'', completed
    )::text
  );

  return public.get_asset_request_approval_detail(request_row.id);
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."save_asset_request_approval_config"(integer)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.save_asset_request_approval_config(p_required_bod_approvals integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  actor_id uuid := public.current_hris_user_id();
  actor_email text;
  active_bod_count integer;
  previous_value jsonb;
  normalized jsonb;
begin
  if actor_id is null or not public.is_system_admin() then
    raise exception ''Only an active system Admin can change Asset Request approval settings.'' using errcode = ''42501'';
  end if;
  if p_required_bod_approvals not in (1, 2) then
    raise exception ''Required BOD approvals must be 1 or 2.'' using errcode = ''22023'';
  end if;

  select count(*) into active_bod_count
  from public.hris_users candidate
  where private.is_asset_request_bod(candidate.id);
  if active_bod_count < p_required_bod_approvals then
    raise exception ''At least % active BOD users are required for this setting.'', p_required_bod_approvals using errcode = ''23514'';
  end if;

  select config_value into previous_value
  from public.approver_configs
  where config_key = ''asset_request_approvals''
  for update;

  normalized := jsonb_build_object(''required_bod_approvals'', p_required_bod_approvals);
  insert into public.approver_configs(config_key, config_value, updated_at)
  values (''asset_request_approvals'', normalized, now())
  on conflict (config_key) do update
    set config_value = excluded.config_value,
        updated_at = excluded.updated_at;

  select email into actor_email from public.hris_users where id = actor_id;
  insert into public.audit_logs(user_id, user_email, action, entity, entity_id, details)
  values (
    actor_id::text, actor_email, ''UPDATE'', ''AssetRequestApprovalConfig'', ''asset_request_approvals'',
    jsonb_build_object(''before'', previous_value, ''after'', normalized, ''inFlightRequestsChanged'', false)::text
  );

  return public.get_asset_request_approval_config();
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."get_my_asset_request_approval_queue"()') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.get_my_asset_request_approval_queue()
 RETURNS TABLE(request_id uuid, employee_id uuid, employee_name text, asset_description text, requested_at timestamp with time zone, business_unit_id uuid, department_id uuid, approval_stage text, current_step text, required_bod_approvals smallint, bod_approval_count smallint, approval_progress text, is_actionable boolean, viewer_action_status text, approval_issue text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''''
AS $function$
  with actor as (
    select viewer.id, private.is_asset_request_bod(viewer.id) as is_bod
    from public.hris_users viewer
    where viewer.id = public.current_hris_user_id()
      and lower(btrim(coalesce(viewer.status, ''''))) = ''active''
  )
  select request.id,
         request.employee_id,
         request.employee_name,
         request.asset_description,
         request.requested_at,
         employee.business_unit_id,
         employee.department_id,
         request.approval_stage,
         case
           when request.approval_stage = ''DIRECT_MANAGER'' and request.manager_id = actor.id then ''Direct Manager Approval''
           when request.approval_stage = ''DIRECT_MANAGER'' then ''Waiting for Direct Manager Approval''
           when request.approval_stage = ''BOD'' and coalesce(viewer_assignment.status, '''') = ''Approved'' then ''Waiting for remaining BOD approval''
           else ''BOD Approval''
         end,
         request.required_bod_approvals,
         request.bod_approval_count,
         format(''%s of %s BOD approvals'', request.bod_approval_count, request.required_bod_approvals),
         case
           when request.approval_stage = ''DIRECT_MANAGER'' then request.manager_id = actor.id and coalesce(viewer_assignment.status, ''Pending'') = ''Pending''
           when request.approval_stage = ''BOD'' then coalesce(viewer_assignment.status, '''') = ''Pending''
           else false
         end,
         viewer_assignment.status,
         request.approval_issue
  from public.asset_requests request
  join public.hris_users employee on employee.id = request.employee_id
  cross join actor
  left join lateral (
    select assignment.status
    from public.asset_request_approval_assignments assignment
    where assignment.request_id = request.id
      and assignment.approval_stage = request.approval_stage
      and assignment.approver_user_id = actor.id
    order by assignment.assigned_at desc, assignment.id
    limit 1
  ) viewer_assignment on true
  where request.request_type::text = ''Request''
    and request.status::text = ''Pending''
    and request.approval_stage in (''DIRECT_MANAGER'', ''BOD'')
    and (
      (request.approval_stage = ''DIRECT_MANAGER'' and request.manager_id = actor.id)
      or actor.is_bod
    )
  order by request.requested_at desc, request.id
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."get_my_request_summaries_v2"()') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.get_my_request_summaries_v2()
 RETURNS TABLE(id uuid, request_type text, submitted_at timestamp with time zone, status text, detail_link text, current_stage text, progress_label text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''''
AS $function$
  select summary.id,
         summary.request_type,
         summary.submitted_at,
         summary.status,
         summary.detail_link,
         case
           when summary.request_type <> ''Asset'' or request.request_type::text <> ''Request'' then null
           when request.approval_stage = ''DIRECT_MANAGER'' then ''Waiting for Direct Manager Approval''
           when request.approval_stage = ''BOD'' then ''BOD Approval''
           when request.approval_stage = ''COMPLETED'' then ''Completed''
           when request.approval_stage = ''REJECTED'' then ''Rejected''
           else ''Not configured''
         end,
         case
           when summary.request_type = ''Asset'' and request.request_type::text = ''Request''
             then format(''%s of %s BOD approvals'', request.bod_approval_count, request.required_bod_approvals)
           else null
         end
  from public.get_my_request_summaries() summary
  left join public.asset_requests request
    on summary.request_type = ''Asset'' and request.id = summary.id
  order by summary.submitted_at desc nulls last
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."get_asset_request_approval_detail"(uuid)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.get_asset_request_approval_detail(p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  actor_id uuid := public.current_hris_user_id();
  actor_is_bod boolean;
  request_row public.asset_requests;
  employee_row public.hris_users;
  manager_row public.hris_users;
  viewer_assignment public.asset_request_approval_assignments;
  can_view boolean;
  can_act boolean;
begin
  select * into request_row from public.asset_requests where id = p_request_id;
  if request_row.id is null or request_row.request_type::text <> ''Request'' then
    raise exception ''Asset request not found.'' using errcode = ''P0002'';
  end if;
  if actor_id is null then
    raise exception ''Sign in to view this asset request.'' using errcode = ''42501'';
  end if;

  actor_is_bod := private.is_asset_request_bod(actor_id);
  can_view := actor_id = request_row.employee_id
    or (request_row.manager_id is not null and actor_id = request_row.manager_id)
    or actor_is_bod
    or public.is_hr_or_admin()
    or public.is_system_admin();
  if not can_view then
    raise exception ''You are not authorized to view this asset request.'' using errcode = ''42501'';
  end if;

  select * into employee_row from public.hris_users where id = request_row.employee_id;
  select * into manager_row from public.hris_users where id = request_row.manager_id;
  select * into viewer_assignment
  from public.asset_request_approval_assignments assignment
  where assignment.request_id = request_row.id
    and assignment.approval_stage = request_row.approval_stage
    and assignment.approver_user_id = actor_id
  order by assignment.assigned_at desc, assignment.id
  limit 1;

  can_act := request_row.status::text = ''Pending''
    and request_row.approval_stage in (''DIRECT_MANAGER'', ''BOD'')
    and viewer_assignment.id is not null
    and viewer_assignment.status = ''Pending'';

  return jsonb_build_object(
    ''request'', jsonb_build_object(
      ''id'', request_row.id,
      ''employeeId'', request_row.employee_id,
      ''employeeName'', request_row.employee_name,
      ''assetDescription'', request_row.asset_description,
      ''justification'', request_row.justification,
      ''status'', request_row.status::text,
      ''requestedAt'', request_row.requested_at,
      ''approvalStage'', request_row.approval_stage,
      ''currentStep'', case
        when request_row.approval_stage = ''DIRECT_MANAGER'' and actor_id = request_row.manager_id then ''Direct Manager Approval''
        when request_row.approval_stage = ''DIRECT_MANAGER'' then ''Waiting for Direct Manager Approval''
        when request_row.approval_stage = ''BOD'' and viewer_assignment.status = ''Approved'' then ''Waiting for remaining BOD approval''
        when request_row.approval_stage = ''BOD'' then ''BOD Approval''
        when request_row.approval_stage = ''COMPLETED'' then ''Completed''
        when request_row.approval_stage = ''REJECTED'' then ''Rejected''
        else ''Not configured''
      end,
      ''managerId'', request_row.manager_id,
      ''managerName'', manager_row.full_name,
      ''managerApprovedBy'', request_row.manager_approved_by,
      ''managerApprovedAt'', request_row.manager_approved_at,
      ''requiredBodApprovals'', request_row.required_bod_approvals,
      ''bodApprovalCount'', request_row.bod_approval_count,
      ''approvalProgress'', format(''%s of %s BOD approvals'', request_row.bod_approval_count, request_row.required_bod_approvals),
      ''approvalIssue'', request_row.approval_issue,
      ''rejectionReason'', request_row.rejection_reason,
      ''approvedAt'', request_row.approved_at,
      ''rejectedAt'', request_row.rejected_at,
      ''businessUnitId'', employee_row.business_unit_id,
      ''departmentId'', employee_row.department_id
    ),
    ''canAct'', can_act,
    ''viewerActionStatus'', viewer_assignment.status,
    ''viewerStage'', viewer_assignment.approval_stage,
    ''bodApprovals'', coalesce((
      select jsonb_agg(jsonb_build_object(
        ''approverId'', assignment.approver_user_id,
        ''approverName'', approver.full_name,
        ''status'', assignment.status,
        ''actedAt'', assignment.acted_at,
        ''comments'', assignment.comments
      ) order by assignment.assigned_at, approver.full_name)
      from public.asset_request_approval_assignments assignment
      join public.hris_users approver on approver.id = assignment.approver_user_id
      where assignment.request_id = request_row.id and assignment.approval_stage = ''BOD''
    ), ''[]''::jsonb),
    ''history'', coalesce((
      select jsonb_agg(jsonb_build_object(
        ''id'', history.id,
        ''actorId'', history.actor_user_id,
        ''actorName'', actor.full_name,
        ''actorRole'', history.actor_role,
        ''stage'', history.approval_stage,
        ''action'', history.action,
        ''comments'', history.comments,
        ''createdAt'', history.created_at
      ) order by history.created_at, history.id)
      from public.asset_request_approval_history history
      left join public.hris_users actor on actor.id = history.actor_user_id
      where history.request_id = request_row.id
    ), ''[]''::jsonb)
  );
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."current_hris_role"()') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.current_hris_role()
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''''
AS $function$
  select ur.role_id
  from public.user_roles ur
  join public.roles r on r.id = ur.role_id
  where ur.user_id = public.current_hris_user_id()
    and ur.is_active and ur.is_primary and r.is_active
  limit 1
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."current_hris_roles"()') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.current_hris_roles()
 RETURNS text[]
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''''
AS $function$
  select coalesce(array_agg(ur.role_id order by ur.is_primary desc, ur.role_id), ''{}''::text[])
  from public.user_roles ur
  join public.roles r on r.id = ur.role_id
  where ur.user_id = public.current_hris_user_id()
    and ur.is_active
    and r.is_active
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."get_accessible_hris_users"()') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.get_accessible_hris_users()
 RETURNS SETOF hris_users
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare row_value public.hris_users; own_row boolean;
begin
  for row_value in select u.* from public.hris_users u where public.can_access_hris_user(u.id) loop
    own_row := row_value.id = public.current_hris_user_id();
    if not own_row then row_value.auth_user_id := null; end if;
    if not own_row and not public.has_feature_permission(''PersonalInformation'',''view'') then
      row_value.birth_date := null;
      row_value.emergency_contact_name := null;
      row_value.emergency_contact_relationship := null;
      row_value.emergency_contact_phone := null;
      row_value.tax_status := null;
    end if;
    if not own_row and not public.has_sensitive_permission(''sss'') then row_value.sss_no := null; end if;
    if not own_row and not public.has_sensitive_permission(''tin'') then row_value.tin := null; end if;
    if not own_row and not public.has_sensitive_permission(''pagibig'') then row_value.pagibig_no := null; end if;
    if not own_row and not public.has_sensitive_permission(''philhealth'') then row_value.philhealth_no := null; end if;
    if not own_row and not public.has_sensitive_permission(''bank_information'') then
      row_value.bank_name := null; row_value.bank_account_number := null; row_value.bank_account_type := null;
    end if;
    if not own_row and not public.has_sensitive_permission(''salary_compensation'') then
      row_value.rate_amount := null; row_value.salary_basic := null; row_value.salary_deminimis := null; row_value.salary_reimbursable := null;
    end if;
    return next row_value;
  end loop;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."admin_update_role_default_scope"(text, text)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.admin_update_role_default_scope(p_role text, p_default_data_scope text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  actor_id uuid := public.current_hris_user_id();
  linked_role text;
  before_state jsonb;
begin
  if actor_id is null or not public.has_active_role(''Admin'') then
    raise exception ''Forbidden: Admin role-configuration authority is required.'' using errcode = ''42501'';
  end if;

  if p_role in (''Recruiter'',''test role'')
     or not exists (select 1 from public.roles where id = p_role and is_active) then
    raise exception ''Unknown or inactive role.'';
  end if;

  if p_default_data_scope not in (''SELF'',''DIRECT_REPORTS'',''DEPARTMENT'',''HOME_ONLY'',''SPECIFIC'',''GLOBAL'') then
    raise exception ''Invalid default data scope.'';
  end if;

  linked_role := case
    when p_role = ''Board of Director'' then ''HR Manager''
    when p_role = ''HR Manager'' then ''Board of Director''
  end;

  select coalesce(jsonb_agg(jsonb_build_object(
    ''role'', r.id,
    ''defaultDataScope'', r.default_data_scope,
    ''dashboardType'', r.dashboard_type
  ) order by r.id), ''[]''::jsonb)
  into before_state
  from public.roles r
  where r.id in (p_role, coalesce(linked_role, p_role));

  update public.roles
  set default_data_scope = p_default_data_scope,
      updated_at = now()
  where id in (p_role, coalesce(linked_role, p_role));

  insert into public.rbac_audit_log(
    actor_user_id, action, entity_type, entity_id, before_value, after_value
  ) values (
    actor_id,
    ''UPDATE_ROLE_DEFAULT_SCOPE'',
    ''role'',
    p_role,
    before_state,
    jsonb_build_object(
      ''roles'', array_remove(array[p_role, linked_role], null),
      ''defaultDataScope'', p_default_data_scope
    )
  );

  update public.rbac_cache_versions set version = version + 1, updated_at = now();
  return true;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."set_nte_code"()') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.set_nte_code()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  v_bu_code text;
  v_year integer;
  v_sequence bigint;
begin
  select nullif(trim(bu.code), '''')
    into v_bu_code
  from public.incident_reports ir
  left join public.business_units bu on bu.id = ir.business_unit_id
  where ir.id = new.incident_report_id;

  v_year := extract(year from coalesce(new.created_at, now()))::integer;
  if new.nte_code is null or trim(new.nte_code) = '''' then
    v_sequence := nextval(''public.ntes_nte_code_seq'');
  end if;
  new.nte_code := coalesce(
    nullif(new.nte_code, ''''),
    format(
      ''NTE-%s-%s-%s'',
      v_year,
      upper(coalesce(v_bu_code, ''GEN'')),
      lpad(v_sequence::text, 3, ''0'')
    )
  );

  if new.body is not null then
    new.body := regexp_replace(
      new.body,
      ''NTE-[0-9]{4}-[A-Z0-9]+-XXX|NTE-[0-9]{4}-XXX-XXX|TNGNTE-[0-9]+'',
      new.nte_code,
      ''g''
    );
  end if;
  return new;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."assign_incident_case_handler"(uuid, uuid, boolean)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.assign_incident_case_handler(p_incident_report_id uuid, p_handler_user_id uuid, p_move_to_nte boolean DEFAULT false)
 RETURNS incident_reports
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  v_actor_id uuid := public.current_hris_user_id();
  v_actor_email text;
  v_handler_name text;
  v_handler_email text;
  v_previous_handler_name text;
  v_report public.incident_reports%rowtype;
  v_previous_handler_id uuid;
  v_assignment_changed boolean;
  v_dedupe_key text;
begin
  if v_actor_id is null then
    raise exception using errcode = ''42501'', message = ''Authentication is required to assign an incident case handler.'';
  end if;

  if not public.has_feature_permission(''IncidentReports'', ''assign'')
     and not public.has_feature_permission(''IncidentReports'', ''manage'') then
    raise exception using errcode = ''42501'', message = ''You do not have permission to assign incident case handlers.'';
  end if;

  select * into v_report
  from public.incident_reports
  where id = p_incident_report_id
  for update;

  if not found then
    raise exception using errcode = ''P0002'', message = ''The incident report could not be found.'';
  end if;

  if p_handler_user_id is null then
    raise exception using errcode = ''23502'', message = ''Select an authorized case handler before continuing.'';
  end if;

  select u.full_name, u.email
    into v_handler_name, v_handler_email
  from public.hris_users u
  where u.id = p_handler_user_id
    and private.is_employee_self_service_eligible(u.id)
    and private.user_can_handle_incident_case(u.id)
    and private.user_is_within_current_scope(u.id);

  if v_handler_name is null then
    raise exception using errcode = ''22023'', message = ''The selected user is not an eligible active HR case handler within your access scope.'';
  end if;

  if p_move_to_nte and v_report.pipeline_stage not in (''ir-review'', ''hr-review-response'', ''nte-for-approval'') then
    raise exception using errcode = ''22023'', message = ''This incident report is not in a stage that can move to NTE approval.'';
  end if;

  v_previous_handler_id := v_report.assigned_to_id;
  v_previous_handler_name := v_report.assigned_to_name;
  v_assignment_changed := v_previous_handler_id is distinct from p_handler_user_id;

  update public.incident_reports
  set assigned_to_id = p_handler_user_id,
      assigned_to_name = v_handler_name,
      pipeline_stage = case when p_move_to_nte then ''nte-for-approval'' else pipeline_stage end,
      status = case when p_move_to_nte then ''Converted''::public.ir_status else status end,
      updated_at = now()
  where id = p_incident_report_id
  returning * into v_report;

  if v_assignment_changed then
    v_dedupe_key := ''incident:'' || v_report.id::text || '':handler:'' || p_handler_user_id::text;
    insert into public.notifications (
      user_id, type, title, message, link, related_entity_id, dedupe_key
    ) values (
      p_handler_user_id::text,
      ''CASE_ASSIGNED'',
      ''Incident case assigned'',
      format(
        ''You were assigned %s involving %s (%s, %s).'',
        ''TNGIR-'' || lpad(v_report.case_number::text, 5, ''0''),
        coalesce(array_to_string(v_report.involved_employee_names, '', ''), ''an employee''),
        coalesce(v_report.business_unit_name, ''Business unit not specified''),
        coalesce(v_report.category, ''Incident'')
      ),
      ''/feedback/cases?action=view_case&caseId='' || v_report.id::text,
      v_report.id::text,
      v_dedupe_key
    )
    on conflict (user_id, dedupe_key) do nothing;

    select email into v_actor_email from public.hris_users where id = v_actor_id;
    insert into public.audit_logs (user_id, user_email, action, entity, entity_id, details)
    values (
      v_actor_id::text,
      v_actor_email,
      case when v_previous_handler_id is null then ''ASSIGN'' else ''REASSIGN'' end,
      ''IncidentReport'',
      v_report.id::text,
      format(
        ''Case handler changed from %s (%s) to %s (%s) for %s.'',
        coalesce(v_previous_handler_name, ''Unassigned''),
        coalesce(v_previous_handler_id::text, ''none''),
        v_handler_name,
        p_handler_user_id,
        ''TNGIR-'' || lpad(v_report.case_number::text, 5, ''0'')
      )
    );
  end if;

  if p_move_to_nte then
    select email into v_actor_email from public.hris_users where id = v_actor_id;
    insert into public.audit_logs (user_id, user_email, action, entity, entity_id, details)
    values (
      v_actor_id::text,
      v_actor_email,
      ''UPDATE'',
      ''IncidentReport'',
      v_report.id::text,
      format(''Moved %s to NTE approval with handler %s.'', ''TNGIR-'' || lpad(v_report.case_number::text, 5, ''0''), v_handler_name)
    );
  end if;

  return v_report;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."follow_up_incident_report"(uuid)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.follow_up_incident_report(p_incident_report_id uuid)
 RETURNS incident_reports
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  v_actor_id uuid := public.current_hris_user_id();
  v_actor_name text;
  v_actor_email text;
  v_report public.incident_reports%rowtype;
  v_target_id uuid;
  v_case_label text;
begin
  if v_actor_id is null then
    raise exception using errcode = ''42501'', message = ''Authentication is required to follow up an incident report.'';
  end if;

  select * into v_report
  from public.incident_reports
  where id = p_incident_report_id
  for update;

  if not found then
    raise exception using errcode = ''P0002'', message = ''The incident report could not be found.'';
  end if;

  if v_report.reported_by is distinct from v_actor_id
     and not public.has_feature_permission(''IncidentReports'', ''manage'') then
    raise exception using errcode = ''42501'', message = ''Only the requester or an authorized case manager can follow up this incident report.'';
  end if;

  if v_report.status::text in (''Closed'', ''NoAction'') then
    raise exception using errcode = ''22023'', message = ''Closed incident reports cannot be followed up.'';
  end if;

  if v_report.last_follow_up_at is not null
     and v_report.last_follow_up_at > now() - interval ''12 hours'' then
    raise exception using errcode = ''22023'', message = ''A follow-up was already sent recently. Please wait 12 hours before sending another reminder.'';
  end if;

  select full_name, email into v_actor_name, v_actor_email
  from public.hris_users where id = v_actor_id;
  v_case_label := case when v_report.case_number is not null
    then ''TNGIR-'' || lpad(v_report.case_number::text, 5, ''0'')
    else v_report.id::text end;

  update public.incident_reports
  set follow_up_count = follow_up_count + 1,
      last_follow_up_at = now(),
      follow_up_history = coalesce(follow_up_history, ''[]''::jsonb) || jsonb_build_array(
        jsonb_build_object(
          ''sentAt'', now(),
          ''sentById'', v_actor_id,
          ''sentByName'', coalesce(v_actor_name, ''Employee'')
        )
      ),
      updated_at = now()
  where id = p_incident_report_id
  returning * into v_report;

  if v_report.assigned_to_id is not null then
    insert into public.notifications(user_id, type, title, message, link, related_entity_id)
    values (
      v_report.assigned_to_id::text,
      ''INCIDENT_FOLLOW_UP'',
      ''Incident report follow-up'',
      format(''%s followed up on %s. Please review the outstanding case.'', coalesce(v_actor_name, ''The requester''), v_case_label),
      ''/feedback/cases?action=view_case&caseId='' || v_report.id::text,
      v_report.id::text
    );
  else
    for v_target_id in
      select distinct ur.user_id
      from public.user_roles ur
      join public.roles r on r.id = ur.role_id and r.is_active
      join public.hris_users u on u.id = ur.user_id
      where ur.is_active
        and ur.role_id in (''HR Staff'', ''HR Manager'', ''Board of Director'')
        and lower(coalesce(u.status, ''active'')) = ''active''
        and ur.user_id <> v_actor_id
    loop
      insert into public.notifications(user_id, type, title, message, link, related_entity_id)
      values (
        v_target_id::text,
        ''INCIDENT_FOLLOW_UP'',
        ''Unassigned incident report follow-up'',
        format(''%s followed up on unassigned case %s.'', coalesce(v_actor_name, ''The requester''), v_case_label),
        ''/feedback/cases?action=view_case&caseId='' || v_report.id::text,
        v_report.id::text
      );
    end loop;
  end if;

  insert into public.audit_logs(user_id, user_email, action, entity, entity_id, details)
  values (
    v_actor_id::text,
    v_actor_email,
    ''UPDATE'',
    ''IncidentReport'',
    v_report.id::text,
    format(''Sent follow-up #%s for %s.'', v_report.follow_up_count, v_case_label)
  );

  return v_report;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."follow_up_ticket"(uuid)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.follow_up_ticket(p_ticket_id uuid)
 RETURNS tickets
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  v_actor_id uuid := public.current_hris_user_id();
  v_actor_name text;
  v_actor_email text;
  v_ticket public.tickets%rowtype;
  v_target_id uuid;
begin
  if v_actor_id is null then
    raise exception using errcode = ''42501'', message = ''Authentication is required to follow up a ticket.'';
  end if;

  select * into v_ticket
  from public.tickets
  where id = p_ticket_id
  for update;

  if not found then
    raise exception using errcode = ''P0002'', message = ''The ticket could not be found.'';
  end if;

  if v_ticket.requester_id is distinct from v_actor_id
     and not public.has_feature_permission(''Helpdesk'', ''manage'') then
    raise exception using errcode = ''42501'', message = ''Only the requester or an authorized helpdesk user can follow up this ticket.'';
  end if;

  if v_ticket.status::text in (''Resolved'', ''Closed'') then
    raise exception using errcode = ''22023'', message = ''Resolved or closed tickets cannot be followed up.'';
  end if;

  if v_ticket.last_follow_up_at is not null
     and v_ticket.last_follow_up_at > now() - interval ''12 hours'' then
    raise exception using errcode = ''22023'', message = ''A follow-up was already sent recently. Please wait 12 hours before sending another reminder.'';
  end if;

  select full_name, email into v_actor_name, v_actor_email
  from public.hris_users where id = v_actor_id;

  update public.tickets
  set follow_up_count = follow_up_count + 1,
      last_follow_up_at = now(),
      follow_up_history = coalesce(follow_up_history, ''[]''::jsonb) || jsonb_build_array(
        jsonb_build_object(
          ''sentAt'', now(),
          ''sentById'', v_actor_id,
          ''sentByName'', coalesce(v_actor_name, ''Employee'')
        )
      )
  where id = p_ticket_id
  returning * into v_ticket;

  if v_ticket.assigned_to_id is not null then
    insert into public.notifications(user_id, type, title, message, link, related_entity_id)
    values (
      v_ticket.assigned_to_id::text,
      ''TICKET_FOLLOW_UP'',
      ''Helpdesk ticket follow-up'',
      format(''%s followed up on ticket %s. Please review the outstanding request.'', coalesce(v_actor_name, ''The requester''), v_ticket.id),
      ''/helpdesk/tickets?ticketId='' || v_ticket.id::text,
      v_ticket.id::text
    );
  else
    for v_target_id in
      select distinct ur.user_id
      from public.user_roles ur
      join public.roles r on r.id = ur.role_id and r.is_active
      join public.hris_users u on u.id = ur.user_id
      where ur.is_active
        and ur.role_id in (''IT'', ''HR Staff'', ''HR Manager'', ''Admin'')
        and lower(coalesce(u.status, ''active'')) = ''active''
        and ur.user_id <> v_actor_id
    loop
      insert into public.notifications(user_id, type, title, message, link, related_entity_id)
      values (
        v_target_id::text,
        ''TICKET_FOLLOW_UP'',
        ''Unassigned helpdesk ticket follow-up'',
        format(''%s followed up on unassigned ticket %s.'', coalesce(v_actor_name, ''The requester''), v_ticket.id),
        ''/helpdesk/tickets?ticketId='' || v_ticket.id::text,
        v_ticket.id::text
      );
    end loop;
  end if;

  insert into public.audit_logs(user_id, user_email, action, entity, entity_id, details)
  values (
    v_actor_id::text,
    v_actor_email,
    ''UPDATE'',
    ''Ticket'',
    v_ticket.id::text,
    format(''Sent ticket follow-up #%s.'', v_ticket.follow_up_count)
  );

  return v_ticket;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."acknowledge_announcement"(uuid)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.acknowledge_announcement(p_announcement_id uuid)
 RETURNS announcement_recipients
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  v_actor_id uuid := public.current_hris_user_id();
  v_actor_email text;
  v_recipient public.announcement_recipients%rowtype;
begin
  if v_actor_id is null then
    raise exception using errcode = ''42501'', message = ''Authentication is required.'';
  end if;

  update public.announcement_recipients
  set read_at = coalesce(read_at, now()),
      acknowledged_at = coalesce(acknowledged_at, now())
  where announcement_id = p_announcement_id and user_id = v_actor_id
  returning * into v_recipient;

  if not found then
    raise exception using errcode = ''42501'', message = ''This announcement is not assigned to your account.'';
  end if;

  update public.announcements
  set acknowledgement_user_ids = array(
        select distinct acknowledgement_id
        from unnest(acknowledgement_user_ids || array[v_actor_id]) acknowledgement_id
      ),
      updated_at = now()
  where id = p_announcement_id;

  select email into v_actor_email from public.hris_users where id = v_actor_id;
  insert into public.audit_logs(user_id, user_email, action, entity, entity_id, details)
  values (v_actor_id::text, v_actor_email, ''UPDATE'', ''Announcement'', p_announcement_id::text, ''Read and acknowledged announcement.'');

  return v_recipient;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."remove_onboarding_checklist_template"(uuid)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.remove_onboarding_checklist_template(p_template_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  actor_id uuid := public.current_hris_user_id();
  actor_email text;
  template_name text;
  usage_count integer;
  removal_mode text;
begin
  if actor_id is null then
    raise exception ''Authentication is required.'' using errcode = ''42501'';
  end if;
  if not (
    public.is_hr_or_admin()
    or public.has_feature_permission(''Employees'', ''edit'')
    or public.has_feature_permission(''Lifecycle'', ''manage'')
  ) then
    raise exception ''You do not have permission to remove lifecycle templates.'' using errcode = ''42501'';
  end if;

  select name into template_name
  from public.onboarding_checklist_templates
  where id = p_template_id
  for update;
  if not found then
    raise exception ''Lifecycle template not found.'' using errcode = ''P0002'';
  end if;

  select count(*) into usage_count
  from public.onboarding_checklists
  where template_id = p_template_id;

  if usage_count > 0 then
    update public.onboarding_checklist_templates
       set is_active = false, archived_at = now(), archived_by = actor_id
     where id = p_template_id;
    removal_mode := ''archived'';
  else
    begin
      delete from public.onboarding_checklist_templates where id = p_template_id;
      removal_mode := ''deleted'';
    exception when foreign_key_violation then
      update public.onboarding_checklist_templates
         set is_active = false, archived_at = now(), archived_by = actor_id
       where id = p_template_id;
      removal_mode := ''archived'';
    end;
  end if;

  select email into actor_email from public.hris_users where id = actor_id;
  insert into public.audit_logs(user_id, user_email, action, entity, entity_id, details)
  values(
    actor_id::text,
    actor_email,
    case when removal_mode = ''deleted'' then ''DELETE'' else ''UPDATE'' end,
    ''OnboardingChecklistTemplate'',
    p_template_id::text,
    format(''%s lifecycle template "%s"; %s linked checklist(s) preserved.'', initcap(removal_mode), template_name, usage_count)
  );

  return jsonb_build_object(
    ''id'', p_template_id,
    ''name'', template_name,
    ''mode'', removal_mode,
    ''linked_checklists'', usage_count
  );
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
