DO $parity$
BEGIN
  IF to_regprocedure('"public"."send_announcement_reminders"(uuid, text, uuid[])') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.send_announcement_reminders(p_announcement_id uuid, p_mode text DEFAULT ''outstanding''::text, p_user_ids uuid[] DEFAULT NULL::uuid[])
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  v_actor_id uuid := public.current_hris_user_id();
  v_actor_email text;
  v_title text;
  v_type text;
  v_count integer := 0;
begin
  if v_actor_id is null or not public.has_feature_permission(''Announcements'', ''manage'') then
    raise exception using errcode = ''42501'', message = ''You do not have permission to send announcement reminders.'';
  end if;

  select title, type::text into v_title, v_type
  from public.announcements where id = p_announcement_id;
  if not found then
    raise exception using errcode = ''P0002'', message = ''The announcement could not be found.'';
  end if;

  with targets as (
    select recipient.id, recipient.user_id
    from public.announcement_recipients recipient
    where recipient.announcement_id = p_announcement_id
      and (
        (p_mode = ''unread'' and recipient.read_at is null)
        or (p_mode = ''unacknowledged'' and recipient.acknowledged_at is null)
        or (p_mode = ''outstanding'' and (
          (v_type = ''Policy'' and recipient.acknowledged_at is null)
          or (v_type <> ''Policy'' and recipient.read_at is null)
        ))
        or (p_mode = ''selected'' and recipient.user_id = any(coalesce(p_user_ids, ''{}''::uuid[])))
      )
  ), updated as (
    update public.announcement_recipients recipient
    set reminder_count = recipient.reminder_count + 1,
        last_reminder_at = now()
    from targets
    where recipient.id = targets.id
    returning recipient.user_id
  ), notified as (
    insert into public.notifications(user_id, type, title, message, link, related_entity_id)
    select
      updated.user_id::text,
      ''ANNOUNCEMENT_REMINDER'',
      ''Announcement reminder'',
      v_title,
      ''/helpdesk/announcements?announcementId='' || p_announcement_id::text,
      p_announcement_id::text
    from updated
    returning 1
  )
  select count(*) into v_count from notified;

  select email into v_actor_email from public.hris_users where id = v_actor_id;
  insert into public.audit_logs(user_id, user_email, action, entity, entity_id, details)
  values (
    v_actor_id::text,
    v_actor_email,
    ''UPDATE'',
    ''Announcement'',
    p_announcement_id::text,
    format(''Sent %s reminder(s) using mode %s.'', v_count, p_mode)
  );

  return v_count;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."audit_user_document_change"()') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.audit_user_document_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare actor_id uuid := public.current_hris_user_id(); actor_email text; action_name text;
begin
  select email into actor_email from public.hris_users where id = actor_id;
  action_name := case
    when tg_op = ''INSERT'' and new.replaces_document_id is not null then ''REPLACE''
    when tg_op = ''INSERT'' then ''UPLOAD''
    when new.archived_at is not null and old.archived_at is null then ''ARCHIVE''
    else ''UPDATE''
  end;
  insert into public.audit_logs(user_id,user_email,action,entity,entity_id,details)
  values(
    coalesce(actor_id::text,''system''),actor_email,action_name,''EmployeeDocument'',new.id,
    jsonb_build_object(
      ''employeeId'',new.user_id,''documentType'',new.document_type,''source'',new.document_source,
      ''status'',new.status,''version'',new.version_number,''replaces'',new.replaces_document_id
    )::text
  );
  return new;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."accept_pan"(uuid, text, text)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.accept_pan(p_pan_id uuid, p_signature_data_url text, p_signature_name text)
 RETURNS pans
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  actor_id uuid := public.current_hris_user_id();
  pan_row public.pans;
  bod_approved boolean;
  all_approved boolean;
  to_data jsonb;
  action_data jsonb;
  next_position text;
  next_department text;
  next_employment_status text;
  next_business_unit text;
  next_business_unit_id uuid;
begin
  if actor_id is null then raise exception ''Authentication required.'' using errcode=''42501''; end if;
  if nullif(trim(coalesce(p_signature_name,'''')),'''') is null or nullif(trim(coalesce(p_signature_data_url,'''')),'''') is null then
    raise exception ''Your typed name and signature are required.'';
  end if;
  select * into pan_row from public.pans where id=p_pan_id for update;
  if pan_row.id is null then raise exception ''PAN record not found.''; end if;
  if pan_row.employee_id is distinct from actor_id then raise exception ''Only the employee named in this PAN may accept it.'' using errcode=''42501''; end if;
  if pan_row.status::text <> ''Pending Employee'' then raise exception ''This PAN is not awaiting employee acceptance.''; end if;

  select not exists(select 1 from jsonb_array_elements(pan_row.routing_steps) step where step->>''status'' <> ''Approved'') into all_approved;
  select exists(select 1 from jsonb_array_elements(pan_row.routing_steps) step where step->>''status''=''Approved'' and private.pan_user_is_bod(step->>''userId'')) into bod_approved;
  if pan_row.workflow_version >= 2 and (not all_approved or not bod_approved) then
    raise exception ''Required approvals, including Board of Director approval, are incomplete.'';
  end if;

  to_data := coalesce(pan_row.particulars->''to'',''{}''::jsonb);
  action_data := coalesce(pan_row.action_taken,''{}''::jsonb);
  next_position := nullif(trim(to_data->>''position''),'''');
  next_department := nullif(trim(to_data->>''department''),'''');
  next_employment_status := nullif(trim(to_data->>''employmentStatus''),'''');
  next_business_unit := nullif(trim(to_data->>''businessUnit''),'''');
  if coalesce(to_data->>''businessUnitId'','''') ~* ''^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'' then
    next_business_unit_id := (to_data->>''businessUnitId'')::uuid;
  end if;

  if pan_row.workflow_version >= 2 then
    update public.hris_users
    set position = case
          when coalesce((action_data->>''promotion'')::boolean,false) or coalesce((action_data->>''changeOfJobTitle'')::boolean,false) or coalesce((action_data->>''transfer'')::boolean,false)
            then case when lower(coalesce(next_position,'''')) in (''same'',''not applicable'') then position else coalesce(next_position,position) end
          else position end,
        department = case when coalesce((action_data->>''transfer'')::boolean,false)
          then case when lower(coalesce(next_department,'''')) in (''same'',''not applicable'') then department else coalesce(next_department,department) end else department end,
        business_unit = case when coalesce((action_data->>''transfer'')::boolean,false)
          then case when lower(coalesce(next_business_unit,'''')) in (''same'',''not applicable'') then business_unit else coalesce(next_business_unit,business_unit) end else business_unit end,
        business_unit_id = case when coalesce((action_data->>''transfer'')::boolean,false) then coalesce(next_business_unit_id,business_unit_id) else business_unit_id end,
        employment_status = case when coalesce((action_data->>''changeOfStatus'')::boolean,false)
          then case when lower(coalesce(next_employment_status,'''')) in (''same'',''not applicable'') then employment_status else coalesce(next_employment_status,employment_status) end else employment_status end,
        salary_basic = case when coalesce((action_data->>''salaryIncrease'')::boolean,false) then coalesce(nullif(to_data#>>''{salary,basic}'','''')::numeric,salary_basic) else salary_basic end,
        salary_deminimis = case when coalesce((action_data->>''salaryIncrease'')::boolean,false) then coalesce(nullif(to_data#>>''{salary,deminimis}'','''')::numeric,salary_deminimis) else salary_deminimis end,
        salary_reimbursable = case when coalesce((action_data->>''salaryIncrease'')::boolean,false) then coalesce(nullif(to_data#>>''{salary,reimbursable}'','''')::numeric,salary_reimbursable) else salary_reimbursable end
    where id=pan_row.employee_id;
  end if;

  update public.pans
  set status=''Completed'',signed_at=now(),signature_data_url=p_signature_data_url,signature_name=trim(p_signature_name),
      accepted_at=now(),accepted_by=actor_id,applied_at=case when workflow_version>=2 then now() else applied_at end,updated_at=now()
  where id=p_pan_id returning * into pan_row;
  perform private.pan_notify(
    pan_row.created_by_user_id,''PAN_UPDATE'',''PAN Accepted'',
    format(''%s acknowledged and accepted PAN %s.'',pan_row.employee_name,p_pan_id),
    format(''/employees/pan?item=%s'',p_pan_id),p_pan_id,format(''pan:%s:accepted'',p_pan_id)
  );
  perform private.pan_audit(''ACCEPT'',p_pan_id,jsonb_build_object(''employeeId'',actor_id,''status'',''Completed'',''employeeRecordApplied'',pan_row.workflow_version>=2));
  return pan_row;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."submit_pan"(uuid)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.submit_pan(p_pan_id uuid)
 RETURNS pans
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  actor_id uuid := public.current_hris_user_id();
  pan_row public.pans;
  step_row jsonb;
  normalized_steps jsonb := ''[]''::jsonb;
  step_number integer := 0;
  first_step jsonb;
  bod_count integer := 0;
begin
  if actor_id is null or not private.pan_actor_can_create() then
    raise exception ''Forbidden: PAN submission permission is required.'' using errcode = ''42501'';
  end if;

  select * into pan_row from public.pans where id = p_pan_id for update;
  if pan_row.id is null then raise exception ''PAN record not found.''; end if;
  if pan_row.status::text not in (''Draft'', ''Declined'', ''Returned for Edits'') then
    raise exception ''Only a draft, rejected, or returned PAN can be submitted.'';
  end if;
  if pan_row.created_by_user_id is distinct from actor_id and not private.pan_actor_can_create() then
    raise exception ''You are not authorized to submit this PAN.'' using errcode = ''42501'';
  end if;
  if jsonb_array_length(coalesce(pan_row.routing_steps, ''[]''::jsonb)) = 0 then
    raise exception ''Add at least one approver before submitting the PAN.'';
  end if;

  select count(*) into bod_count
  from jsonb_array_elements(coalesce(pan_row.routing_steps, ''[]''::jsonb)) step
  where private.pan_user_is_bod(step->>''userId'');
  if bod_count = 0 then
    raise exception ''Every PAN requires at least one active Board of Director approver.'';
  end if;

  for step_row in
    select value from jsonb_array_elements(pan_row.routing_steps) with ordinality as route(value, ordinality)
    order by ordinality
  loop
    if nullif(step_row->>''userId'', '''') is null then
      raise exception ''Every PAN routing step must identify an approver.'';
    end if;
    normalized_steps := normalized_steps || jsonb_build_array(
      (step_row - ''timestamp'' - ''notes'') || jsonb_build_object(
        ''order'', step_number,
        ''status'', case when step_number = 0 then ''Pending'' else ''Waiting'' end,
        ''role'', case when private.pan_user_is_bod(step_row->>''userId'') then ''Board of Director'' else coalesce(nullif(step_row->>''role'',''''), ''Approver'') end
      )
    );
    step_number := step_number + 1;
  end loop;

  update public.pans
  set status = ''Pending Approval'',
      workflow_version = 2,
      routing_steps = normalized_steps,
      rejection_reason = null,
      approval_completed_at = null,
      updated_at = now()
  where id = p_pan_id
  returning * into pan_row;

  first_step := normalized_steps->0;
  perform private.pan_notify(
    (first_step->>''userId'')::uuid,
    ''PAN_APPROVAL_REQUEST'',
    ''PAN Approval Required'',
    format(''PAN %s for %s is awaiting your approval.'', p_pan_id, pan_row.employee_name),
    format(''/approvals?type=pan&item=%s'', p_pan_id),
    p_pan_id,
    format(''pan:%s:approval:%s'', p_pan_id, coalesce(first_step->>''id'', ''0''))
  );
  perform private.pan_audit(''SUBMIT'', p_pan_id, jsonb_build_object(
    ''status'', ''Pending Approval'', ''workflowVersion'', 2,
    ''routingStepCount'', jsonb_array_length(normalized_steps), ''requiredBodSteps'', bod_count
  ));
  return pan_row;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."enforce_employee_award_certificate_gate"()') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.enforce_employee_award_certificate_gate()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''''
AS $function$
begin
  if new.status::text in (''Draft'', ''PendingApproval'', ''Pending Approval'', ''Pending'', ''Rejected'')
     and new.certificate_snapshot_url is not null
     and (tg_op = ''INSERT'' or old.certificate_snapshot_url is distinct from new.certificate_snapshot_url) then
    raise exception ''A final award certificate cannot be stored before approval.'';
  end if;
  if new.status::text = ''Issued'' and nullif(btrim(new.certificate_snapshot_url), '''') is null then
    raise exception ''An issued award requires a final certificate.'';
  end if;
  return new;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"private"."notify_time_request_direct_manager"()') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION private.notify_time_request_direct_manager()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare request_type text; manager_stage boolean; request_title text; request_link text; manager_name text;
begin
  request_type:=case tg_table_name when ''leave_requests'' then ''leave'' when ''wfh_requests'' then ''wfh'' else ''overtime'' end;
  manager_stage:=case tg_table_name
    when ''leave_requests'' then new.status::text in (''Pending'',''PendingGM'')
    when ''wfh_requests'' then new.status::text in (''WFH_PENDING_DEPT_HEAD_APPROVAL'',''WFH_PENDING_GM_APPROVAL'')
    else new.status::text in (''Submitted'',''PendingGM'') end;
  if not manager_stage then return new; end if;
  if tg_op=''UPDATE'' and new.status is not distinct from old.status and new.direct_manager_id is not distinct from old.direct_manager_id then return new; end if;
  if new.direct_manager_id is not null then
    request_title:=case request_type when ''leave'' then ''Leave Request Pending Your Approval'' when ''wfh'' then ''WFH Request Pending Your Approval'' else ''Overtime Request Pending Your Approval'' end;
    request_link:=format(''/approvals?type=%s&item=%s'',request_type,new.id);
    if not exists(select 1 from public.notifications n where n.user_id=new.direct_manager_id::text and n.related_entity_id=new.id::text and n.title=request_title) then
      insert into public.notifications(user_id,type,title,message,link,related_entity_id,dedupe_key)
      values(new.direct_manager_id::text,''GENERAL'',request_title,
        format(''%s submitted a %s request for your review.'',new.employee_name,request_type),request_link,new.id::text,
        format(''direct-manager-%s-%s-%s'',request_type,new.id,new.direct_manager_id));
    end if;
    select full_name into manager_name from public.hris_users where id=new.direct_manager_id;
    insert into public.audit_logs(user_id,action,entity,entity_id,details)
    select new.employee_id::text,''ASSIGN'',initcap(request_type),new.id::text,
      format(''Assigned to direct manager %s (%s)'',coalesce(manager_name,''Unknown''),new.direct_manager_id)
    where not exists(select 1 from public.audit_logs a where a.entity_id=new.id::text and a.action=''ASSIGN'' and a.details like ''%direct manager%'');
  else
    insert into public.notifications(user_id,type,title,message,link,related_entity_id,dedupe_key)
    select u.id::text,''GENERAL'',''Approver Configuration Required'',
      format(''%s request %s has no configured direct manager.'',initcap(request_type),new.id),
      format(''/approvals?type=%s&item=%s'',request_type,new.id),new.id::text,
      format(''approver-config-%s-%s-%s'',request_type,new.id,u.id)
    from public.hris_users u
    where lower(u.status)=''active'' and exists (
      select 1 from public.user_roles ur where ur.user_id=u.id and ur.is_active
        and ur.role_id in (''HR Manager'',''HR Staff'',''Admin'')
    )
      and not exists(select 1 from public.notifications n where n.dedupe_key=format(''approver-config-%s-%s-%s'',request_type,new.id,u.id));
  end if;
  return new;
end $function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."process_job_requisition_approval"(uuid, text, text)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.process_job_requisition_approval(p_requisition_id uuid, p_decision text, p_reason text DEFAULT NULL::text)
 RETURNS job_requisitions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare actor_id uuid:=public.current_hris_user_id(); request_row public.job_requisitions; step jsonb; rebuilt jsonb:=''[]''::jsonb; actor_found boolean:=false; remaining integer; approved_bod integer; next_index integer; next_user uuid;
begin
  if actor_id is null then raise exception ''Authentication is required.'' using errcode=''42501''; end if;
  if lower(p_decision) not in (''approve'',''reject'') then raise exception ''Decision must be approve or reject.''; end if;
  select * into request_row from public.job_requisitions where id=p_requisition_id for update;
  if not found then raise exception ''Job requisition not found.'' using errcode=''P0002''; end if;
  if request_row.status::text not in (''PendingApproval'',''Pending Approval'') then raise exception ''This requisition is not pending approval.''; end if;

  for step in select value from jsonb_array_elements(coalesce(request_row.routing_steps,''[]''::jsonb)) with ordinality route(value,ordinality) order by ordinality loop
    if step->>''userId''=actor_id::text and step->>''status''=''Pending'' and not actor_found then
      actor_found:=true;
      step:=step||jsonb_build_object(''status'',case when lower(p_decision)=''approve'' then ''Approved'' else ''Rejected'' end,''timestamp'',now(),''notes'',nullif(btrim(coalesce(p_reason,'''')),''''));
    end if;
    rebuilt:=rebuilt||jsonb_build_array(step);
  end loop;
  if not actor_found then raise exception ''This requisition is not assigned to you at the current approval step.'' using errcode=''42501''; end if;
  perform set_config(''app.job_requisition_rpc'',''on'',true);
  if lower(p_decision)=''reject'' then
    update public.job_requisitions set routing_steps=rebuilt,status=''Rejected'',updated_at=now() where id=p_requisition_id returning * into request_row;
  else
    select count(*) into remaining from jsonb_array_elements(rebuilt) item where coalesce((item->>''isRequired'')::boolean,true) and lower(item->>''status'')<>''approved'';
    select count(*) into approved_bod from jsonb_array_elements(rebuilt) item where (coalesce((item->>''isBod'')::boolean,false) or item->>''roleSnapshot''=''Board of Director'') and lower(item->>''status'')=''approved'';
    if remaining=0 and approved_bod>0 then
      update public.job_requisitions set routing_steps=rebuilt,status=''Approved'',updated_at=now() where id=p_requisition_id returning * into request_row;
    else
      select ordinality::integer-1,(value->>''userId'')::uuid into next_index,next_user from jsonb_array_elements(rebuilt) with ordinality route(value,ordinality) where value->>''status''=''Waiting'' order by ordinality limit 1;
      if next_index is not null then rebuilt:=jsonb_set(rebuilt,array[next_index::text,''status''],''"Pending"''::jsonb,true); end if;
      update public.job_requisitions set routing_steps=rebuilt,status=''PendingApproval'',updated_at=now() where id=p_requisition_id returning * into request_row;
    end if;
  end if;
  insert into public.audit_logs(user_id,user_email,action,entity,entity_id,details)
  select actor_id::text,actor.email,upper(p_decision),''JobRequisition'',p_requisition_id::text,format(''%s assigned approval step. Status: %s'',initcap(lower(p_decision)),request_row.status::text)
  from public.hris_users actor where actor.id=actor_id;
  if next_user is not null then
    insert into public.notifications(user_id,type,title,message,link,is_read,related_entity_id,dedupe_key)
    values(next_user::text,''JOB_REQUISITION_SUBMITTED'',''Job Requisition Approval Required'',format(''Requisition %s requires your approval.'',request_row.req_code),''/recruitment/requisitions?item=''||p_requisition_id,false,p_requisition_id::text,''job-requisition:''||p_requisition_id::text||'':''||next_user::text)
    on conflict(user_id,dedupe_key) do nothing;
  end if;
  return request_row;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."resubmit_incident_report"(uuid)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.resubmit_incident_report(p_report_id uuid)
 RETURNS incident_reports
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  actor uuid := public.current_hris_user_id();
  row public.incident_reports;
  previous_status text;
begin
  if actor is null then
    raise exception ''Authentication is required to resubmit an incident report'' using errcode = ''42501'';
  end if;

  select * into row
  from public.incident_reports
  where id = p_report_id
  for update;

  if row.id is null then
    raise exception ''Incident report not found'' using errcode = ''P0002'';
  end if;
  if row.reported_by <> actor then
    raise exception ''Only the original reporter can resubmit this incident report'' using errcode = ''42501'';
  end if;
  if row.status::text not in (''Returned for Revision'', ''Rejected'') then
    raise exception ''Only a returned or rejected incident report can be resubmitted'' using errcode = ''22023'';
  end if;

  previous_status := row.status::text;

  update public.incident_reports
  set status = ''Submitted'',
      pipeline_stage = ''ir-review'',
      revision_notes = null,
      rejection_reason = null,
      updated_at = now(),
      revision_history = coalesce(revision_history, ''[]''::jsonb)
        || jsonb_build_array(jsonb_build_object(
          ''action'', ''Resubmitted'',
          ''actorId'', actor,
          ''actorRole'', public.current_hris_role(),
          ''at'', now(),
          ''previousStatus'', previous_status,
          ''newStatus'', ''Submitted''
        ))
  where id = p_report_id
  returning * into row;

  insert into public.audit_logs(user_id, action, entity, entity_id, details)
  values(actor::text, ''RESUBMIT'', ''IncidentReport'', row.id::text, format(''%s -> Submitted'', previous_status));

  if row.assigned_to_id is not null then
    insert into public.notifications(user_id, type, title, message, link, related_entity_id, dedupe_key)
    values(
      row.assigned_to_id::text,
      ''GENERAL'',
      ''Incident Report Resubmitted'',
      ''The reporter updated and resubmitted the incident report for review.'',
      ''/feedback/cases?reportId='' || row.id,
      row.id::text,
      ''ir-resubmit-'' || row.id || ''-'' || extract(epoch from now())::bigint
    );
  end if;

  return row;
end
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."approve_pan"(uuid, text)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.approve_pan(p_pan_id uuid, p_comment text DEFAULT NULL::text)
 RETURNS pans
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  actor_id uuid := public.current_hris_user_id();
  pan_row public.pans;
  step_row jsonb;
  rebuilt jsonb := ''[]''::jsonb;
  actor_step_found boolean := false;
  next_step_index integer;
  step_index integer := 0;
  next_step jsonb;
  all_approved boolean;
  bod_approved boolean;
begin
  if actor_id is null then raise exception ''Authentication required.'' using errcode = ''42501''; end if;
  select * into pan_row from public.pans where id = p_pan_id for update;
  if pan_row.id is null then raise exception ''PAN record not found.''; end if;
  if pan_row.status::text <> ''Pending Approval'' then raise exception ''This PAN is not pending approval.''; end if;

  for step_row in select value from jsonb_array_elements(pan_row.routing_steps) with ordinality route(value, ordinality) order by ordinality
  loop
    if step_row->>''userId'' = actor_id::text and step_row->>''status'' = ''Pending'' and not actor_step_found then
      step_row := step_row || jsonb_build_object(''status'',''Approved'',''timestamp'',now(),''notes'',nullif(trim(coalesce(p_comment,'''')),''''));
      actor_step_found := true;
    end if;
    rebuilt := rebuilt || jsonb_build_array(step_row);
  end loop;
  if not actor_step_found then
    raise exception ''You are not the current assigned approver for this PAN.'' using errcode = ''42501'';
  end if;

  select min((ordinality - 1)::integer) into next_step_index
  from jsonb_array_elements(rebuilt) with ordinality route(value, ordinality)
  where value->>''status'' = ''Waiting'';
  if next_step_index is not null then
    rebuilt := jsonb_set(rebuilt, array[next_step_index::text, ''status''], ''"Pending"''::jsonb, false);
    next_step := rebuilt->next_step_index;
  end if;

  select not exists(select 1 from jsonb_array_elements(rebuilt) step where step->>''status'' <> ''Approved'') into all_approved;
  select exists(select 1 from jsonb_array_elements(rebuilt) step where step->>''status'' = ''Approved'' and private.pan_user_is_bod(step->>''userId'')) into bod_approved;

  if all_approved then
    if pan_row.workflow_version >= 2 and not bod_approved then
      raise exception ''A Board of Director approval is required before employee acknowledgement.'';
    end if;
    update public.pans set routing_steps=rebuilt, status=''Pending Employee'', approval_completed_at=now(), updated_at=now()
    where id=p_pan_id returning * into pan_row;
    perform private.pan_notify(
      pan_row.employee_id, ''PAN_UPDATE'', ''PAN for Acknowledgement'',
      format(''PAN %s is approved and ready for your acknowledgement and acceptance.'', p_pan_id),
      format(''/employees/pan?item=%s'', p_pan_id), p_pan_id,
      format(''pan:%s:employee-acknowledgement'', p_pan_id)
    );
  else
    update public.pans set routing_steps=rebuilt, updated_at=now() where id=p_pan_id returning * into pan_row;
    if next_step is not null then
      perform private.pan_notify(
        (next_step->>''userId'')::uuid, ''PAN_APPROVAL_REQUEST'', ''PAN Approval Required'',
        format(''PAN %s for %s is awaiting your approval.'', p_pan_id, pan_row.employee_name),
        format(''/approvals?type=pan&item=%s'', p_pan_id), p_pan_id,
        format(''pan:%s:approval:%s'', p_pan_id, coalesce(next_step->>''id'', next_step_index::text))
      );
    end if;
  end if;
  perform private.pan_audit(''APPROVE'', p_pan_id, jsonb_build_object(''comment'',nullif(trim(coalesce(p_comment,'''')),''''),''status'',pan_row.status::text));
  return pan_row;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."reject_pan"(uuid, text)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.reject_pan(p_pan_id uuid, p_reason text)
 RETURNS pans
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  actor_id uuid := public.current_hris_user_id();
  pan_row public.pans;
  step_row jsonb;
  rebuilt jsonb := ''[]''::jsonb;
  actor_step_found boolean := false;
begin
  if actor_id is null then raise exception ''Authentication required.'' using errcode = ''42501''; end if;
  if length(trim(coalesce(p_reason,''''))) < 3 then raise exception ''A rejection reason is required.''; end if;
  select * into pan_row from public.pans where id=p_pan_id for update;
  if pan_row.id is null then raise exception ''PAN record not found.''; end if;
  if pan_row.status::text <> ''Pending Approval'' then raise exception ''This PAN is not pending approval.''; end if;

  for step_row in select value from jsonb_array_elements(pan_row.routing_steps) with ordinality route(value, ordinality) order by ordinality
  loop
    if step_row->>''userId''=actor_id::text and step_row->>''status''=''Pending'' and not actor_step_found then
      step_row := step_row || jsonb_build_object(''status'',''Declined'',''timestamp'',now(),''notes'',trim(p_reason));
      actor_step_found := true;
    end if;
    rebuilt := rebuilt || jsonb_build_array(step_row);
  end loop;
  if not actor_step_found then raise exception ''You are not the current assigned approver for this PAN.'' using errcode=''42501''; end if;

  update public.pans set routing_steps=rebuilt,status=''Declined'',rejection_reason=trim(p_reason),updated_at=now()
  where id=p_pan_id returning * into pan_row;
  perform private.pan_notify(
    pan_row.created_by_user_id, ''PAN_UPDATE'', ''PAN Rejected'',
    format(''PAN %s for %s was rejected. Reason: %s'',p_pan_id,pan_row.employee_name,trim(p_reason)),
    format(''/employees/pan?item=%s'',p_pan_id),p_pan_id,format(''pan:%s:rejected'',p_pan_id)
  );
  perform private.pan_audit(''REJECT'',p_pan_id,jsonb_build_object(''reason'',trim(p_reason),''status'',''Declined''));
  return pan_row;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."cancel_pan"(uuid, text)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.cancel_pan(p_pan_id uuid, p_reason text)
 RETURNS pans
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  actor_id uuid := public.current_hris_user_id();
  pan_row public.pans;
  step_row jsonb;
  rebuilt jsonb := ''[]''::jsonb;
  target_id uuid;
  notify_employee boolean := false;
begin
  if actor_id is null then raise exception ''Authentication required.'' using errcode=''42501''; end if;
  if length(trim(coalesce(p_reason,''''))) < 3 then raise exception ''A cancellation reason is required.''; end if;
  select * into pan_row from public.pans where id=p_pan_id for update;
  if pan_row.id is null then raise exception ''PAN record not found.''; end if;
  if pan_row.status::text not in (''Draft'',''Pending Approval'',''Pending Employee'') then
    raise exception ''Only an active PAN can be cancelled.'';
  end if;
  if actor_id is distinct from pan_row.created_by_user_id
     and not (public.has_active_role(''Admin'') or public.has_active_role(''HR Manager'') or public.has_active_role(''HR Staff'')) then
    raise exception ''You are not authorized to cancel this PAN.'' using errcode=''42501'';
  end if;
  notify_employee := pan_row.status::text = ''Pending Employee'' or pan_row.approval_completed_at is not null;

  for step_row in select value from jsonb_array_elements(coalesce(pan_row.routing_steps,''[]''::jsonb)) with ordinality route(value, ordinality) order by ordinality
  loop
    if step_row->>''status'' in (''Pending'',''Waiting'') then step_row := step_row || jsonb_build_object(''status'',''Cancelled'',''timestamp'',now()); end if;
    rebuilt := rebuilt || jsonb_build_array(step_row);
  end loop;
  update public.pans
  set status=''Cancelled'',routing_steps=rebuilt,cancelled_at=now(),cancelled_by=actor_id,cancellation_reason=trim(p_reason),updated_at=now()
  where id=p_pan_id returning * into pan_row;

  for target_id in
    select distinct (step->>''userId'')::uuid from jsonb_array_elements(rebuilt) step where nullif(step->>''userId'','''') is not null
    union
    select pan_row.employee_id where notify_employee
  loop
    if target_id is distinct from actor_id then
      perform private.pan_notify(
        target_id,''PAN_UPDATE'',''PAN Cancelled'',
        format(''PAN %s for %s was cancelled. Reason: %s'',p_pan_id,pan_row.employee_name,trim(p_reason)),
        format(''/employees/pan?item=%s'',p_pan_id),p_pan_id,format(''pan:%s:cancelled:%s'',p_pan_id,target_id)
      );
    end if;
  end loop;
  perform private.pan_audit(''CANCEL'',p_pan_id,jsonb_build_object(''reason'',trim(p_reason),''status'',''Cancelled''));
  return pan_row;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."create_interview_rating_assignments"(uuid, uuid, uuid, uuid[], date, text)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.create_interview_rating_assignments(p_candidate_id uuid, p_application_id uuid, p_template_version_id uuid, p_reviewer_user_ids uuid[], p_due_date date, p_interview_round text)
 RETURNS SETOF job_interview_rating_records
 LANGUAGE plpgsql
AS $function$
declare
  actor_id uuid := public.current_hris_user_id();
  actor_email text;
  template_row public.job_interview_templates%rowtype;
  candidate_row public.job_candidates%rowtype;
  application_row public.job_applications%rowtype;
  reviewer_row record;
  rating_row public.job_interview_rating_records%rowtype;
  position_name text;
  applicant_name text;
  existing_id uuid;
  round_name text := coalesce(nullif(btrim(p_interview_round), ''''), ''Round 1'');
begin
  if actor_id is null
     or not public.has_recruitment_admin_access()
     or not public.has_feature_permission(''Interviews'', ''manage'') then
    raise exception ''Only authorized HR or Admin users can assign interview ratings'';
  end if;
  if coalesce(array_length(p_reviewer_user_ids, 1), 0) = 0 then
    raise exception ''At least one reviewer is required'';
  end if;
  if (select count(*) from unnest(p_reviewer_user_ids)) <>
     (select count(distinct reviewer_id) from unnest(p_reviewer_user_ids) reviewer_id) then
    raise exception ''A reviewer can only be assigned once per round'';
  end if;

  select * into template_row
  from public.job_interview_templates
  where id = p_template_version_id and is_current and status = ''Active'';
  if not found then raise exception ''Select an active current interview template''; end if;
  select * into candidate_row from public.job_candidates where id = p_candidate_id;
  if not found then raise exception ''Candidate was not found''; end if;
  select * into application_row
  from public.job_applications
  where id = p_application_id and candidate_id = p_candidate_id;
  if not found then raise exception ''Application does not belong to candidate''; end if;

  select coalesce(nullif(application_row.role_title_snapshot, ''''), jp.title, ''Application'')
  into position_name
  from public.job_posts jp
  where jp.id = application_row.job_post_id;
  position_name := coalesce(position_name, nullif(application_row.role_title_snapshot, ''''), ''Application'');
  applicant_name := btrim(concat_ws('' '', candidate_row.first_name, candidate_row.last_name));
  select email into actor_email from public.hris_users where id = actor_id;

  if exists (
    select 1 from unnest(p_reviewer_user_ids) ids
    where not exists (select 1 from public.hris_users u where u.id = ids)
  ) then
    raise exception ''One or more reviewers could not be found'';
  end if;

  for reviewer_row in
    select u.id, u.full_name, u.email, u.position
    from public.hris_users u
    where u.id = any(p_reviewer_user_ids)
    order by u.full_name
  loop
    select id into existing_id
    from public.job_interview_rating_records
    where candidate_id = p_candidate_id
      and application_id = p_application_id
      and reviewer_user_id = reviewer_row.id
      and interview_round = round_name;

    if existing_id is not null then
      select * into rating_row from public.job_interview_rating_records where id = existing_id;
      return next rating_row;
      continue;
    end if;

    insert into public.job_interview_rating_records (
      candidate_id, application_id, template_version_id, template_group_id, template_version,
      template_snapshot, reviewer_user_id, reviewer_name_snapshot, reviewer_position_snapshot,
      due_date, interview_round, form_data, created_by_user_id
    ) values (
      p_candidate_id, p_application_id, template_row.id, template_row.template_group_id, template_row.version,
      to_jsonb(template_row), reviewer_row.id, coalesce(nullif(reviewer_row.full_name, ''''), reviewer_row.email),
      coalesce(reviewer_row.position, ''''), p_due_date, round_name,
      jsonb_build_object(
        ''candidate_date'', current_date::text,
        ''position_applied_for'', position_name,
        ''applicant_name'', applicant_name,
        ''interviewer_name'', coalesce(nullif(reviewer_row.full_name, ''''), reviewer_row.email),
        ''interviewer_position'', coalesce(reviewer_row.position, ''''),
        ''electronic_acknowledgement'', false
      ), actor_id
    ) returning * into rating_row;

    insert into public.notifications (user_id, title, message, type, link, related_entity_id, dedupe_key)
    values (
      reviewer_row.id::text,
      ''Interview rating assigned'',
      format(''You have been assigned to rate %s for %s (%s).'', applicant_name, position_name, round_name),
      ''INTERVIEW_RATING_ASSIGNED'',
      ''/recruitment/interview-ratings/'' || rating_row.id::text,
      rating_row.id::text,
      ''interview-rating-assigned:'' || rating_row.id::text
    );

    insert into public.audit_logs (user_id, user_email, action, entity, entity_id, details)
    values (actor_id::text, actor_email, ''INTERVIEW_RATING_ASSIGNED'', ''job_interview_rating_records'', rating_row.id::text,
      jsonb_build_object(''candidate_id'', p_candidate_id, ''reviewer_id'', reviewer_row.id,
        ''reviewer_name'', coalesce(reviewer_row.full_name, reviewer_row.email), ''template_version'', template_row.version,
        ''interview_round'', round_name, ''due_date'', p_due_date)::text);
    return next rating_row;
  end loop;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."mark_employee_award_issued"(uuid, text)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.mark_employee_award_issued(p_award_id uuid, p_certificate_snapshot_url text)
 RETURNS employee_awards
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare actor_id uuid := public.current_hris_user_id(); award_row public.employee_awards;
begin
  if actor_id is null then raise exception ''Authentication is required.'' using errcode = ''42501''; end if;
  select * into award_row from public.employee_awards where id = p_award_id for update;
  if not found then raise exception ''Award request not found.'' using errcode = ''P0002''; end if;
  if award_row.status::text <> ''Approved'' then raise exception ''The award must complete approval before issuance.''; end if;
  if nullif(btrim(p_certificate_snapshot_url), '''') is null then raise exception ''A final certificate is required.''; end if;
  if not (public.is_hr_or_admin() or award_row.approver_id = actor_id or award_row.created_by_user_id = actor_id) then
    raise exception ''You do not have permission to issue this award.'' using errcode = ''42501'';
  end if;
  update public.employee_awards
     set status = ''Issued'', certificate_snapshot_url = p_certificate_snapshot_url,
         issued_at = now(), issued_by = actor_id
   where id = p_award_id returning * into award_row;
  perform private.award_notify(award_row.employee_id, ''AWARD_ISSUED'', ''You received an award! 🏆'', ''Your approved award certificate has been issued.'', award_row.id, ''award-issued:'' || award_row.id::text);
  perform private.award_audit(''UPDATE'', award_row.id, ''Issued approved award certificate to employee.'');
  return award_row;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."set_employee_end_date_core_20260824"(uuid, date, text)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.set_employee_end_date_core_20260824(p_target_user_id uuid, p_end_date date, p_reason text)
 RETURNS hris_users
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  actor_id uuid := public.current_hris_user_id();
  actor_email text;
  target_row public.hris_users;
  updated_row public.hris_users;
  auth_banned_before timestamptz;
  auth_banned_after timestamptz;
  previous_access_state text;
  next_access_state text;
  active_admin_count integer;
  revoked_session_count integer := 0;
  revoked_refresh_token_count integer := 0;
begin
  if actor_id is null or not (
    public.has_active_role(''Admin'')
    or public.has_active_role(''HR Manager'')
    or public.has_active_role(''HR Staff'')
  ) then
    raise exception ''Forbidden: HR Staff, HR Manager, or Admin authority is required.'' using errcode = ''42501'';
  end if;
  if not public.can_access_hris_user(p_target_user_id) then
    raise exception ''The employee is outside your authorized scope.'' using errcode = ''42501'';
  end if;
  if actor_id = p_target_user_id then
    raise exception ''You cannot offboard or reactivate your own account.'' using errcode = ''42501'';
  end if;
  if length(trim(coalesce(p_reason, ''''))) < 5 then
    raise exception ''A reason of at least 5 characters is required.'';
  end if;

  select * into target_row
  from public.hris_users
  where id = p_target_user_id
  for update;
  if target_row.id is null then
    raise exception ''Employee account not found.'' using errcode = ''P0002'';
  end if;
  if p_end_date is not null and target_row.date_hired is not null and p_end_date < target_row.date_hired then
    raise exception ''End Date cannot be earlier than Date Hired.'';
  end if;

  if p_end_date is not null and exists (
    select 1 from public.user_roles ur
    where ur.user_id = p_target_user_id and ur.role_id = ''Admin'' and ur.is_active
  ) then
    select count(distinct ur.user_id) into active_admin_count
    from public.user_roles ur
    join public.hris_users u on u.id = ur.user_id
    where ur.role_id = ''Admin'' and ur.is_active and lower(u.status) = ''active'';
    if active_admin_count <= 1 then
      raise exception ''Cannot offboard the final active Admin.'' using errcode = ''42501'';
    end if;
  end if;

  if target_row.auth_user_id is not null then
    select u.banned_until into auth_banned_before
    from auth.users u
    where u.id = target_row.auth_user_id
    for update;
    if not found then
      raise exception ''The linked authentication account was not found; no changes were saved.'';
    end if;
  end if;

  select email into actor_email from public.hris_users where id = actor_id;
  previous_access_state := case
    when target_row.auth_user_id is null then ''No linked auth account''
    when lower(target_row.status) <> ''active'' then ''Disabled''
    when auth_banned_before is not null and auth_banned_before > now() then ''Disabled''
    else ''Enabled''
  end;

  if p_end_date is not null then
    if target_row.auth_user_id is not null then
      update auth.users
      set banned_until = ''9999-12-31 23:59:59+00''::timestamptz,
          updated_at = now()
      where id = target_row.auth_user_id;

      update auth.refresh_tokens
      set revoked = true,
          updated_at = now()
      where user_id = target_row.auth_user_id::text
        and not revoked;
      get diagnostics revoked_refresh_token_count = row_count;

      delete from auth.sessions where user_id = target_row.auth_user_id;
      get diagnostics revoked_session_count = row_count;
      auth_banned_after := ''9999-12-31 23:59:59+00''::timestamptz;
    end if;

    update public.hris_users
    set end_date = p_end_date,
        pre_end_employment_status = case
          when lower(status) = ''active'' then employment_status
          else coalesce(pre_end_employment_status, employment_status)
        end,
        pre_deactivation_banned_until = case
          when lower(status) = ''active'' then auth_banned_before
          else coalesce(pre_deactivation_banned_until, auth_banned_before)
        end,
        employment_status = ''Separated'',
        status = ''Inactive'',
        account_lifecycle_reason = trim(p_reason),
        account_inactivated_at = now(),
        account_inactivated_by = actor_id
    where id = p_target_user_id
    returning * into updated_row;
  else
    auth_banned_after := case
      when target_row.pre_deactivation_banned_until is not null
        and target_row.pre_deactivation_banned_until > now()
      then target_row.pre_deactivation_banned_until
      else null
    end;

    if target_row.auth_user_id is not null then
      update auth.users
      set banned_until = auth_banned_after,
          updated_at = now()
      where id = target_row.auth_user_id;

      update auth.refresh_tokens
      set revoked = true,
          updated_at = now()
      where user_id = target_row.auth_user_id::text
        and not revoked;
      get diagnostics revoked_refresh_token_count = row_count;

      delete from auth.sessions where user_id = target_row.auth_user_id;
      get diagnostics revoked_session_count = row_count;
    end if;

    update public.hris_users
    set end_date = null,
        employment_status = case
          when employment_status = ''Separated'' then pre_end_employment_status
          else employment_status
        end,
        pre_end_employment_status = null,
        pre_deactivation_banned_until = null,
        status = ''Active'',
        account_lifecycle_reason = trim(p_reason),
        account_reactivated_at = now(),
        account_reactivated_by = actor_id
    where id = p_target_user_id
    returning * into updated_row;
  end if;

  next_access_state := case
    when target_row.auth_user_id is null then ''No linked auth account''
    when p_end_date is not null then ''Disabled''
    when auth_banned_after is not null and auth_banned_after > now() then ''Disabled (pre-existing auth restriction)''
    else ''Enabled; fresh sign-in required''
  end;

  insert into public.audit_logs(user_id, user_email, action, entity, entity_id, details)
  values (
    actor_id::text,
    actor_email,
    case when p_end_date is null then ''REACTIVATE'' else ''OFFBOARD'' end,
    ''EmployeeOffboarding'',
    p_target_user_id::text,
    jsonb_build_object(
      ''sourceModule'', ''Employees/ProfileEdit'',
      ''employeeId'', target_row.id,
      ''employeeName'', target_row.full_name,
      ''reason'', trim(p_reason),
      ''confirmedByUserId'', actor_id,
      ''previousEmploymentStatus'', target_row.employment_status,
      ''newEmploymentStatus'', updated_row.employment_status,
      ''previousEndDate'', target_row.end_date,
      ''newEndDate'', updated_row.end_date,
      ''previousAccountAccess'', previous_access_state,
      ''newAccountAccess'', next_access_state,
      ''previousAuthBannedUntil'', auth_banned_before,
      ''newAuthBannedUntil'', auth_banned_after,
      ''revokedSessions'', revoked_session_count,
      ''revokedRefreshTokens'', revoked_refresh_token_count,
      ''confirmedAt'', now()
    )::text
  );

  return updated_row;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."set_employee_end_date"(uuid, date, text)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.set_employee_end_date(p_target_user_id uuid, p_end_date date, p_reason text)
 RETURNS hris_users
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  actor_id uuid := public.current_hris_user_id();
  target_row public.hris_users;
  current_auth_ban timestamptz;
begin
  if actor_id is null or not (
    public.has_active_role(''Admin'')
    or public.has_active_role(''HR Manager'')
    or public.has_active_role(''HR Staff'')
  ) then
    raise exception ''Forbidden: HR Staff, HR Manager, or Admin authority is required.'' using errcode = ''42501'';
  end if;
  if not public.can_access_hris_user(p_target_user_id) then
    raise exception ''The employee is outside your authorized scope.'' using errcode = ''42501'';
  end if;

  select * into target_row
  from public.hris_users
  where id = p_target_user_id
  for update;
  if target_row.id is null then
    raise exception ''Employee account not found.'' using errcode = ''P0002'';
  end if;
  if p_end_date is null and target_row.end_date is null then
    raise exception ''No End Date is recorded. Reactivation must reverse a confirmed employee offboarding.'';
  end if;

  if p_end_date is null and target_row.auth_user_id is not null then
    select u.banned_until into current_auth_ban
    from auth.users u
    where u.id = target_row.auth_user_id
    for update;

    -- 9999-12-31 is the HRIS lifecycle lock. Any other future ban was
    -- established independently and must survive employee reactivation.
    if current_auth_ban is not null
       and current_auth_ban > now()
       and current_auth_ban <> ''9999-12-31 23:59:59+00''::timestamptz then
      update public.hris_users
      set pre_deactivation_banned_until = current_auth_ban
      where id = p_target_user_id;
    end if;
  end if;

  return public.set_employee_end_date_core_20260824(
    p_target_user_id,
    p_end_date,
    p_reason
  );
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."get_accessible_helpdesk_ticket"(uuid)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.get_accessible_helpdesk_ticket(p_ticket_id uuid)
 RETURNS tickets
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  actor_id uuid := public.current_hris_user_id();
  ticket_row public.tickets;
begin
  if actor_id is null then
    raise exception ''Your account is inactive or you are not signed in.'' using errcode = ''42501'';
  end if;
  select * into ticket_row from public.tickets where id = p_ticket_id;
  if ticket_row.id is null then
    raise exception ''The requested ticket was not found.'' using errcode = ''P0002'';
