DO $parity$
BEGIN
  IF to_regprocedure('"public"."notify_job_requisition_current_step"()') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.notify_job_requisition_current_step()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  current_step jsonb;
  stage_message text;
begin
  if new.status::text in (''PendingApproval'', ''Pending Approval'')
    and (tg_op = ''INSERT'' or old.status::text = ''Draft'') then
    select value into current_step
    from jsonb_array_elements(coalesce(new.routing_steps, ''[]''::jsonb)) route(value)
    where value->>''status'' = ''Pending''
    order by coalesce((value->>''order'')::integer, 999)
    limit 1;

    if current_step is not null then
      stage_message := case
        when current_step->>''roleSnapshot'' = ''HR Manager''
          then format(''Requisition %s requires your HR Manager review before it can be sent to BOD.'', new.req_code)
        else format(''Requisition %s requires your BOD approval after HR Manager review.'', new.req_code)
      end;
      insert into public.notifications(user_id, type, title, message, link, is_read, related_entity_id, dedupe_key)
      values(
        current_step->>''userId'', ''JOB_REQUISITION_SUBMITTED'', ''Job Requisition Approval Required'',
        stage_message, ''/recruitment/requisitions?item='' || new.id, false, new.id::text,
        ''job-requisition:'' || new.id::text || '':'' || (current_step->>''userId'')
      )
      on conflict(user_id, dedupe_key) do nothing;
    end if;
  end if;
  return new;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."record_coe_document_event"(uuid, text)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.record_coe_document_event(p_request_id uuid, p_action text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  actor_id uuid := public.current_hris_user_id();
  actor_email text;
  request_row public.coe_requests;
  normalized_action text := upper(btrim(coalesce(p_action, '''')));
begin
  if actor_id is null then
    raise exception ''Authentication is required.'' using errcode = ''42501'';
  end if;
  if normalized_action not in (''PRINT'', ''DOWNLOAD'', ''EMAIL'') then
    raise exception ''Unsupported COE document event.'';
  end if;

  select * into request_row from public.coe_requests where id = p_request_id;
  if request_row.id is null or request_row.status <> ''Approved'' then
    raise exception ''Approved COE document not found.'' using errcode = ''P0002'';
  end if;
  if not (
    request_row.employee_id = actor_id
    or public.is_hr_or_admin()
    or (public.has_feature_permission(''COE'', ''view'') and public.can_access_hris_user(request_row.employee_id))
  ) then
    raise exception ''You do not have access to this COE document.'' using errcode = ''42501'';
  end if;

  select email into actor_email from public.hris_users where id = actor_id;
  insert into public.audit_logs(user_id, user_email, action, entity, entity_id, details)
  values (
    actor_id::text,
    actor_email,
    normalized_action,
    ''COE'',
    p_request_id::text,
    format(''%s approved COE document version %s.'', initcap(lower(normalized_action)), request_row.document_version)
  );
end;
$function$
';
  END IF;
END
$parity$;


