    EXECUTE 'CREATE OR REPLACE FUNCTION private.assign_direct_manager_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare resolved uuid;
begin
  if tg_op = ''INSERT'' or new.employee_id is distinct from old.employee_id or new.direct_manager_id is null then
    resolved := private.resolve_direct_manager_id(new.employee_id);
    new.direct_manager_id := resolved;
    new.approver_configuration_required := resolved is null;
    new.approval_configuration_note := case when resolved is null then ''No active direct manager is configured for this employee.'' else null end;
  end if;
  return new;
end $function$
';
