    ) values (
      old.id,
      next_version,
      to_jsonb(old),
      public.current_hris_user_id(),
      coalesce(current_setting(''app.discipline_change_source'', true), ''editor'')
    );
  end if;
  return new;
end;
$function$
';
  END IF;
END
