DO $parity$
BEGIN
  IF to_regprocedure('"public"."save_discipline_categories"(jsonb)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.save_discipline_categories(p_categories jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  actor_id uuid := public.current_hris_user_id();
  actor_email text;
  item jsonb;
  original_name text;
  category_name text;
  category_description text;
  order_value integer;
  active_value boolean;
  archived_value boolean;
  saved_count integer := 0;
begin
  if actor_id is null or not (
    public.is_hr_or_admin()
    or public.has_feature_permission(''CodeOfDiscipline'', ''manage'')
    or public.has_feature_permission(''CodeOfDiscipline'', ''edit'')
  ) then
    raise exception ''You do not have permission to manage discipline categories.'' using errcode = ''42501'';
  end if;
  if jsonb_typeof(p_categories) <> ''array'' then
    raise exception ''Category payload must be an array.'';
  end if;
  if exists (
    select 1
    from jsonb_array_elements(p_categories) value
    group by lower(btrim(value->>''name''))
    having count(*) > 1
  ) then
    raise exception ''Duplicate category names are not allowed.'';
  end if;

  for item in select value from jsonb_array_elements(p_categories)
  loop
    original_name := nullif(btrim(item->>''originalName''), '''');
    category_name := nullif(btrim(item->>''name''), '''');
    category_description := nullif(btrim(item->>''description''), '''');
    order_value := greatest(coalesce((item->>''displayOrder'')::integer, 0), 0);
    active_value := coalesce((item->>''isActive'')::boolean, true);
    archived_value := coalesce((item->>''archived'')::boolean, false);
    if category_name is null then
      raise exception ''Category name is required.'';
    end if;
    if exists (
      select 1 from public.discipline_categories c
      where lower(btrim(c.name)) = lower(category_name)
        and (original_name is null or c.name <> original_name)
    ) then
      raise exception ''Category "%" already exists.'', category_name;
    end if;

    if original_name is not null and exists (
      select 1 from public.discipline_categories where name = original_name
    ) then
      update public.discipline_categories
         set name = category_name,
             description = category_description,
             display_order = order_value,
             is_active = case when archived_value then false else active_value end,
             archived_at = case when archived_value then coalesce(archived_at, now()) else null end,
             archived_by = case when archived_value then actor_id else null end,
             updated_at = now()
       where name = original_name;
    else
      insert into public.discipline_categories(
        name, description, display_order, is_active, archived_at, archived_by
      ) values (
        category_name, category_description, order_value,
        case when archived_value then false else active_value end,
        case when archived_value then now() else null end,
        case when archived_value then actor_id else null end
      );
    end if;
    saved_count := saved_count + 1;
  end loop;

  select email into actor_email from public.hris_users where id = actor_id;
  insert into public.audit_logs(user_id, user_email, action, entity, entity_id, details)
  values (
    actor_id::text, actor_email, ''UPDATE'', ''DisciplineCategory'', null,
    format(''Saved %s Code of Discipline category record(s).'', saved_count)
  );

  return jsonb_build_object(''saved'', saved_count);
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."archive_discipline_entry"(uuid)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.archive_discipline_entry(p_entry_id uuid)
 RETURNS discipline_entries
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  actor_id uuid := public.current_hris_user_id();
  actor_email text;
  saved_row public.discipline_entries;
begin
  if actor_id is null or not (
    public.is_hr_or_admin()
    or public.has_feature_permission(''CodeOfDiscipline'', ''manage'')
    or public.has_feature_permission(''CodeOfDiscipline'', ''edit'')
  ) then
    raise exception ''You do not have permission to archive discipline entries.'' using errcode = ''42501'';
  end if;

  perform set_config(''app.discipline_change_source'', ''archive'', true);
  update public.discipline_entries
     set is_active = false, archived_at = now(), archived_by = actor_id,
         last_modified_at = now(), last_modified_by_user_id = actor_id
   where id = p_entry_id
   returning * into saved_row;
  if saved_row.id is null then
    raise exception ''Discipline entry not found.'' using errcode = ''P0002'';
  end if;

  select email into actor_email from public.hris_users where id = actor_id;
  insert into public.audit_logs(user_id, user_email, action, entity, entity_id, details)
  values (
    actor_id::text, actor_email, ''UPDATE'', ''DisciplineEntry'', saved_row.id::text,
    format(''Archived Code of Discipline entry %s; version history was preserved.'', saved_row.code)
  );
  return saved_row;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."bulk_import_discipline_entries"(jsonb, text, text)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.bulk_import_discipline_entries(p_rows jsonb, p_mode text, p_file_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  actor_id uuid := public.current_hris_user_id();
  actor_email text;
  import_id uuid;
  row_value jsonb;
  row_number_value integer := 0;
  reported_row_number integer;
  total_count integer := 0;
  inserted_count integer := 0;
  updated_count integer := 0;
  skipped_count integer := 0;
  failed_count integer := 0;
  errors_value jsonb := ''[]''::jsonb;
  seen_codes text[] := array[]::text[];
  code_value text;
  category_input text;
  category_value text;
  severity_value text;
  description_value text;
  status_value text;
  business_unit_input text;
  business_unit_value uuid;
  existing_row public.discipline_entries;
  sanctions_value jsonb;
  sanction_text text;
  sanction_index integer;
  sanction_gap_found boolean;
begin
  if actor_id is null or not (
    public.is_hr_or_admin()
    or public.has_feature_permission(''CodeOfDiscipline'', ''manage'')
    or public.has_feature_permission(''CodeOfDiscipline'', ''edit'')
  ) then
    raise exception ''You do not have permission to import discipline entries.'' using errcode = ''42501'';
  end if;
  if p_mode not in (''add_only'', ''update_only'', ''add_update'') then
    raise exception ''Import mode must be add_only, update_only, or add_update.'';
  end if;
  if jsonb_typeof(p_rows) <> ''array'' then
    raise exception ''Import rows must be a JSON array.'';
  end if;
  if coalesce(jsonb_array_length(p_rows), 0) > 5000 then
    raise exception ''A maximum of 5,000 rows may be imported at one time.'';
  end if;

  total_count := coalesce(jsonb_array_length(p_rows), 0);
  insert into public.discipline_import_runs(uploaded_by, file_name, import_mode, total_rows)
  values (actor_id, coalesce(nullif(btrim(p_file_name), ''''), ''unnamed import''), p_mode, total_count)
  returning id into import_id;

  perform set_config(''app.discipline_change_source'', ''bulk_import:'' || import_id::text, true);

  for row_value in select value from jsonb_array_elements(p_rows)
  loop
    row_number_value := row_number_value + 1;
    reported_row_number := row_number_value;
    begin
      reported_row_number := coalesce(nullif(row_value->>''source_row_number'', '''')::integer, row_number_value);
      code_value := nullif(btrim(row_value->>''code''), '''');
      category_input := nullif(btrim(row_value->>''category''), '''');
      severity_value := initcap(lower(btrim(coalesce(row_value->>''severity_level'', row_value->>''severity''))));
      description_value := nullif(btrim(row_value->>''description''), '''');
      status_value := lower(btrim(coalesce(row_value->>''status'', ''active'')));
      business_unit_input := nullif(btrim(row_value->>''business_unit''), '''');
      business_unit_value := null;
      sanctions_value := ''[]''::jsonb;
      sanction_gap_found := false;

      if code_value is null then raise exception ''Code is required.''; end if;
      if category_input is null then raise exception ''Category is required.''; end if;
      if description_value is null then raise exception ''Description is required.''; end if;
      if severity_value not in (''Low'', ''Medium'', ''High'', ''Critical'') then
        raise exception ''Severity must be Low, Medium, High, or Critical.'';
      end if;
      if status_value not in (''active'', ''inactive'') then
        raise exception ''Status must be Active or Inactive.'';
      end if;
      if lower(code_value) = any(seen_codes) then
        raise exception ''Duplicate code appears more than once in this upload.'';
      end if;
      seen_codes := array_append(seen_codes, lower(code_value));

      select c.name into category_value
      from public.discipline_categories c
      where lower(btrim(c.name)) = lower(category_input) and c.is_active
      limit 1;
      if category_value is null then
        raise exception ''Category does not exist or is inactive.'';
      end if;

      if business_unit_input is not null then
        select bu.id into business_unit_value
        from public.business_units bu
        where bu.id::text = business_unit_input
           or lower(btrim(bu.name)) = lower(business_unit_input)
           or lower(btrim(coalesce(bu.code, ''''))) = lower(business_unit_input)
        limit 1;
        if business_unit_value is null then
          raise exception ''Business unit was not found.'';
        end if;
      end if;

      if exists (
        select 1
        from public.discipline_entries duplicate_entry
        where lower(btrim(duplicate_entry.category)) = lower(category_value)
          and lower(btrim(duplicate_entry.description)) = lower(description_value)
          and lower(btrim(duplicate_entry.code)) <> lower(code_value)
      ) then
        raise exception ''A duplicate entry with the same category and description already exists.'';
      end if;

      if jsonb_typeof(row_value->''sanctions'') = ''array'' then
        sanctions_value := row_value->''sanctions'';
      else
        for sanction_index in 1..10 loop
          sanction_text := nullif(btrim(row_value->>(''sanction_'' || sanction_index::text)), '''');
          if sanction_text is not null then
            if sanction_gap_found then
              raise exception ''Sanction levels cannot contain gaps.'';
            end if;
            sanctions_value := sanctions_value || jsonb_build_array(jsonb_build_object(
              ''offense'', jsonb_array_length(sanctions_value) + 1,
              ''action'', sanction_text
            ));
          else
            sanction_gap_found := true;
          end if;
        end loop;
      end if;
      if exists (
        select 1 from jsonb_array_elements(sanctions_value) sanction
        where nullif(btrim(sanction->>''action''), '''') is null
      ) then
        raise exception ''Sanction values cannot be empty.'';
      end if;

      select * into existing_row
      from public.discipline_entries
      where lower(btrim(code)) = lower(code_value)
      for update;

      if existing_row.id is not null and p_mode = ''add_only'' then
        skipped_count := skipped_count + 1;
        errors_value := errors_value || jsonb_build_array(jsonb_build_object(
          ''rowNumber'', reported_row_number, ''code'', code_value, ''field'', ''code'',
          ''reason'', ''An entry with this code already exists.'',
          ''suggestion'', ''Choose Update matching entries or Add and update.''
        ));
      elsif existing_row.id is null and p_mode = ''update_only'' then
        skipped_count := skipped_count + 1;
        errors_value := errors_value || jsonb_build_array(jsonb_build_object(
          ''rowNumber'', reported_row_number, ''code'', code_value, ''field'', ''code'',
          ''reason'', ''No matching entry exists to update.'',
          ''suggestion'', ''Choose Add and update or Add new entries only.''
        ));
      elsif existing_row.id is not null then
        update public.discipline_entries
           set code = code_value,
               category = category_value,
               description = description_value,
               severity = severity_value::public.severity_level,
               sanctions = sanctions_value,
               business_unit_id = business_unit_value,
               is_active = status_value = ''active'',
               archived_at = case when status_value = ''inactive'' then coalesce(archived_at, now()) else null end,
               archived_by = case when status_value = ''inactive'' then actor_id else null end,
               last_modified_at = now(),
               last_modified_by_user_id = actor_id
         where id = existing_row.id;
        updated_count := updated_count + 1;
      else
        insert into public.discipline_entries(
          code, category, description, severity, sanctions, business_unit_id,
          is_active, archived_at, archived_by, last_modified_at, last_modified_by_user_id
        ) values (
          code_value, category_value, description_value,
          severity_value::public.severity_level, sanctions_value, business_unit_value,
          status_value = ''active'',
          case when status_value = ''inactive'' then now() else null end,
          case when status_value = ''inactive'' then actor_id else null end,
          now(), actor_id
        );
        inserted_count := inserted_count + 1;
      end if;
    exception when others then
      failed_count := failed_count + 1;
      errors_value := errors_value || jsonb_build_array(jsonb_build_object(
        ''rowNumber'', coalesce(reported_row_number, row_number_value),
        ''code'', coalesce(code_value, row_value->>''code'', ''''),
        ''field'', case
          when sqlerrm ilike ''%category%'' then ''category''
          when sqlerrm ilike ''%severity%'' then ''severity_level''
          when sqlerrm ilike ''%business unit%'' then ''business_unit''
          when sqlerrm ilike ''%description%'' then ''description''
          when sqlerrm ilike ''%duplicate entry%'' then ''description''
          when sqlerrm ilike ''%sanction%'' then ''sanctions''
          else ''row''
        end,
        ''reason'', sqlerrm,
        ''suggestion'', ''Correct the highlighted value and import the row again.''
      ));
    end;
  end loop;

  update public.discipline_import_runs
     set imported_rows = inserted_count,
         updated_rows = updated_count,
         skipped_rows = skipped_count,
         failed_rows = failed_count,
         errors = errors_value,
         completed_at = now()
   where id = import_id;

  select email into actor_email from public.hris_users where id = actor_id;
  insert into public.audit_logs(user_id, user_email, action, entity, entity_id, details)
  values (
    actor_id::text, actor_email, ''IMPORT'', ''DisciplineEntry'', import_id::text,
    format(
      ''Imported Code of Discipline file "%s" using %s mode: %s total, %s added, %s updated, %s skipped, %s failed.'',
      coalesce(nullif(btrim(p_file_name), ''''), ''unnamed import''), p_mode, total_count,
      inserted_count, updated_count, skipped_count, failed_count
    )
  );

  return jsonb_build_object(
    ''importId'', import_id,
    ''total'', total_count,
    ''imported'', inserted_count,
    ''updated'', updated_count,
    ''skipped'', skipped_count,
    ''failed'', failed_count,
    ''errors'', errors_value
  );
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."guard_conditional_time_approval_transition"()') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.guard_conditional_time_approval_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  v_request_type text := lower(tg_argv[0]);
  v_actor_id uuid := public.current_hris_user_id();
  v_context jsonb;
  v_is_final_approval boolean;
  v_is_bod_stage boolean;
begin
  if new.status::text is not distinct from old.status::text then
    return new;
  end if;

  v_context := private.time_request_context(v_request_type, new.id);
  v_is_final_approval := new.status::text in (''Approved'', ''WFH_FOR_TIMEKEEPING'');
  v_is_bod_stage := old.status::text in (''PendingBOD'', ''WFH_PENDING_BOD_APPROVAL'');

  if coalesce((v_context->>''requiresBod'')::boolean, false)
     and v_is_final_approval
     and not v_is_bod_stage then
    raise exception ''This request exceeds its configured threshold and must be routed to an assigned BOD approver.''
      using errcode = ''42501'';
  end if;

  if v_is_bod_stage and not exists (
    select 1
    from public.time_request_approval_assignments a
    where a.request_type = v_request_type
      and a.request_id = old.id
      and a.approver_user_id = v_actor_id
      and a.status in (''Approved'', ''Rejected'', ''Skipped'')
      and a.updated_at >= now() - interval ''10 minutes''
  ) then
    raise exception ''Only a currently assigned escalation approver may decide this request.''
      using errcode = ''42501'';
  end if;

  return new;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."get_time_approval_email_payload"(text, uuid)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.get_time_approval_email_payload(p_request_type text, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''''
AS $function$
#variable_conflict use_variable
declare
  actor_id uuid:=public.current_hris_user_id();
  employee_id uuid;
  employee_name text;
  request_dates text;
  status_value text;
  context_value jsonb;
  payload jsonb;
  recipients jsonb;
  is_manager_stage boolean;
begin
  if lower(p_request_type)=''leave'' then
    select r.employee_id,r.employee_name,format(''%s to %s · %s day(s)'',r.start_date,r.end_date,r.duration_days),r.status,r.approval_context
      into employee_id,employee_name,request_dates,status_value,context_value from public.leave_requests r where r.id=p_request_id;
  elsif lower(p_request_type)=''wfh'' then
    select r.employee_id,r.employee_name,format(''%s to %s'',r.date,coalesce(r.end_date,r.date)),r.status,r.approval_context
      into employee_id,employee_name,request_dates,status_value,context_value from public.wfh_requests r where r.id=p_request_id;
  elsif lower(p_request_type)=''overtime'' then
    select r.employee_id,r.employee_name,format(''%s · %s to %s'',r.date,r.start_time,r.end_time),r.status::text,r.approval_context
      into employee_id,employee_name,request_dates,status_value,context_value from public.ot_requests r where r.id=p_request_id;
  else
    raise exception ''Unsupported request type.'' using errcode=''22023'';
  end if;
  if employee_id is null then raise exception ''Request not found.''; end if;
  if actor_id<>employee_id
    and not private.is_direct_reporting_manager(actor_id,employee_id)
    and not public.is_system_admin()
    and not exists (select 1 from public.time_request_approval_assignments a where a.request_type=lower(p_request_type) and a.request_id=p_request_id and a.approver_user_id=actor_id)
  then raise exception ''You are not authorized to prepare this approval email.'' using errcode=''42501''; end if;

  context_value:=case when context_value is null or context_value=''{}''::jsonb
    then private.time_request_context(p_request_type,p_request_id) else context_value end;
  is_manager_stage:=status_value in (''Pending'',''PendingGM'',''WFH_PENDING_DEPT_HEAD_APPROVAL'',''WFH_PENDING_GM_APPROVAL'',''Submitted'',''PendingGM'');
  if is_manager_stage then
    select coalesce(jsonb_agg(jsonb_build_object(''id'',manager.id,''name'',manager.full_name,''email'',manager.email)),''[]''::jsonb)
      into recipients
    from public.hris_users employee join public.hris_users manager
      on employee.reports_to in (manager.id::text,manager.auth_user_id::text,coalesce(manager.employee_id,''''),manager.full_name)
    where employee.id=employee_id and lower(manager.status)=''active'';
  else
    select coalesce(jsonb_agg(jsonb_build_object(''id'',recipient.id,''name'',recipient.full_name,''email'',recipient.email)),''[]''::jsonb)
      into recipients
    from public.time_request_approval_assignments a join public.hris_users recipient on recipient.id=a.approver_user_id
    where a.request_type=lower(p_request_type) and a.request_id=p_request_id and a.status=''Pending'' and lower(recipient.status)=''active'';
  end if;

  select jsonb_build_object(
    ''employeeName'',employee_name,
    ''requestLabel'',case lower(p_request_type) when ''leave'' then ''Leave request'' when ''wfh'' then ''WFH request'' else ''Overtime request'' end,
    ''requestDates'',request_dates,
    ''businessUnit'',coalesce(u.business_unit,''Not assigned''),
    ''department'',coalesce(u.department,''Not assigned''),
    ''status'',status_value,
    ''context'',coalesce(context_value,''{}''::jsonb),
    ''link'',format(''/approvals?type=%s&item=%s'',lower(p_request_type),p_request_id),
    ''recipients'',recipients
  ) into payload
  from public.hris_users u where u.id=employee_id;
  return payload;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."process_time_request_approval"(text, uuid, text, text)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.process_time_request_approval(p_request_type text, p_request_id uuid, p_decision text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  actor_id uuid := public.current_hris_user_id();
  actor_email text;
  employee_id uuid;
  current_status text;
  context_value jsonb;
  requires_bod boolean;
  is_manager_stage boolean;
  assignment public.time_request_approval_assignments;
  required_pending integer;
  bod_approved integer;
  final_status text;
begin
  if actor_id is null then
    raise exception ''Authentication is required.'' using errcode = ''42501'';
  end if;
  if lower(p_decision) not in (''approve'', ''reject'', ''return'') then
    raise exception ''Unsupported approval decision.'' using errcode = ''22023'';
  end if;

  select email into actor_email
  from public.hris_users
  where id = actor_id;

  if lower(p_request_type) = ''leave'' then
    select r.employee_id, r.status
      into employee_id, current_status
    from public.leave_requests r
    where r.id = p_request_id
    for update;
    is_manager_stage := current_status in (''Pending'', ''PendingGM'');
  elsif lower(p_request_type) = ''wfh'' then
    select r.employee_id, r.status
      into employee_id, current_status
    from public.wfh_requests r
    where r.id = p_request_id
    for update;
    is_manager_stage := current_status in (
      ''WFH_PENDING_DEPT_HEAD_APPROVAL'',
      ''WFH_PENDING_GM_APPROVAL''
    );
  elsif lower(p_request_type) = ''overtime'' then
    select r.employee_id, r.status::text
      into employee_id, current_status
    from public.ot_requests r
    where r.id = p_request_id
    for update;
    is_manager_stage := current_status in (''Submitted'', ''PendingGM'');
  else
    raise exception ''Unsupported request type.'' using errcode = ''22023'';
  end if;

  if employee_id is null then raise exception ''Request not found.''; end if;

  if is_manager_stage then
    if not private.is_direct_reporting_manager(actor_id, employee_id) then
      raise exception ''Only the employee''''s direct reporting manager may complete this step.'' using errcode = ''42501'';
    end if;
    if lower(p_decision) = ''return'' then
      raise exception ''Return for clarification is not yet available for this legacy request type.'' using errcode = ''22023'';
    end if;
    if lower(p_decision) = ''reject'' then
      final_status := case lower(p_request_type)
        when ''wfh'' then ''WFH_REJECTED''
        else ''Rejected''
      end;
    else
      context_value := private.time_request_context(p_request_type, p_request_id);
      requires_bod := coalesce((context_value->>''requiresBod'')::boolean, false);
      if requires_bod then
        final_status := case lower(p_request_type)
          when ''leave'' then ''PendingBOD''
          when ''wfh'' then ''WFH_PENDING_BOD_APPROVAL''
          else ''PendingBOD''
        end;
      else
        final_status := case lower(p_request_type)
          when ''wfh'' then ''WFH_FOR_TIMEKEEPING''
          else ''Approved''
        end;
      end if;
    end if;
  else
    select * into assignment
    from public.time_request_approval_assignments a
    where a.request_type = lower(p_request_type)
      and a.request_id = p_request_id
      and a.approver_user_id = actor_id
      and a.status = ''Pending''
    for update;

    if assignment.id is null then
      raise exception ''This request is not assigned to you.'' using errcode = ''42501'';
    end if;

    update public.time_request_approval_assignments
    set status = case lower(p_decision)
          when ''approve'' then ''Approved''
          when ''reject'' then ''Rejected''
          else ''Skipped''
        end,
        decision_note = p_note,
        decided_at = now(),
        updated_at = now()
    where id = assignment.id;

    if lower(p_decision) = ''reject'' and assignment.is_required then
      final_status := case lower(p_request_type)
        when ''wfh'' then ''WFH_REJECTED''
        else ''Rejected''
      end;
    elsif lower(p_decision) = ''return'' then
      final_status := case lower(p_request_type)
        when ''leave'' then ''Pending''
        when ''wfh'' then ''WFH_PENDING_DEPT_HEAD_APPROVAL''
        else ''Submitted''
      end;
    else
      select count(*) into required_pending
      from public.time_request_approval_assignments a
      where a.request_type = lower(p_request_type)
        and a.request_id = p_request_id
        and a.is_required
        and a.status <> ''Approved'';

      select count(*) into bod_approved
      from public.time_request_approval_assignments a
      where a.request_type = lower(p_request_type)
        and a.request_id = p_request_id
        and a.is_bod
        and a.status = ''Approved'';

      if required_pending = 0 and bod_approved >= 1 then
        final_status := case lower(p_request_type)
          when ''wfh'' then ''WFH_FOR_TIMEKEEPING''
          else ''Approved''
        end;
      else
        final_status := current_status;
      end if;
    end if;
  end if;

  context_value := coalesce(
    context_value,
    private.time_request_context(p_request_type, p_request_id)
  );
  requires_bod := coalesce((context_value->>''requiresBod'')::boolean, false);

  -- The trigger accepts this context only for this request, request type, and
  -- already-authorized actor. Clear it before returning to the caller.
  perform set_config(
    ''app.time_request_approval_context'',
    format(''%s:%s:%s'', lower(p_request_type), p_request_id, actor_id),
    true
  );

  if lower(p_request_type) = ''leave'' then
    update public.leave_requests
    set status = final_status,
        approver_id = actor_id,
        approval_route = case when requires_bod then ''BOD_REQUIRED'' else ''MANAGER_ONLY'' end,
        approval_reason = context_value->>''reason'',
        approval_context = context_value,
        approval_routed_at = now(),
        history_log = coalesce(history_log, ''[]''::jsonb) || jsonb_build_array(jsonb_build_object(
          ''action'', initcap(lower(p_decision)),
          ''by'', actor_id,
          ''date'', now(),
          ''note'', coalesce(p_note, context_value->>''reason'')
        ))
    where id = p_request_id;
  elsif lower(p_request_type) = ''wfh'' then
    update public.wfh_requests
    set status = final_status,
        approved_by = actor_id,
        approved_at = now(),
        rejection_reason = case when lower(p_decision) = ''reject'' then p_note else null end,
        approval_route = case when requires_bod then ''BOD_REQUIRED'' else ''MANAGER_ONLY'' end,
        approval_reason = context_value->>''reason'',
        approval_context = context_value,
        approval_routed_at = now()
    where id = p_request_id;
  else
    update public.ot_requests
    set status = final_status::public.ot_status,
        approved_by = actor_id,
        approved_at = now(),
        updated_at = now(),
        manager_note = coalesce(p_note, manager_note),
        approval_route = case when requires_bod then ''BOD_REQUIRED'' else ''MANAGER_ONLY'' end,
        approval_reason = context_value->>''reason'',
        approval_context = context_value,
        approval_routed_at = now(),
        history_log = coalesce(history_log, ''[]''::jsonb) || jsonb_build_array(jsonb_build_object(
          ''action'', initcap(lower(p_decision)),
          ''by'', actor_id,
          ''date'', now(),
          ''note'', coalesce(p_note, context_value->>''reason'')
        ))
    where id = p_request_id;
  end if;

  if is_manager_stage and lower(p_decision) = ''approve'' and requires_bod then
    perform private.assign_time_request_approvers(p_request_type, p_request_id, true);
  end if;

  if final_status in (''Approved'', ''WFH_FOR_TIMEKEEPING'') then
    update public.time_request_approval_assignments
    set status = ''Skipped'',
        updated_at = now(),
        decision_note = coalesce(decision_note, ''Request completed'')
    where request_type = lower(p_request_type)
      and request_id = p_request_id
      and status = ''Pending'';
  end if;

  insert into public.audit_logs(user_id, user_email, action, entity, entity_id, details)
  values(
    actor_id::text,
    actor_email,
    upper(p_decision),
    initcap(lower(p_request_type)),
    p_request_id::text,
    format(
      ''Conditional approval: %s -> %s. %s'',
      current_status,
      final_status,
      context_value->>''reason''
    )
  );

  perform set_config(''app.time_request_approval_context'', '''', true);

  return jsonb_build_object(
    ''requestType'', lower(p_request_type),
    ''requestId'', p_request_id,
    ''previousStatus'', current_status,
    ''status'', final_status,
    ''route'', case when requires_bod then ''BOD_REQUIRED'' else ''MANAGER_ONLY'' end,
    ''context'', context_value,
    ''notifyEscalation'', is_manager_stage
      and lower(p_decision) = ''approve''
      and requires_bod
  );
exception when others then
  perform set_config(''app.time_request_approval_context'', '''', true);
  raise;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."get_coe_approval_authority"()') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.get_coe_approval_authority()
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  authority text;
begin
  select coalesce(config_value->>''authority'', config_value->>''value'')
    into authority
  from public.approver_configs
  where config_key = ''coe_approval_authority'';

  -- HR Manager only is the safe, explicit default when the setting has not
  -- yet been written. Invalid saved values fail closed instead of silently
  -- selecting a broader role.
  if authority is null then
    return ''HR_MANAGER'';
  end if;
  if authority not in (''HR_MANAGER'', ''HR_STAFF'', ''HR_MANAGER_OR_HR_STAFF'') then
    raise exception ''Invalid COE approval authority configuration.'' using errcode = ''22023'';
  end if;
  return authority;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"private"."notify_coe_approvers_after_insert"()') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION private.notify_coe_approvers_after_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
begin
  perform private.coe_notify_approvers(new.id);
  return new;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"private"."coe_notify_approvers"(uuid)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION private.coe_notify_approvers(p_request_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  request_row public.coe_requests;
  authority text;
  approver_row record;
begin
  select * into request_row
  from public.coe_requests
  where id = p_request_id;

  if request_row.id is null
     or request_row.status::text not in (''Pending'', ''Pending HR Manager Approval'') then
    return;
  end if;

  authority := public.get_coe_approval_authority();

  update public.notifications
     set is_read = true
   where related_entity_id = request_row.id::text
     and type = ''COE_UPDATE''
     and title not in (
       ''COE Request Approved'',
       ''COE Request Rejected'',
       ''COE Request Returned for Revision''
     );

  for approver_row in
    select u.id
    from public.hris_users u
    where lower(coalesce(u.status, '''')) = ''active''
      and (
        (authority = ''HR_MANAGER'' and private.coe_user_has_role(u.id, ''HR Manager''))
        or (authority = ''HR_STAFF'' and private.coe_user_has_role(u.id, ''HR Staff''))
        or (
          authority = ''HR_MANAGER_OR_HR_STAFF''
          and (
            private.coe_user_has_role(u.id, ''HR Manager'')
            or private.coe_user_has_role(u.id, ''HR Staff'')
          )
        )
      )
      and private.coe_user_has_workflow_permission(u.id, ''approve'')
      and private.coe_user_can_access_employee(u.id, request_row.employee_id)
  loop
    insert into public.notifications(
      user_id, type, title, message, link, is_read, related_entity_id, dedupe_key
    )
    values (
      approver_row.id::text,
      ''COE_UPDATE'',
      ''COE Request Approval Required'',
      format(''%s has requested a Certificate of Employment.'', request_row.employee_name),
      format(''/employees/coe/requests?requestId=%s'', request_row.id),
      false,
      request_row.id::text,
      format(''coe-approval:%s:%s'', request_row.id, approver_row.id)
    )
    on conflict (user_id, dedupe_key) do update
      set type = excluded.type,
          title = excluded.title,
          message = excluded.message,
          link = excluded.link,
          is_read = false,
          related_entity_id = excluded.related_entity_id,
          created_at = now();
  end loop;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."get_incident_report_user_directory"()') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.get_incident_report_user_directory()
 RETURNS TABLE(id uuid, full_name text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''''
AS $function$
  select
    directory_user.id,
    directory_user.full_name
  from public.hris_users directory_user
  where lower(directory_user.status) = ''active''
    and exists (
      select 1
      from public.hris_users caller
      where caller.id = public.current_hris_id()
        and lower(caller.status) = ''active''
    )
  order by directory_user.full_name;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"private"."enforce_incident_report_revision_state"()') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION private.enforce_incident_report_revision_state()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  actor uuid := public.current_hris_user_id();
begin
  if old.status::text not in (''Returned for Revision'', ''Rejected'') or actor is null then
    return new;
  end if;

  if actor <> old.reported_by then
    raise exception ''This incident report is waiting for revision by the original reporter''
      using errcode = ''42501'';
  end if;

  if new.status is distinct from old.status and new.status::text <> ''Submitted'' then
    raise exception ''Use the resubmit action to advance this incident report''
      using errcode = ''22023'';
  end if;

  return new;
end
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."approve_coe_request_with_snapshot"(uuid)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.approve_coe_request_with_snapshot(p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
begin
  if public.current_hris_user_id() is null then
    raise exception ''Authentication is required.'' using errcode = ''42501'';
  end if;
  raise exception ''Review the COE template and generated content before approval.'' using errcode = ''55000'';
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."reject_coe_request"(uuid, text)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.reject_coe_request(p_request_id uuid, p_reason text)
 RETURNS coe_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  actor_id uuid := public.current_hris_user_id();
  actor_email text;
  request_row public.coe_requests;
  reason_value text := btrim(coalesce(p_reason, ''''));
begin
  if actor_id is null then
    raise exception ''Authentication is required.'' using errcode = ''42501'';
  end if;
  if length(reason_value) < 1 then
    raise exception ''A rejection reason is required.'';
  end if;

  select * into request_row
  from public.coe_requests
  where id = p_request_id
  for update;
  if request_row.id is null then
    raise exception ''COE request not found.'' using errcode = ''P0002'';
  end if;
  if request_row.status::text not in (''Pending'', ''Pending HR Manager Approval'') then
    raise exception ''Only a pending COE request can be rejected.'';
  end if;
  if not private.is_coe_approval_authorized(actor_id, request_row.employee_id, ''reject'') then
    raise exception ''Only the configured HR Manager or HR Staff authority can reject this COE request.'' using errcode = ''42501'';
  end if;

  update public.coe_requests
     set status = ''Rejected'',
         rejection_reason = reason_value,
         approved_by = actor_id,
         approved_at = now(),
         return_reason = null,
         returned_by = null,
         returned_at = null,
         generated_document_url = null,
         updated_at = now()
   where id = p_request_id
   returning * into request_row;

  select email into actor_email from public.hris_users where id = actor_id;
  insert into public.audit_logs(user_id, user_email, action, entity, entity_id, details)
  values (
    actor_id::text,
    actor_email,
    ''REJECT'',
    ''COERequest'',
    p_request_id::text,
    format(''Rejected COE request. Reason: %s'', reason_value)
  );

  return request_row;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."import_assets_batch"(jsonb)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.import_assets_batch(p_rows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  actor_id uuid := public.current_hris_user_id();
  actor_email text;
  row_value jsonb;
  row_number integer := 0;
  total_rows integer := coalesce(pg_catalog.jsonb_array_length(p_rows), 0);
  imported_rows integer := 0;
  assigned_rows integer := 0;
  asset_tag_value text;
  serial_value text;
  employee_identifier text;
  business_unit_identifier text;
  name_value text;
  type_value text;
  status_value text;
  condition_value text;
  purchase_date_value date;
  date_assigned_value date;
  warranty_expiry_value date;
  purchase_cost_value numeric;
  business_unit_id_value text;
  employee_id_value uuid;
  employee_auth_id uuid;
  asset_id_value uuid;
  assignment_id_value uuid;
begin
  if actor_id is null or not (public.is_system_admin() or public.has_feature_permission(''Assets'', ''manage'')) then
    raise exception ''You do not have permission to batch upload assets.'' using errcode=''42501'';
  end if;
  if p_rows is null or pg_catalog.jsonb_typeof(p_rows) <> ''array'' then
    raise exception ''Asset import rows must be a JSON array.'' using errcode=''22023'';
  end if;
  if total_rows = 0 then raise exception ''The asset import file contains no data rows.'' using errcode=''22023''; end if;
  if total_rows > 500 then raise exception ''Asset imports are limited to 500 rows per operation.'' using errcode=''22023''; end if;

  select email into actor_email from public.hris_users where id = actor_id;

  for row_value in select value from pg_catalog.jsonb_array_elements(p_rows) loop
    row_number := row_number + 1;
    asset_tag_value := nullif(btrim(row_value->>''asset_tag''), '''');
    name_value := nullif(btrim(row_value->>''name''), '''');
    type_value := nullif(btrim(row_value->>''type''), '''');
    business_unit_identifier := nullif(btrim(row_value->>''business_unit_id''), '''');
    serial_value := nullif(btrim(row_value->>''serial_number''), '''');
    status_value := coalesce(nullif(btrim(row_value->>''status''), ''''), ''Available'');
    condition_value := coalesce(nullif(btrim(row_value->>''condition''), ''''), ''New'');
    employee_identifier := coalesce(
      nullif(btrim(row_value->>''assigned_employee_id''), ''''),
      nullif(btrim(row_value->>''employee_id''), ''''),
      nullif(btrim(row_value->>''employee_email''), ''''),
      nullif(btrim(row_value->>''assigned_employee''), '''')
    );

    if asset_tag_value is null then raise exception ''Asset row %: asset_tag is required.'', row_number using errcode=''22023''; end if;
    if name_value is null then raise exception ''Asset row %: asset name is required.'', row_number using errcode=''22023''; end if;
    if type_value is null then raise exception ''Asset row %: asset type is required.'', row_number using errcode=''22023''; end if;
    if business_unit_identifier is null then raise exception ''Asset row %: business unit is required.'', row_number using errcode=''22023''; end if;
    if status_value not in (''Available'', ''Assigned'', ''In Repair'', ''Retired'') then raise exception ''Asset row %: invalid asset status “%”.'', row_number, status_value using errcode=''22023''; end if;
    if nullif(btrim(row_value->>''purchase_date''), '''') is null then raise exception ''Asset row %: purchase_date is required.'', row_number using errcode=''22023''; end if;

    select bu.id::text into business_unit_id_value
    from public.business_units bu
    where bu.id::text = business_unit_identifier
       or lower(btrim(coalesce(bu.name, ''''))) = lower(business_unit_identifier)
       or lower(btrim(coalesce(bu.code, ''''))) = lower(business_unit_identifier)
    limit 1;
    if business_unit_id_value is null then raise exception ''Asset row %: business unit “%” was not found.'', row_number, business_unit_identifier using errcode=''22023''; end if;

    employee_id_value := null;
    employee_auth_id := null;
    if employee_identifier is not null then
      select u.id, u.auth_user_id into employee_id_value, employee_auth_id
      from public.hris_users u
      where lower(btrim(coalesce(u.status, ''''))) = ''active''
        and (
          u.id::text = employee_identifier
          or lower(btrim(coalesce(u.email, ''''))) = lower(employee_identifier)
          or lower(btrim(coalesce(u.employee_id, ''''))) = lower(employee_identifier)
        )
      limit 1;
      if employee_id_value is null then raise exception ''Asset row %: employee “%” was not found as an active employee ID or email.'', row_number, employee_identifier using errcode=''22023''; end if;
    end if;

    if exists (select 1 from public.assets a where lower(btrim(a.asset_tag)) = lower(asset_tag_value)) then
      raise exception ''Asset row %: duplicate asset tag “%”.'', row_number, asset_tag_value using errcode=''23505'';
    end if;
    if serial_value is not null and exists (select 1 from public.assets a where lower(btrim(coalesce(a.serial_number, ''''))) = lower(serial_value)) then
      raise exception ''Asset row %: duplicate serial number “%”.'', row_number, serial_value using errcode=''23505'';
    end if;

    purchase_date_value := (row_value->>''purchase_date'')::date;
    date_assigned_value := coalesce(nullif(btrim(row_value->>''date_assigned''), '''')::date, current_date);
    warranty_expiry_value := nullif(btrim(row_value->>''warranty_expiry''), '''')::date;
    purchase_cost_value := coalesce(nullif(btrim(coalesce(row_value->>''purchase_cost'', '''')), '''')::numeric, 0);
    if employee_id_value is not null then status_value := ''Assigned''; end if;
    if employee_id_value is null and status_value = ''Assigned'' then raise exception ''Asset row %: an Assigned asset must have an active employee identifier.'', row_number using errcode=''22023''; end if;

    insert into public.assets(
      asset_tag, name, type, brand, model, serial_number, description, business_unit_id,
      purchase_date, value, status, notes, condition, warranty_expiry, updated_at
    ) values (
      asset_tag_value, name_value, type_value, nullif(btrim(row_value->>''brand''), ''''), nullif(btrim(row_value->>''model''), ''''),
      serial_value, nullif(btrim(row_value->>''description''), ''''), business_unit_id_value,
      purchase_date_value, purchase_cost_value, status_value::public.asset_status, nullif(btrim(row_value->>''notes''), ''''),
      nullif(btrim(row_value->>''condition''), ''''), warranty_expiry_value, now()
    ) returning id into asset_id_value;

    if employee_id_value is not null then
      insert into public.asset_assignments(asset_id, employee_id, date_assigned, condition_on_assign, is_acknowledged)
      values (asset_id_value, employee_id_value, date_assigned_value, condition_value, false)
      returning id into assignment_id_value;
      assigned_rows := assigned_rows + 1;

      insert into public.notifications(user_id, type, title, message, link, related_entity_id, dedupe_key)
      select target_id, ''ASSET_ASSIGNED'', ''Asset Assigned'',
        format(''You have been assigned an asset: %s. Please review and accept.'', name_value),
        format(''/my-profile?acceptAssetAssignmentId=%s'', assignment_id_value), assignment_id_value::text,
        format(''asset-batch-assigned:%s:%s'', assignment_id_value, target_id)
      from (
        select employee_id_value::text as target_id
        union
        select employee_auth_id::text where employee_auth_id is not null
      ) targets
      on conflict (user_id, dedupe_key) do nothing;
    end if;

    insert into public.audit_logs(user_id, user_email, action, entity, entity_id, details)
    values (
      actor_id::text, actor_email, ''CREATE'', ''Asset'', asset_id_value::text,
      format(''Batch imported asset %s%s.'', asset_tag_value, case when employee_id_value is null then '''' else format('' Assigned to employee %s'', employee_id_value) end)
    );
    imported_rows := imported_rows + 1;
  end loop;

  return jsonb_build_object(
    ''total_rows'', total_rows,
    ''imported_rows'', imported_rows,
    ''assigned_rows'', assigned_rows,
    ''failed_rows'', 0,
    ''duplicate_rows'', 0,
    ''invalid_employee_rows'', 0,
    ''missing_required_rows'', 0
  );
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."import_memos_batch"(jsonb, boolean)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.import_memos_batch(p_rows jsonb, p_publish boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  actor_id uuid := public.current_hris_user_id();
  actor_email text;
  row_value jsonb;
  row_number integer := 0;
  total_rows integer := coalesce(pg_catalog.jsonb_array_length(p_rows), 0);
  imported_rows integer := 0;
  published_rows integer := 0;
  memo_id_value uuid;
  memo_number_value text;
  effective_date_value date;
  publication_date_value date;
  status_value public.memo_status;
  body_value text;
  target_business_units_value text[];
  target_departments_value text[];
  target_employee_ids_value uuid[];
  target_input text;
  target_employee_id uuid;
  target_row record;
  notification_target text;
  notification_link text;
begin
  if actor_id is null or not (public.is_system_admin() or public.has_feature_permission(''Feedback'', ''edit'')) then
    raise exception ''You do not have permission to batch upload memos.'' using errcode=''42501'';
  end if;
  if p_rows is null or pg_catalog.jsonb_typeof(p_rows) <> ''array'' then
    raise exception ''Memo import rows must be a JSON array.'' using errcode=''22023'';
  end if;
  if total_rows = 0 then raise exception ''The memo import file contains no data rows.'' using errcode=''22023''; end if;
  if total_rows > 500 then raise exception ''Memo imports are limited to 500 rows per operation.'' using errcode=''22023''; end if;
  select email into actor_email from public.hris_users where id = actor_id;

  for row_value in select value from pg_catalog.jsonb_array_elements(p_rows) loop
    row_number := row_number + 1;
    memo_number_value := nullif(btrim(row_value->>''memo_number''), '''');
    body_value := nullif(row_value->>''body'', '''');
    effective_date_value := (row_value->>''effective_date'')::date;
    publication_date_value := nullif(btrim(row_value->>''publication_date''), '''')::date;
    if memo_number_value is null then raise exception ''Memo row %: memo_number is required.'', row_number using errcode=''22023''; end if;
    if body_value is null then raise exception ''Memo row %: memo content is required.'', row_number using errcode=''22023''; end if;
    if effective_date_value is null then raise exception ''Memo row %: effective_date is required.'', row_number using errcode=''22023''; end if;
    if exists (select 1 from public.memos m where lower(btrim(coalesce(m.memo_number, ''''))) = lower(memo_number_value)) then
      raise exception ''Memo row %: duplicate memo number “%”.'', row_number, memo_number_value using errcode=''23505'';
    end if;

    target_business_units_value := coalesce(array(select pg_catalog.jsonb_array_elements_text(coalesce(row_value->''target_business_units'', ''[]''::jsonb))), ''{}''::text[]);
    target_departments_value := coalesce(array(select pg_catalog.jsonb_array_elements_text(coalesce(row_value->''target_departments'', ''[]''::jsonb))), ''{}''::text[]);
    target_employee_ids_value := ''{}''::uuid[];

    foreach target_input in array target_business_units_value loop
      if target_input = ''All'' then continue; end if;
      if not exists (
        select 1 from public.business_units bu
        where bu.id::text = target_input
           or lower(btrim(coalesce(bu.name, ''''))) = lower(target_input)
           or lower(btrim(coalesce(bu.code, ''''))) = lower(target_input)
      ) then raise exception ''Memo row %: business unit “%” was not found.'', row_number, target_input using errcode=''22023''; end if;
    end loop;
    foreach target_input in array target_departments_value loop
      if target_input = ''All'' then continue; end if;
      if not exists (
        select 1 from public.departments d
        where d.id::text = target_input
           or lower(btrim(coalesce(d.name, ''''))) = lower(target_input)
      ) then raise exception ''Memo row %: department “%” was not found.'', row_number, target_input using errcode=''22023''; end if;
    end loop;

    for target_input in select value from pg_catalog.jsonb_array_elements_text(coalesce(row_value->''target_employee_ids'', ''[]''::jsonb)) items(value) loop
      select u.id into target_employee_id
      from public.hris_users u
      where lower(btrim(coalesce(u.status, ''''))) = ''active''
        and u.id::text = target_input
      limit 1;
      if target_employee_id is null then raise exception ''Memo row %: target employee “%” is not an active employee.'', row_number, target_input using errcode=''22023''; end if;
      target_employee_ids_value := array_append(target_employee_ids_value, target_employee_id);
    end loop;

    if coalesce(array_length(target_business_units_value, 1), 0) = 0
       and coalesce(array_length(target_departments_value, 1), 0) = 0
       and coalesce(array_length(target_employee_ids_value, 1), 0) = 0 then
      target_business_units_value := array[''All''];
      target_departments_value := array[''All''];
    end if;

    status_value := case when p_publish then ''Published''::public.memo_status else ''Draft''::public.memo_status end;
    if p_publish then
      publication_date_value := coalesce(publication_date_value, current_date);
      published_rows := published_rows + 1;
    end if;

    insert into public.memos(
      title, memo_number, memo_type, body, effective_date, publication_date,
      target_departments, target_business_units, target_employee_ids,
      acknowledgement_required, tags, attachments, acknowledgement_tracker,
      acknowledgement_signatures, status, created_by, notes
    ) values (
      nullif(btrim(row_value->>''title''), ''''), memo_number_value, nullif(btrim(row_value->>''memo_type''), ''''), body_value,
      effective_date_value, publication_date_value, target_departments_value, target_business_units_value, target_employee_ids_value,
      coalesce((row_value->>''acknowledgement_required'')::boolean, false),
      coalesce(array(select pg_catalog.jsonb_array_elements_text(coalesce(row_value->''tags'', ''[]''::jsonb))), ''{}''::text[]),
      coalesce(array(select pg_catalog.jsonb_array_elements_text(coalesce(row_value->''attachments'', ''[]''::jsonb))), ''{}''::text[]),
      ''{}''::text[], ''[]''::jsonb, status_value, actor_id, nullif(btrim(row_value->>''notes''), '''')
    ) returning id into memo_id_value;

    if p_publish then
      notification_link := format(''/feedback/memos?memoId=%s'', memo_id_value);
      for target_row in
        select u.id, u.auth_user_id
        from public.hris_users u
        where lower(btrim(coalesce(u.status, ''''))) = ''active''
          and (
            u.id = any(target_employee_ids_value)
            or ''All'' = any(target_business_units_value)
            or ''All'' = any(target_departments_value)
            or u.business_unit = any(target_business_units_value)
            or u.business_unit_id::text = any(target_business_units_value)
            or exists (
              select 1 from public.business_units bu
              where bu.id = u.business_unit_id
                and (bu.name = any(target_business_units_value) or bu.code = any(target_business_units_value))
            )
            or u.department = any(target_departments_value)
            or u.department_id::text = any(target_departments_value)
            or exists (
              select 1 from public.departments d
              where d.id = u.department_id
                and d.name = any(target_departments_value)
            )
          )
      loop
        foreach notification_target in array array_remove(array[target_row.id::text, target_row.auth_user_id::text], null) loop
          insert into public.notifications(user_id, type, title, message, link, related_entity_id, dedupe_key)
          values (
            notification_target, ''MEMO_PUBLISHED'', ''New memo published'',
            format(''%s is now available in the Memo Library.'', row_value->>''title''), notification_link, memo_id_value::text,
            format(''memo-published:%s:%s'', memo_id_value, notification_target)
          ) on conflict (user_id, dedupe_key) do nothing;
        end loop;
      end loop;
    end if;

    insert into public.audit_logs(user_id, user_email, action, entity, entity_id, details)
    values (actor_id::text, actor_email, ''CREATE'', ''Memo'', memo_id_value::text,
      format(''Batch imported memo %s as %s.'', memo_number_value, status_value));
    imported_rows := imported_rows + 1;
  end loop;

  return jsonb_build_object(
    ''total_rows'', total_rows,
    ''imported_rows'', imported_rows,
    ''published_rows'', published_rows,
    ''failed_rows'', 0,
    ''duplicate_rows'', 0,
    ''invalid_employee_rows'', 0,
    ''missing_required_rows'', 0
  );
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."get_conditional_time_approval_config"()') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.get_conditional_time_approval_config()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  cfg jsonb := private.conditional_time_approval_config();
  selected_active_bods integer;
  required_active_bods integer;
  required_count integer := greatest(1, coalesce((cfg->>''required_bod_approvals'')::integer, 1));
begin
  select count(*) into selected_active_bods
  from pg_catalog.jsonb_array_elements_text(coalesce(cfg->''user_ids'', ''[]''::jsonb)) selected(user_id)
  where private.is_time_approval_bod(selected.user_id::uuid);

  select count(*) into required_active_bods
  from pg_catalog.jsonb_array_elements_text(coalesce(cfg->''required_user_ids'', ''[]''::jsonb)) required(user_id)
  where private.is_time_approval_bod(required.user_id::uuid);

  return cfg || jsonb_build_object(
    ''selected_active_bod_count'', selected_active_bods,
    ''required_active_bod_count'', required_active_bods,
    ''valid'', required_active_bods >= required_count,
    ''invalid_reason'', case
      when required_active_bods >= required_count then null
      when selected_active_bods = 0 then ''No selected approver is an active BOD. Check the user role, active status, and saved configuration.''
      else ''At least one selected active BOD approver must be marked as required.''
    end
  );
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."save_conditional_time_approval_config"(jsonb, text)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.save_conditional_time_approval_config(p_config jsonb, p_change_note text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  actor_id uuid := public.current_hris_user_id();
  selected_ids uuid[] := coalesce(array(
    select distinct value::uuid
    from pg_catalog.jsonb_array_elements_text(coalesce(p_config->''user_ids'', ''[]''::jsonb)) items(value)
  ), ''{}''::uuid[]);
  required_ids uuid[] := coalesce(array(
    select distinct value::uuid
    from pg_catalog.jsonb_array_elements_text(coalesce(p_config->''required_user_ids'', ''[]''::jsonb)) items(value)
  ), ''{}''::uuid[]);
  active_count integer;
  required_active_bod_count integer;
  required_bod_count integer := greatest(1, coalesce((p_config->>''required_bod_approvals'')::integer, 1));
  previous_value jsonb;
  normalized jsonb;
begin
  if actor_id is null or not public.is_system_admin() then
    raise exception ''Only an active system Admin can change conditional approval routing.'' using errcode=''42501'';
  end if;
  if nullif(btrim(p_change_note), '''') is null then
    raise exception ''A reason or change note is required.'' using errcode=''22023'';
  end if;
  if coalesce(array_length(selected_ids, 1), 0) = 0 then
    raise exception ''Select at least one escalated approver.'' using errcode=''22023'';
  end if;
  if not required_ids <@ selected_ids then
    raise exception ''Every required approver must also be selected.'' using errcode=''22023'';
  end if;

  select count(*) into active_count
  from public.hris_users
  where id = any(selected_ids)
    and lower(btrim(coalesce(status, ''''))) = ''active'';
  if active_count <> coalesce(array_length(selected_ids, 1), 0) then
    raise exception ''All configured approvers must have active accounts.'' using errcode=''22023'';
  end if;

  select count(*) into required_active_bod_count
  from pg_catalog.unnest(required_ids) candidate(id)
  where private.is_time_approval_bod(candidate.id);
  if required_active_bod_count < required_bod_count then
    raise exception ''At least one selected active BOD approver must be marked as required.'' using errcode=''22023'';
  end if;

  normalized := jsonb_build_object(
    ''user_ids'', to_jsonb(selected_ids),
    ''user_names'', coalesce((select jsonb_agg(u.full_name order by u.full_name) from public.hris_users u where u.id = any(selected_ids)), ''[]''::jsonb),
    ''required_user_ids'', to_jsonb(required_ids),
    ''required_bod_approvals'', required_bod_count,
    ''leave_days_per_remaining_month'', greatest(0.1, coalesce((p_config->>''leave_days_per_remaining_month'')::numeric, 1)),
    ''wfh_days_per_month'', greatest(0, coalesce((p_config->>''wfh_days_per_month'')::integer, 4)),
    ''weekly_total_hours'', greatest(1, coalesce((p_config->>''weekly_total_hours'')::numeric, 50))
  );

  select config_value into previous_value
  from public.approver_configs
  where config_key = ''conditional_time_approvals'';

  insert into public.approver_configs(config_key, config_value, updated_at)
  values (''conditional_time_approvals'', normalized, now())
  on conflict (config_key) do update set config_value = excluded.config_value, updated_at = excluded.updated_at;

  insert into public.audit_logs(user_id, user_email, action, entity, entity_id, details)
  select actor_id::text, u.email, ''UPDATE'', ''ConditionalApprovalConfig'', ''conditional_time_approvals'',
    format(''Conditional approval config changed from %s to %s. Change note: %s'', coalesce(previous_value, ''{}''::jsonb), normalized, p_change_note)
  from public.hris_users u
  where u.id = actor_id;

  return public.get_conditional_time_approval_config();
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."process_employee_award_approval"(uuid, boolean, text)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.process_employee_award_approval(p_award_id uuid, p_approved boolean, p_rejection_reason text DEFAULT NULL::text)
 RETURNS employee_awards
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  actor_id uuid := public.current_hris_user_id();
  award_row public.employee_awards;
  step jsonb;
  updated_steps jsonb := ''[]''::jsonb;
  actor_has_pending_step boolean := false;
  remaining_count integer;
  approved_bod_count integer;
  next_approver uuid;
begin
  if actor_id is null then raise exception ''Authentication is required.'' using errcode = ''42501''; end if;
  select * into award_row from public.employee_awards where id = p_award_id for update;
  if not found then raise exception ''Award request not found.'' using errcode = ''P0002''; end if;
  if award_row.status::text not in (''PendingApproval'', ''Pending Approval'', ''Pending'') then
    raise exception ''This award request is no longer pending.'';
  end if;

  for step in select value from jsonb_array_elements(coalesce(award_row.approver_steps, ''[]''::jsonb)) loop
    if step->>''userId'' = actor_id::text and lower(step->>''status'') = ''pending'' then
      actor_has_pending_step := true;
      step := jsonb_set(step, ''{status}'', to_jsonb((case when p_approved then ''Approved'' else ''Rejected'' end)::text), true);
      step := jsonb_set(step, ''{timestamp}'', to_jsonb(now()::text), true);
      if not p_approved then
        step := jsonb_set(step, ''{rejectionReason}'', to_jsonb(coalesce(nullif(btrim(p_rejection_reason), ''''), ''No reason provided'')), true);
      end if;
    end if;
    updated_steps := updated_steps || jsonb_build_array(step);
  end loop;
  if not actor_has_pending_step then
    raise exception ''This award is not assigned to you for approval.'' using errcode = ''42501'';
  end if;

  if not p_approved then
    update public.employee_awards set approver_steps = updated_steps, status = ''Rejected'',
      rejection_reason = coalesce(nullif(btrim(p_rejection_reason), ''''), ''No reason provided''), decided_at = now()
    where id = p_award_id returning * into award_row;
    perform private.award_notify(award_row.created_by_user_id, ''AWARD_APPROVAL_REQUEST'', ''Award Nomination Rejected'', ''Your award nomination was rejected.'', award_row.id, ''award-rejected:'' || award_row.id::text);
    perform private.award_audit(''REJECT'', award_row.id, ''Rejected assigned award approval step.'');
    return award_row;
  end if;

  select count(*) into remaining_count from jsonb_array_elements(updated_steps) item
  where coalesce((item->>''isRequired'')::boolean, true) and lower(item->>''status'') <> ''approved'';
  select count(*) into approved_bod_count from jsonb_array_elements(updated_steps) item
  where (coalesce((item->>''isBod'')::boolean, false) or item->>''roleSnapshot'' = ''Board of Director'')
    and lower(item->>''status'') = ''approved'';

  if remaining_count = 0 and approved_bod_count > 0 then
    update public.employee_awards set approver_steps = updated_steps, approver_id = actor_id,
      status = ''Approved'', decided_at = now(), rejection_reason = null
    where id = p_award_id returning * into award_row;
    perform private.award_notify(award_row.created_by_user_id, ''AWARD_ISSUED'', ''Award Nomination Approved'', ''Your award nomination completed all required approvals, including BOD approval.'', award_row.id, ''award-approved:'' || award_row.id::text);
    perform private.award_audit(''APPROVE'', award_row.id, ''Completed required award approvals including BOD approval.'');
  else
    select (item->>''userId'')::uuid into next_approver from jsonb_array_elements(updated_steps) item
    where lower(item->>''status'') = ''pending'' order by coalesce((item->>''order'')::integer, 999) limit 1;
    update public.employee_awards set approver_steps = updated_steps, approver_id = coalesce(next_approver, approver_id)
    where id = p_award_id returning * into award_row;
    perform private.award_audit(''APPROVE'', award_row.id, format(''Recorded approval; %s required step(s) remain and BOD approval gate is %s.'', remaining_count, case when approved_bod_count > 0 then ''satisfied'' else ''pending'' end));
  end if;
  return award_row;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."enforce_job_requisition_bod_workflow"()') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.enforce_job_requisition_bod_workflow()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  rpc_write boolean := coalesce(current_setting(''app.job_requisition_rpc'', true), '''') = ''on'';
  approved_hr_order integer;
  approved_bod_order integer;
begin
  if new.status::text in (''PendingApproval'', ''Pending Approval'')
    and (tg_op = ''INSERT'' or old.status::text = ''Draft'') then
    new.routing_steps := private.normalize_job_requisition_route(new.routing_steps);
  elsif tg_op = ''UPDATE'' and old.status::text in (''PendingApproval'', ''Pending Approval'')
    and new.routing_steps is distinct from old.routing_steps and not rpc_write then
    raise exception ''Approval steps can only be changed through the assigned requisition approval action.'' using errcode = ''42501'';
  end if;

  if new.status::text = ''Approved'' and (tg_op = ''INSERT'' or old.status::text <> ''Approved'') then
    select min(coalesce((step->>''order'')::integer, 999)) into approved_hr_order
    from jsonb_array_elements(coalesce(new.routing_steps, ''[]''::jsonb)) step
    where step->>''roleSnapshot'' = ''HR Manager'' and lower(step->>''status'') = ''approved'';

    select min(coalesce((step->>''order'')::integer, 999)) into approved_bod_order
    from jsonb_array_elements(coalesce(new.routing_steps, ''[]''::jsonb)) step
    where (coalesce((step->>''isBod'')::boolean, false) or step->>''roleSnapshot'' = ''Board of Director'')
      and lower(step->>''status'') = ''approved'';

    if approved_hr_order is null then
      raise exception ''A completed HR Manager approval is required before BOD review.'';
    end if;
    if approved_bod_order is null then
      raise exception ''A completed Board of Director approval is required before this requisition can be Approved.'';
    end if;
    if approved_bod_order <= approved_hr_order then
      raise exception ''Board of Director approval must occur after HR Manager approval.'';
    end if;
    if exists (
      select 1 from jsonb_array_elements(coalesce(new.routing_steps, ''[]''::jsonb)) step
      where coalesce((step->>''isRequired'')::boolean, true) and lower(step->>''status'') <> ''approved''
    ) then
      raise exception ''All required requisition approval steps must be completed.'';
    end if;
  end if;
  return new;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."get_pan_directory"()') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.get_pan_directory()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  actor_id uuid := public.current_hris_user_id();
  result jsonb;
begin
  if actor_id is null then
    raise exception ''Authentication is required.'' using errcode = ''42501'';
  end if;

  if not (
    private.pan_actor_can_create()
    or public.has_active_role(''Admin'')
    or public.has_active_role(''Board of Director'')
    or public.has_feature_permission(''PAN'', ''view'')
    or public.has_feature_permission(''PersonnelActionNotices'', ''view'')
  ) then
    raise exception ''PAN access is required to load the employee directory.'' using errcode = ''42501'';
  end if;

  with directory as (
    select
      candidate.id,
      candidate.employee_id,
      candidate.full_name,
      candidate.email,
      candidate.role::text as primary_role,
      candidate.status::text as status,
      candidate.department,
      candidate.department_id,
      candidate.business_unit,
      candidate.business_unit_id,
      candidate.employment_status,
      candidate.position,
      candidate.salary_basic,
      candidate.salary_deminimis,
      candidate.salary_reimbursable,
      candidate.date_hired,
      coalesce((
        select jsonb_agg(to_jsonb(role_names.role_name) order by role_names.role_name)
        from (
          select candidate.role::text as role_name
          union
          select assignment.role_id
          from public.user_roles assignment
          where assignment.user_id = candidate.id and assignment.is_active
        ) role_names
      ), ''[]''::jsonb) as roles,
      public.can_access_hris_user(candidate.id) as is_in_scope,
      (
        candidate.role::text = ''Board of Director''
        or exists (
          select 1 from public.user_roles assignment
          where assignment.user_id = candidate.id
            and assignment.role_id = ''Board of Director''
            and assignment.is_active
        )
      ) as is_bod,
      (
        candidate.role::text <> ''Employee''
        or exists (
          select 1 from public.user_roles assignment
          where assignment.user_id = candidate.id
            and assignment.role_id <> ''Employee''
            and assignment.is_active
        )
      ) as is_approver
    from public.hris_users candidate
    where lower(candidate.status::text) = ''active''
  ), rows_as_json as (
    select directory.*,
      jsonb_build_object(
        ''id'', id,
        ''employee_id'', employee_id,
        ''full_name'', full_name,
        ''email'', email,
        ''role'', primary_role,
        ''roles'', roles,
        ''status'', status,
        ''department'', department,
        ''department_id'', department_id,
        ''business_unit'', business_unit,
        ''business_unit_id'', business_unit_id,
        ''employment_status'', employment_status,
        ''position'', position,
        ''salary_basic'', salary_basic,
        ''salary_deminimis'', salary_deminimis,
        ''salary_reimbursable'', salary_reimbursable,
        ''date_hired'', date_hired
      ) as payload
    from directory
  )
  select jsonb_build_object(
    ''employees'', coalesce((
      select jsonb_agg(payload order by full_name, id)
      from rows_as_json where is_in_scope
    ), ''[]''::jsonb),
    ''approvers'', coalesce((
      select jsonb_agg(payload order by is_bod desc, full_name, id)
      from rows_as_json where is_approver and (is_in_scope or is_bod)
    ), ''[]''::jsonb)
  ) into result;

  return result;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."canonicalize_incident_report_participants"()') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.canonicalize_incident_report_participants()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  involved_count integer;
  witness_count integer;
begin
  select count(*) into involved_count
  from public.hris_users u
  where u.id = any(coalesce(new.involved_employee_ids, ''{}''::uuid[]))
    and lower(u.status) = ''active'';

  if involved_count <> cardinality(coalesce(new.involved_employee_ids, ''{}''::uuid[])) then
    raise exception ''Every involved person must be an active HRIS user.'' using errcode = ''22023'';
  end if;

  select count(*) into witness_count
  from public.hris_users u
  where u.id = any(coalesce(new.witness_ids, ''{}''::uuid[]))
    and lower(u.status) = ''active'';

  if witness_count <> cardinality(coalesce(new.witness_ids, ''{}''::uuid[])) then
    raise exception ''Every witness must be an active HRIS user.'' using errcode = ''22023'';
  end if;

  new.involved_employee_names := coalesce((
    select array_agg(u.full_name order by selected.ordinality)
    from unnest(coalesce(new.involved_employee_ids, ''{}''::uuid[])) with ordinality selected(user_id, ordinality)
    join public.hris_users u on u.id = selected.user_id
  ), ''{}''::text[]);

  new.witness_names := coalesce((
    select array_agg(u.full_name order by selected.ordinality)
    from unnest(coalesce(new.witness_ids, ''{}''::uuid[])) with ordinality selected(user_id, ordinality)
    join public.hris_users u on u.id = selected.user_id
  ), ''{}''::text[]);

  return new;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."notify_hr_on_incident_report_filed"()') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.notify_hr_on_incident_report_filed()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  reporter_name text;
begin
  select full_name into reporter_name from public.hris_users where id = new.reported_by;

  insert into public.notifications (
    user_id, type, title, message, link, is_read, related_entity_id, dedupe_key
  )
  select
    recipient.id::text,
    ''CASE_ASSIGNED'',
    ''New Incident Report Filed'',
    format(
      ''A new Incident Report (%s) has been submitted by %s.'',
      ''TNGIR-'' || lpad(new.case_number::text, 5, ''0''),
      coalesce(reporter_name, ''an employee'')
    ),
    ''/feedback/cases?caseId='' || new.id::text,
    false,
    new.id::text,
    ''incident:'' || new.id::text || '':filed:'' || recipient.id::text
  from (
    select distinct u.id
    from public.hris_users u
    join public.user_roles ur on ur.user_id = u.id and ur.is_active
    join public.roles r on r.id = ur.role_id and r.is_active
    where lower(u.status) = ''active''
      and ur.role_id in (''HR Manager'', ''HR Staff'')
  ) recipient
  on conflict (user_id, dedupe_key) do nothing;

  return new;
end;
$function$
';
  END IF;
END
$parity$;


