DO $parity$
BEGIN
  IF to_regprocedure('"private"."audit_incident_report_change"()') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION private.audit_incident_report_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare actor uuid:=public.current_hris_user_id(); actor_role text:=public.current_hris_role(); action_name text; reason_text text;
begin
  if tg_op=''INSERT'' then
    insert into public.audit_logs(user_id,action,entity,entity_id,details)
    values(new.reported_by::text,case when new.status::text=''Draft'' then ''SAVE_DRAFT'' else ''SUBMIT'' end,''IncidentReport'',new.id::text,
      format(''Incident report created with status %s'',new.status::text));
    return new;
  end if;
  if actor is null then return new; end if;
  if new.status is distinct from old.status then
    action_name:=case
      when old.status::text=''Returned for Revision'' and new.status::text=''Submitted'' then ''RESUBMIT''
      when new.status::text=''Returned for Revision'' then ''RETURN''
      when new.status::text=''Rejected'' then ''REJECT''
      when new.status::text=''Submitted'' then ''SUBMIT''
      when new.status::text=''Closed'' then ''CLOSE''
      else ''STATUS_CHANGE'' end;
    reason_text:=case when new.status::text=''Returned for Revision'' then new.revision_notes
      when new.status::text=''Rejected'' then new.rejection_reason else null end;
    new.revision_history:=coalesce(old.revision_history,''[]''::jsonb)||jsonb_build_array(jsonb_strip_nulls(jsonb_build_object(
      ''action'',action_name,''actorId'',actor,''actorRole'',actor_role,''at'',now(),
      ''previousStatus'',old.status::text,''newStatus'',new.status::text,''reason'',reason_text)));
  elsif actor=old.reported_by and (
    new.category is distinct from old.category or new.description is distinct from old.description
    or new.location is distinct from old.location or new.date_time is distinct from old.date_time
    or new.involved_employee_ids is distinct from old.involved_employee_ids
    or new.witness_ids is distinct from old.witness_ids or new.attachment_urls is distinct from old.attachment_urls
  ) then
    new.revision_history:=coalesce(old.revision_history,''[]''::jsonb)||jsonb_build_array(jsonb_build_object(
      ''action'',''Reporter Edit'',''actorId'',actor,''actorRole'',actor_role,''at'',now(),
      ''previousStatus'',old.status::text,''newStatus'',new.status::text,
      ''attachmentsBefore'',old.attachment_urls,''attachmentsAfter'',new.attachment_urls));
    insert into public.audit_logs(user_id,action,entity,entity_id,details)
    values(actor::text,''EDIT'',''IncidentReport'',new.id::text,''Reporter edited incident details or attachments'');
  end if;
  if new.status is distinct from old.status then
    insert into public.audit_logs(user_id,action,entity,entity_id,details)
    values(actor::text,action_name,''IncidentReport'',new.id::text,
      format(''%s -> %s%s'',old.status::text,new.status::text,case when reason_text is null then '''' else ''. ''||reason_text end));
  end if;
  return new;
end $function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"private"."normalize_job_requisition_route"(jsonb)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION private.normalize_job_requisition_route(p_steps jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  step jsonb;
  result jsonb := ''[]''::jsonb;
  approver_id uuid;
  hr_manager_id uuid;
  hr_manager_name text;
  approver_name text;
  sequence_number integer := 1;
  bod_count integer := 0;
begin
  -- Validate every submitted identity and honor the first selected active HR
  -- Manager. The server resolves a default active HR Manager if the client did
  -- not include one, so RLS or a modified request cannot create a BOD-only route.
  for step in
    select value
    from jsonb_array_elements(coalesce(p_steps, ''[]''::jsonb)) with ordinality route(value, ordinality)
    order by ordinality
  loop
    begin
      approver_id := nullif(step->>''userId'', '''')::uuid;
    exception when invalid_text_representation then
      raise exception ''Every requisition approver must have a valid user ID.'';
    end;

    if approver_id is null then
      continue;
    end if;
    if not (
      private.workflow_user_has_role(approver_id, ''HR Manager'')
      or private.workflow_user_has_role(approver_id, ''Board of Director'')
    ) then
      raise exception ''Requisition approvers must be active HR Manager or Board of Director users.'';
    end if;
    if hr_manager_id is null and private.workflow_user_has_role(approver_id, ''HR Manager'') then
      hr_manager_id := approver_id;
    end if;
  end loop;

  if hr_manager_id is null then
    select candidate.id
      into hr_manager_id
    from public.hris_users candidate
    where private.workflow_user_has_role(candidate.id, ''HR Manager'')
    order by (candidate.role::text = ''HR Manager'') desc, candidate.full_name, candidate.id
    limit 1;
  end if;

  if hr_manager_id is null then
    raise exception ''An active HR Manager is required as the first requisition approval step.'';
  end if;

  select full_name into hr_manager_name from public.hris_users where id = hr_manager_id;
  result := jsonb_build_array(jsonb_build_object(
    ''id'', ''req-step-'' || hr_manager_id::text || ''-hr'',
    ''userId'', hr_manager_id,
    ''name'', hr_manager_name,
    ''role'', ''HR'',
    ''roleSnapshot'', ''HR Manager'',
    ''isBod'', false,
    ''isRequired'', true,
    ''status'', ''Pending'',
    ''order'', 1
  ));

  for step in
    select value
    from jsonb_array_elements(coalesce(p_steps, ''[]''::jsonb)) with ordinality route(value, ordinality)
    order by ordinality
  loop
    approver_id := nullif(step->>''userId'', '''')::uuid;
    if approver_id is null
      or approver_id = hr_manager_id
      or not private.workflow_user_has_role(approver_id, ''Board of Director'')
      or exists (select 1 from jsonb_array_elements(result) prior where prior->>''userId'' = approver_id::text)
    then
      continue;
    end if;

    select full_name into approver_name from public.hris_users where id = approver_id;
    sequence_number := sequence_number + 1;
    bod_count := bod_count + 1;
    result := result || jsonb_build_array(jsonb_build_object(
      ''id'', coalesce(nullif(step->>''id'', ''''), ''req-step-'' || approver_id::text || ''-bod''),
      ''userId'', approver_id,
      ''name'', approver_name,
      ''role'', ''Board of Director'',
      ''roleSnapshot'', ''Board of Director'',
      ''isBod'', true,
      ''isRequired'', true,
      ''status'', ''Waiting'',
      ''order'', sequence_number
    ));
  end loop;

  if bod_count = 0 then
    raise exception ''At least one active Board of Director approver is required after HR Manager approval.'';
  end if;

  return result;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."get_my_pending_time_approval_ids"()') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.get_my_pending_time_approval_ids()
 RETURNS TABLE(request_type text, request_id uuid)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''''
AS $function$
  with actor as (
    select manager.id, manager.auth_user_id, manager.employee_id, manager.full_name
    from public.hris_users manager
    where manager.id = public.current_hris_user_id()
  ), reportees as (
    select employee.id
    from public.hris_users employee
    cross join actor
    where employee.reports_to in (
      actor.id::text,
      actor.auth_user_id::text,
      coalesce(actor.employee_id, ''''),
      actor.full_name
    )
  ), assigned as (
    select assignment.request_type, assignment.request_id
    from public.time_request_approval_assignments assignment
    join actor on actor.id = assignment.approver_user_id
    where assignment.status = ''Pending''
  ), manager_queue as (
    select ''leave''::text as request_type, request.id as request_id
    from public.leave_requests request
    join reportees on reportees.id = request.employee_id
    where request.status in (''Pending'', ''PendingGM'')
    union all
    select ''wfh''::text, request.id
    from public.wfh_requests request
    join reportees on reportees.id = request.employee_id
    where request.status in (''WFH_PENDING_DEPT_HEAD_APPROVAL'', ''WFH_PENDING_GM_APPROVAL'')
    union all
    select ''overtime''::text, request.id
    from public.ot_requests request
    join reportees on reportees.id = request.employee_id
    where request.status in (''Submitted'', ''PendingGM'')
  )
  select request_type, request_id from assigned
  union
  select request_type, request_id from manager_queue
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."return_incident_report_for_revision"(uuid, text)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.return_incident_report_for_revision(p_report_id uuid, p_reason text)
 RETURNS incident_reports
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare actor uuid:=private.require_incident_hr_actor(); actor_role text:=public.current_hris_role(); row public.incident_reports; previous text;
begin
  if nullif(btrim(p_reason),'''') is null then raise exception ''Revision instructions are required''; end if;
  select * into row from public.incident_reports where id=p_report_id for update;
  if row.id is null then raise exception ''Incident report not found''; end if;
  if row.status::text not in (''Submitted'',''HR Review'') then raise exception ''This incident report cannot be returned from its current status''; end if;
  previous:=row.status::text;
  update public.incident_reports set status=''Returned for Revision'',revision_notes=btrim(p_reason),updated_at=now(),
    revision_history=coalesce(revision_history,''[]''::jsonb)||jsonb_build_array(jsonb_build_object(''action'',''Returned for Revision'',''actorId'',actor,''actorRole'',actor_role,''at'',now(),''previousStatus'',previous,''newStatus'',''Returned for Revision'',''reason'',btrim(p_reason)))
  where id=p_report_id returning * into row;
  insert into public.notifications(user_id,type,title,message,link,related_entity_id,dedupe_key)
  values(row.reported_by::text,''GENERAL'',''Incident Report Returned for Revision'',btrim(p_reason),''/feedback/cases?reportId=''||row.id,row.id::text,''ir-return-''||row.id||''-''||extract(epoch from now())::bigint);
  insert into public.audit_logs(user_id,action,entity,entity_id,details)
  values(actor::text,''RETURN'',''IncidentReport'',row.id::text,format(''%s -> Returned for Revision. %s'',previous,btrim(p_reason)));
  return row;
end $function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."reject_incident_report"(uuid, text)') IS NULL THEN
