 RETURNS incident_reports
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare actor uuid:=private.require_incident_hr_actor(); actor_role text:=public.current_hris_role(); row public.incident_reports; previous text;
begin
  if nullif(btrim(p_reason),'''') is null then raise exception ''A rejection reason is required''; end if;
  select * into row from public.incident_reports where id=p_report_id for update;
  if row.id is null then raise exception ''Incident report not found''; end if;
  if row.status::text not in (''Submitted'',''HR Review'') then raise exception ''This incident report cannot be rejected from its current status''; end if;
  previous:=row.status::text;
  update public.incident_reports set status=''Rejected'',rejection_reason=btrim(p_reason),pipeline_stage=''closed'',updated_at=now(),
    revision_history=coalesce(revision_history,''[]''::jsonb)||jsonb_build_array(jsonb_build_object(''action'',''Rejected'',''actorId'',actor,''actorRole'',actor_role,''at'',now(),''previousStatus'',previous,''newStatus'',''Rejected'',''reason'',btrim(p_reason)))
  where id=p_report_id returning * into row;
  insert into public.notifications(user_id,type,title,message,link,related_entity_id,dedupe_key)
  values(row.reported_by::text,''GENERAL'',''Incident Report Rejected'',btrim(p_reason),''/feedback/cases?reportId=''||row.id,row.id::text,''ir-reject-''||row.id);
  insert into public.audit_logs(user_id,action,entity,entity_id,details)
  values(actor::text,''REJECT'',''IncidentReport'',row.id::text,format(''%s -> Rejected. %s'',previous,btrim(p_reason)));
  return row;
end $function$
';
  END IF;
END
