DO $parity$
BEGIN
  IF to_regprocedure('"public"."can_view_time_request"(text, uuid, uuid, uuid, uuid)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.can_view_time_request(p_request_type text, p_request_id uuid, p_employee_id uuid, p_direct_manager_id uuid, p_business_unit_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  v_actor uuid := public.current_hris_user_id();
  v_resource text := case lower(p_request_type)
    when ''overtime'' then ''OT''
    when ''wfh'' then ''WFH''
    when ''leave'' then ''Leave''
    else null
  end;
begin
  if v_actor is null or v_resource is null then return false; end if;
  if v_actor = p_employee_id then return true; end if;
  if private.is_active_time_request_approver(v_actor, p_request_type, p_request_id) then return true; end if;

  return private.has_assigned_feature_permission(v_actor, v_resource, ''view'')
    and public.can_access_hris_user(p_employee_id);
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"private"."audit_incident_report_reporter_revision"()') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION private.audit_incident_report_reporter_revision()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  actor uuid := public.current_hris_user_id();
  changed_fields text[] := array[]::text[];
begin
  if actor is null
     or actor <> old.reported_by
     or old.status::text not in (''Draft'', ''Returned for Revision'', ''Rejected'') then
    return new;
  end if;

  if new.date_time is distinct from old.date_time then changed_fields := array_append(changed_fields, ''incident date''); end if;
  if new.location is distinct from old.location then changed_fields := array_append(changed_fields, ''location''); end if;
  if new.category is distinct from old.category then changed_fields := array_append(changed_fields, ''category''); end if;
  if new.description is distinct from old.description then changed_fields := array_append(changed_fields, ''description''); end if;
  if new.involved_employee_ids is distinct from old.involved_employee_ids then changed_fields := array_append(changed_fields, ''involved employees''); end if;
  if new.witness_ids is distinct from old.witness_ids then changed_fields := array_append(changed_fields, ''witnesses''); end if;
  if new.attachment_url is distinct from old.attachment_url then changed_fields := array_append(changed_fields, ''attachment''); end if;
  if new.signature_data_url is distinct from old.signature_data_url then changed_fields := array_append(changed_fields, ''signature''); end if;

  if cardinality(changed_fields) > 0 then
    new.revision_history := coalesce(old.revision_history, ''[]''::jsonb)
      || jsonb_build_array(jsonb_build_object(
        ''action'', ''Reporter Edited'',
        ''actorId'', actor,
        ''actorRole'', public.current_hris_role(),
        ''at'', now(),
        ''previousStatus'', old.status::text,
        ''newStatus'', new.status::text,
        ''changedFields'', to_jsonb(changed_fields)
      ));

    insert into public.audit_logs(user_id, action, entity, entity_id, details)
    values(
      actor::text,
      ''UPDATE'',
      ''IncidentReport'',
      old.id::text,
      format(''Reporter revised %s while status was %s.'', array_to_string(changed_fields, '', ''), old.status::text)
    );
  end if;

  return new;
end
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."initialize_manpower_request_workflow"()') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.initialize_manpower_request_workflow()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  actor_id uuid := coalesce(public.current_hris_user_id(), new.requester_id);
  business_unit_manager_id uuid;
  requester_role text := private.manpower_role_label(actor_id);
  assignment_message text;
  history_entry jsonb;
begin
  select manager.id
    into business_unit_manager_id
  from public.hris_users manager
  where manager.business_unit_id = new.business_unit_id
    and lower(manager.status) = ''active''
    and private.workflow_user_has_role(manager.id, ''Business Unit Manager'')
  order by manager.full_name, manager.id
  limit 1;

  history_entry := jsonb_build_object(
    ''stage'', ''BUSINESS_UNIT_MANAGER'',
    ''action'', ''Submitted / Assigned'',
    ''approverName'', new.requester_name,
    ''approverRole'', requester_role,
    ''assignedApproverId'', business_unit_manager_id,
    ''assignedApproverName'', case when business_unit_manager_id is null then null else (select full_name from public.hris_users where id = business_unit_manager_id) end,
    ''assignedApproverRole'', case when business_unit_manager_id is null then null else ''Business Unit Manager'' end,
    ''timestamp'', now(),
    ''previousStatus'', null,
    ''newStatus'', ''Pending'',
    ''previousStage'', null,
    ''newStage'', ''BUSINESS_UNIT_MANAGER'',
    ''comments'', case when business_unit_manager_id is null then ''Approver Configuration Required'' else null end
  );

  perform set_config(''app.manpower_workflow_mutation'', ''on'', true);
  update public.manpower_requests request
  set approval_stage = ''BUSINESS_UNIT_MANAGER'',
      approval_issue = case when business_unit_manager_id is null then ''Approver Configuration Required'' else null end,
      approval_history = coalesce(new.approval_history, ''[]''::jsonb) || jsonb_build_array(history_entry)
  where request.id = new.id;

  insert into public.audit_logs (user_id, user_email, action, entity, entity_id, details)
  select actor_id::text, actor.email, ''SUBMIT'', ''ManpowerRequest'', new.id::text,
    jsonb_build_object(
      ''previousStatus'', null,
      ''newStatus'', ''Pending'',
      ''previousStage'', null,
      ''newStage'', ''BUSINESS_UNIT_MANAGER'',
      ''assignedApproverId'', business_unit_manager_id,
      ''assignedApproverRole'', case when business_unit_manager_id is null then null else ''Business Unit Manager'' end,
      ''remarks'', case when business_unit_manager_id is null then ''Approver Configuration Required'' else ''Request submitted'' end
    )::text
  from public.hris_users actor
  where actor.id = actor_id;

  if business_unit_manager_id is null then
    return new;
  end if;

  insert into public.manpower_request_approval_assignments (
    request_id, approval_stage, approver_user_id, approver_role, status
  ) values (
    new.id, ''BUSINESS_UNIT_MANAGER'', business_unit_manager_id, ''Business Unit Manager'', ''Pending''
  ) on conflict (request_id, approval_stage, approver_user_id) do nothing;

  assignment_message := format(
    ''A new on-call manpower request for %s on %s was submitted by %s.'',
    coalesce(new.business_unit_name, ''the selected Business Unit''),
    to_char(new.date_needed, ''Mon DD, YYYY''),
    new.requester_name
  );
  insert into public.notifications (
    user_id, type, title, message, link, is_read, related_entity_id, dedupe_key
  ) values (
    business_unit_manager_id::text,
    ''MANPOWER_REQUEST_SUBMITTED'',
    ''New On-Call Request'',
    assignment_message,
    ''/approvals?type=manpower&item='' || new.id::text,
    false,
    new.id::text,
    format(''manpower:%s:BUSINESS_UNIT_MANAGER:%s'', new.id, business_unit_manager_id)
  ) on conflict (user_id, dedupe_key) do nothing;

  insert into public.audit_logs (user_id, user_email, action, entity, entity_id, details)
  select actor_id::text, actor.email, ''ASSIGN'', ''ManpowerRequest'', new.id::text,
    jsonb_build_object(
      ''approvalStage'', ''BUSINESS_UNIT_MANAGER'',
      ''assignedApproverId'', business_unit_manager_id,
      ''assignedApproverName'', manager.full_name,
      ''assignedApproverRole'', ''Business Unit Manager'',
      ''remarks'', ''Initial Business Unit Manager approval assignment''
    )::text
  from public.hris_users actor
  cross join public.hris_users manager
  where actor.id = actor_id and manager.id = business_unit_manager_id;
  return new;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."get_department_reporting_fte"(uuid, uuid, date)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.get_department_reporting_fte(p_business_unit_id uuid, p_department_id uuid, p_date date)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  reporting_fte integer;
begin
  if public.current_hris_user_id() is null
     or not public.has_feature_permission(''Manpower'', ''create'')
     or not public.has_workflow_permission(''Manpower'', ''submit'') then
    raise exception ''You are not authorized to calculate reporting FTE.'' using errcode = ''42501'';
  end if;
  if not exists (
    select 1 from public.departments department
    where department.id = p_department_id
      and department.business_unit_id = p_business_unit_id
  ) then
    raise exception ''The department is not part of the selected Business Unit.'' using errcode = ''23514'';
  end if;

  select count(distinct assignment.employee_id)::integer
    into reporting_fte
  from public.shift_assignments assignment
  join public.hris_users employee on employee.id = assignment.employee_id
  where assignment.date = p_date
    and assignment.business_unit_id = p_business_unit_id
    and assignment.department_id = p_department_id
    and lower(employee.status) = ''active'';
  return coalesce(reporting_fte, 0);
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."upload_interview_rating_attachment"(uuid, text, text, text, bigint)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.upload_interview_rating_attachment(p_rating_id uuid, p_file_name text, p_storage_path text, p_mime_type text, p_file_size bigint)
 RETURNS job_interview_rating_attachments
 LANGUAGE plpgsql
AS $function$
declare
  actor_id uuid := public.current_hris_user_id();
  attachment_row public.job_interview_rating_attachments%rowtype;
begin
  if actor_id is null
     or not public.has_recruitment_admin_access()
     or not public.has_feature_permission(''Interviews'', ''manage'') then
    raise exception ''Only authorized HR or Admin users can upload scanned interview ratings'';
  end if;
  if nullif(btrim(p_file_name), '''') is null then raise exception ''A scanned rating file name is required''; end if;
  if p_mime_type not in (''application/pdf'', ''image/jpeg'', ''image/png'') then
    raise exception ''Upload a PDF, JPG, or PNG scanned rating form'';
  end if;
  if p_file_size is null or p_file_size < 1 or p_file_size > 10485760 then
    raise exception ''Scanned rating forms must be between 1 byte and 10 MB'';
  end if;
  if p_storage_path is null or p_storage_path !~ (''^interview-ratings/'' || p_rating_id::text || ''/[^/]+$'') then
    raise exception ''Invalid scanned rating storage path'';
  end if;
  if not exists (select 1 from public.job_interview_rating_records r where r.id = p_rating_id) then
    raise exception ''Interview rating was not found'';
  end if;

  insert into public.job_interview_rating_attachments (
    rating_id, file_name, storage_path, mime_type, file_size, uploaded_by_user_id
  ) values (
    p_rating_id, btrim(p_file_name), p_storage_path, p_mime_type, p_file_size, actor_id
  ) returning * into attachment_row;
  return attachment_row;
end;
$function$
';
  END IF;
END
