DO $parity$
BEGIN
  IF to_regprocedure('"public"."get_interview_rating_candidate"(uuid)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.get_interview_rating_candidate(p_rating_id uuid)
 RETURNS TABLE(id uuid, first_name text, last_name text, email text, phone text, source text, tags text[], portfolio_url text, consent_at timestamp with time zone, current_city text, current_employer text, years_relevant_experience text, earliest_start_date date, linkedin_url text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''public'', ''pg_temp''
AS $function$
declare
  actor_id uuid := public.current_hris_user_id();
begin
  if actor_id is null
     or not exists (
       select 1
       from public.job_interview_rating_records r
       where r.id = p_rating_id
         and (r.reviewer_user_id = actor_id or public.has_recruitment_admin_access())
     ) then
