DO $parity$
BEGIN
  IF to_regprocedure('"public"."submit_interview_rating"(uuid, jsonb)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.submit_interview_rating(p_rating_id uuid, p_form_data jsonb)
 RETURNS job_interview_rating_records
 LANGUAGE plpgsql
AS $function$
declare
  actor_id uuid := public.current_hris_user_id();
  actor_email text;
  is_admin boolean := public.has_recruitment_admin_access();
  rating_row public.job_interview_rating_records%rowtype;
  field_row jsonb;
  section_row jsonb;
  field_value jsonb;
  safe_form_data jsonb := coalesce(p_form_data, ''{}''::jsonb);
  old_status text;
  field_type text;
begin
  select * into rating_row from public.job_interview_rating_records where id = p_rating_id for update;
  if not found then raise exception ''Interview rating was not found''; end if;
  if actor_id is null or (rating_row.reviewer_user_id <> actor_id and not is_admin) then
    raise exception ''You are not authorized to submit this interview rating'';
  end if;
  if rating_row.status in (''Submitted'', ''Locked'') or rating_row.locked_at is not null then
    raise exception ''This interview rating has already been submitted'';
  end if;
  if not is_admin then
    safe_form_data := safe_form_data || jsonb_build_object(
      ''candidate_date'', coalesce(rating_row.form_data->''candidate_date'', ''null''::jsonb),
      ''position_applied_for'', coalesce(rating_row.form_data->''position_applied_for'', ''null''::jsonb),
      ''applicant_name'', coalesce(rating_row.form_data->''applicant_name'', ''null''::jsonb),
      ''interviewer_name'', coalesce(rating_row.form_data->''interviewer_name'', ''null''::jsonb),
      ''interviewer_position'', coalesce(rating_row.form_data->''interviewer_position'', ''null''::jsonb)
    );
  end if;

  for section_row in select value from jsonb_array_elements(coalesce(rating_row.template_snapshot->''sections'', ''[]''::jsonb))
  loop
    for field_row in select value from jsonb_array_elements(coalesce(section_row->''fields'', ''[]''::jsonb))
    loop
      if coalesce((field_row->>''required'')::boolean, false) then
        field_value := safe_form_data -> (field_row->>''id'');
        if field_value is null
           or field_value = ''null''::jsonb
           or (jsonb_typeof(field_value) = ''string'' and btrim(field_value #>> ''{}'') = '''') then
          raise exception ''Required interview rating field is missing: %'', field_row->>''label'';
        end if;
        field_type := field_row->>''type'';
        if field_type = ''rating'' and (
          jsonb_typeof(field_value) <> ''object''
          or nullif(field_value->>''value'', '''') is null
          or (field_value->>''value'')::integer not between 1 and 5
        ) then
          raise exception ''Select a valid rating for: %'', field_row->>''label'';
        end if;
        if field_type = ''acknowledgement'' and field_value <> ''true''::jsonb then
          raise exception ''Electronic acknowledgement is required'';
        end if;
      end if;
    end loop;
  end loop;

  old_status := rating_row.status;
  perform set_config(''tng.interview_rating_action'', ''submit'', true);
  update public.job_interview_rating_records
  set form_data = safe_form_data,
      status = ''Submitted'',
      submitted_at = now(),
      locked_at = now(),
      returned_notes = null,
      updated_at = now()
  where id = p_rating_id;
  select * into rating_row from public.job_interview_rating_records where id = p_rating_id;
  select email into actor_email from public.hris_users where id = actor_id;

  insert into public.audit_logs (user_id, user_email, action, entity, entity_id, details)
  values (actor_id::text, actor_email, ''INTERVIEW_RATING_SUBMITTED'', ''job_interview_rating_records'', p_rating_id::text,
    jsonb_build_object(''previous_status'', old_status, ''new_status'', ''Submitted'',
      ''overall_evaluation'', safe_form_data->>''overall_evaluation'', ''job_offer'', safe_form_data->''job_offer'')::text);

  if rating_row.created_by_user_id <> actor_id then
    insert into public.notifications (user_id, title, message, type, link, related_entity_id, dedupe_key)
    values (
      rating_row.created_by_user_id::text,
      ''Interview rating submitted'',
      format(''%s submitted an interview rating for %s.'', rating_row.reviewer_name_snapshot, safe_form_data->>''applicant_name''),
      ''INTERVIEW_RATING_SUBMITTED'',
      ''/recruitment/interview-ratings/'' || rating_row.id::text,
      rating_row.id::text,
      ''interview-rating-submitted:'' || rating_row.id::text
    );
  end if;
  return rating_row;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."audit_job_interview_rating_attachment"()') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.audit_job_interview_rating_attachment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''public'', ''pg_temp''
AS $function$
declare
  actor_id uuid := public.current_hris_user_id();
  actor_email text;
  candidate_id uuid;
  attachment_row public.job_interview_rating_attachments%rowtype;
begin
  attachment_row := case when tg_op = ''INSERT'' then new else old end;
  select r.candidate_id into candidate_id
  from public.job_interview_rating_records r
  where r.id = attachment_row.rating_id;
  select u.email into actor_email from public.hris_users u where u.id = actor_id;
  insert into public.audit_logs (user_id, user_email, action, entity, entity_id, details)
  values (
    actor_id::text,
    actor_email,
    case when tg_op = ''INSERT'' then ''INTERVIEW_RATING_ATTACHMENT_ADDED'' else ''INTERVIEW_RATING_ATTACHMENT_REMOVED'' end,
    ''job_interview_rating_attachments'',
    attachment_row.id::text,
    jsonb_build_object(
      ''rating_id'', attachment_row.rating_id,
      ''candidate_id'', candidate_id,
      ''file_name'', attachment_row.file_name,
      ''storage_path'', attachment_row.storage_path,
      ''mime_type'', attachment_row.mime_type,
      ''file_size'', attachment_row.file_size
    )::text
  );
  return attachment_row;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."reopen_interview_rating"(uuid, text)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.reopen_interview_rating(p_rating_id uuid, p_reason text)
 RETURNS job_interview_rating_records
 LANGUAGE plpgsql
AS $function$
declare
  actor_id uuid := public.current_hris_user_id();
  actor_email text;
  rating_row public.job_interview_rating_records%rowtype;
  old_status text;
begin
  if actor_id is null or not public.has_recruitment_admin_access() or not public.has_feature_permission(''Interviews'', ''manage'') then
    raise exception ''Only authorized HR or Admin users can reopen interview ratings'';
  end if;
  if nullif(btrim(p_reason), '''') is null then raise exception ''A reason is required to reopen an interview rating''; end if;
  select * into rating_row from public.job_interview_rating_records where id = p_rating_id for update;
  if not found then raise exception ''Interview rating was not found''; end if;
  if rating_row.status not in (''Submitted'', ''Locked'') then raise exception ''Only submitted ratings can be reopened''; end if;
  old_status := rating_row.status;
  perform set_config(''tng.interview_rating_action'', ''reopen'', true);
  update public.job_interview_rating_records
  set status = ''Returned for Revision'', locked_at = null, reopened_at = now(), reopened_by_user_id = actor_id,
      returned_notes = btrim(p_reason), updated_at = now()
  where id = p_rating_id;
  select * into rating_row from public.job_interview_rating_records where id = p_rating_id;
  select email into actor_email from public.hris_users where id = actor_id;
  insert into public.audit_logs (user_id, user_email, action, entity, entity_id, details)
  values (actor_id::text, actor_email, ''INTERVIEW_RATING_REOPENED'', ''job_interview_rating_records'', p_rating_id::text,
    jsonb_build_object(''previous_status'', old_status, ''new_status'', ''Returned for Revision'', ''reason'', btrim(p_reason), ''reviewer_id'', rating_row.reviewer_user_id)::text);
  insert into public.notifications (user_id, title, message, type, link, related_entity_id, dedupe_key)
  values (rating_row.reviewer_user_id::text, ''Interview rating returned for revision'', format(''Your interview rating for %s was returned for revision: %s'', rating_row.form_data->>''applicant_name'', btrim(p_reason)), ''INTERVIEW_RATING_RETURNED'', ''/recruitment/interview-ratings/'' || rating_row.id::text, rating_row.id::text, ''interview-rating-returned:'' || rating_row.id::text || '':'' || extract(epoch from now())::bigint);
  return rating_row;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."get_job_offer_approval_package"(uuid)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.get_job_offer_approval_package(p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  request_row public.job_offer_approval_requests%rowtype;
  offer_row public.job_offers%rowtype;
  application_row public.job_applications%rowtype;
  candidate_row public.job_candidates%rowtype;
begin
  if (select public.current_hris_user_id()) is null
     or not (select private.offer_approval_actor_can_view(p_request_id)) then
    raise exception ''You are not authorized to view this offer approval package'' using errcode = ''42501'';
  end if;

  select * into request_row from public.job_offer_approval_requests where id = p_request_id;
  if not found then
    raise exception ''Offer approval request was not found'' using errcode = ''22023'';
  end if;
  select * into offer_row from public.job_offers where id = request_row.offer_id;
  select * into application_row from public.job_applications where id = request_row.application_id;
  select * into candidate_row from public.job_candidates where id = request_row.candidate_id;

  return jsonb_build_object(
    ''request'', to_jsonb(request_row),
    ''offer'', to_jsonb(offer_row),
    ''application'', to_jsonb(application_row),
    ''candidate'', to_jsonb(candidate_row),
    ''ratings'', coalesce((
      select jsonb_agg(to_jsonb(rating) order by rating.created_at asc)
      from public.job_interview_rating_records rating
      where rating.candidate_id = request_row.candidate_id
        and rating.application_id = request_row.application_id
        and exists (
          select 1
          from jsonb_array_elements(request_row.attachment_snapshot) attachment
          where (attachment->>''source'' = ''rating'' and attachment->>''sourceId'' = rating.id::text)
             or (attachment->>''source'' = ''rating_attachment'' and attachment->>''ratingId'' = rating.id::text)
        )
    ), ''[]''::jsonb),
    ''ratingAttachments'', coalesce((
      select jsonb_agg(to_jsonb(attachment_row) order by attachment_row.created_at asc)
      from public.job_interview_rating_attachments attachment_row
      where exists (
        select 1
        from jsonb_array_elements(request_row.attachment_snapshot) attachment
        where attachment->>''source'' = ''rating_attachment''
          and attachment->>''sourceId'' = attachment_row.id::text
      )
    ), ''[]''::jsonb),
    ''candidateDocuments'', coalesce((
      select jsonb_agg(to_jsonb(document) order by document.uploaded_at desc)
      from public.job_candidate_documents document
      where document.candidate_id = request_row.candidate_id
        and exists (
          select 1
          from jsonb_array_elements(request_row.attachment_snapshot) attachment
          where attachment->>''source'' = ''candidate_document''
            and attachment->>''sourceId'' = document.id::text
        )
    ), ''[]''::jsonb),
    ''assignments'', coalesce((
      select jsonb_agg(to_jsonb(assignment) order by assignment.assigned_at asc)
      from public.job_offer_approval_assignments assignment
      where assignment.request_id = request_row.id
    ), ''[]''::jsonb),
    ''approvalTrail'', coalesce((
      select jsonb_agg(to_jsonb(history) order by history.created_at asc)
      from public.job_offer_approval_history history
      where history.request_id = request_row.id
    ), ''[]''::jsonb)
  );
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."lock_interview_rating"(uuid)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.lock_interview_rating(p_rating_id uuid)
 RETURNS job_interview_rating_records
 LANGUAGE plpgsql
AS $function$
declare
  actor_id uuid := public.current_hris_user_id();
  actor_email text;
  rating_row public.job_interview_rating_records%rowtype;
begin
  if actor_id is null or not public.has_recruitment_admin_access() or not public.has_feature_permission(''Interviews'', ''manage'') then
    raise exception ''Only authorized HR or Admin users can lock interview ratings'';
  end if;
  select * into rating_row from public.job_interview_rating_records where id = p_rating_id for update;
  if not found then raise exception ''Interview rating was not found''; end if;
  if rating_row.status <> ''Submitted'' then raise exception ''Only submitted ratings can be locked''; end if;
  perform set_config(''tng.interview_rating_action'', ''lock'', true);
  update public.job_interview_rating_records
  set status = ''Locked'', locked_at = coalesce(locked_at, now()), updated_at = now()
  where id = p_rating_id;
  select * into rating_row from public.job_interview_rating_records where id = p_rating_id;
  select email into actor_email from public.hris_users where id = actor_id;
  insert into public.audit_logs (user_id, user_email, action, entity, entity_id, details)
  values (actor_id::text, actor_email, ''INTERVIEW_RATING_LOCKED'', ''job_interview_rating_records'', p_rating_id::text, jsonb_build_object(''previous_status'', ''Submitted'', ''new_status'', ''Locked'')::text);
  return rating_row;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."remove_interview_rating_attachment"(uuid)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.remove_interview_rating_attachment(p_attachment_id uuid)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
declare
  actor_id uuid := public.current_hris_user_id();
  attachment_row public.job_interview_rating_attachments%rowtype;
begin
  if actor_id is null
     or not public.has_recruitment_admin_access()
     or not public.has_feature_permission(''Interviews'', ''manage'') then
    raise exception ''Only authorized HR or Admin users can remove scanned interview ratings'';
  end if;
  select * into attachment_row
  from public.job_interview_rating_attachments
  where id = p_attachment_id
  for update;
  if not found then raise exception ''Scanned interview rating was not found''; end if;
  delete from public.job_interview_rating_attachments where id = p_attachment_id;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."process_job_offer_approval"(uuid, text, text)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.process_job_offer_approval(p_request_id uuid, p_decision text, p_comments text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''public'', ''pg_temp''
AS $function$
declare
  actor_id uuid := public.current_hris_user_id();
  actor_email text;
  decision text := lower(btrim(coalesce(p_decision, '''')));
  request_row public.job_offer_approval_requests%rowtype;
  assignment_row public.job_offer_approval_assignments%rowtype;
  offer_row public.job_offers%rowtype;
  application_row public.job_applications%rowtype;
  candidate_name text;
  previous_status text;
  next_stage text;
  next_role text;
  next_assigned_count integer;
begin
  if decision not in (''approve'', ''return'', ''reject'') then
    raise exception ''Decision must be approve, return, or reject'' using errcode = ''22023'';
  end if;
  if decision in (''return'', ''reject'') and nullif(btrim(p_comments), '''') is null then
    raise exception ''Comments are required when returning or rejecting an offer approval'' using errcode = ''22023'';
  end if;
  if actor_id is null then raise exception ''Your session is not authorized'' using errcode = ''42501''; end if;

  select * into request_row from public.job_offer_approval_requests where id = p_request_id for update;
  if not found then raise exception ''Offer approval request was not found'' using errcode = ''22023''; end if;
  if request_row.status <> ''Pending Approval'' then
    raise exception ''This offer approval has already been processed'' using errcode = ''P0001'';
  end if;
  select * into assignment_row
  from public.job_offer_approval_assignments assignment
  where assignment.request_id = request_row.id
    and assignment.approver_user_id = actor_id
    and assignment.status = ''Pending''
    and assignment.approval_stage = request_row.approval_stage
  for update;
  if not found then raise exception ''This offer approval is not assigned to you'' using errcode = ''42501''; end if;

  select * into offer_row from public.job_offers where id = request_row.offer_id;
  select * into application_row from public.job_applications where id = request_row.application_id;
  select candidate.first_name || '' '' || candidate.last_name into candidate_name
  from public.job_candidates candidate where candidate.id = request_row.candidate_id;
  select email into actor_email from public.hris_users where id = actor_id;
  previous_status := request_row.status;

  update public.job_offer_approval_assignments
  set status = case when decision = ''approve'' then ''Approved'' when decision = ''return'' then ''Returned for Revision'' else ''Rejected'' end,
      comments = nullif(btrim(p_comments), ''''), decided_at = now()
  where id = assignment_row.id;

  insert into public.job_offer_approval_history (
    request_id, approval_stage, approver_user_id, approver_role, action,
    status_before, status_after, comments, documents_reviewed
  ) values (
    request_row.id, request_row.approval_stage, actor_id, assignment_row.approver_role,
    upper(decision), previous_status,
    case when decision = ''approve'' and request_row.approval_stage = ''HR_MANAGER'' then ''Pending Approval''
      when decision = ''approve'' then ''Approved''
      when decision = ''return'' then ''Returned for Revision'' else ''Rejected'' end,
    nullif(btrim(p_comments), ''''), request_row.attachment_snapshot
  );
  insert into public.audit_logs(user_id, user_email, action, entity, entity_id, details)
  values (
    actor_id::text, actor_email, ''OFFER_APPROVAL_'' || upper(decision), ''job_offer_approval_requests'', request_row.id::text,
    jsonb_build_object(''offer_id'', request_row.offer_id, ''candidate_id'', request_row.candidate_id,
      ''approver_role'', assignment_row.approver_role, ''approval_stage'', request_row.approval_stage,
      ''previous_status'', previous_status,
      ''new_status'', case when decision = ''approve'' and request_row.approval_stage = ''HR_MANAGER'' then ''Pending Approval''
        when decision = ''approve'' then ''Approved'' when decision = ''return'' then ''Returned for Revision'' else ''Rejected'' end,
      ''comments'', nullif(btrim(p_comments), ''''), ''documents_reviewed'', request_row.attachment_snapshot)::text
  );

  if decision <> ''approve'' then
    update public.job_offer_approval_requests
    set status = case when decision = ''return'' then ''Returned for Revision'' else ''Rejected'' end,
        updated_at = now(), completed_at = now()
    where id = request_row.id;
    update public.job_offer_approval_assignments
    set status = ''Cancelled'', comments = ''Closed by another approval decision.'', decided_at = now()
    where request_id = request_row.id and status = ''Pending'';
    update public.job_offers
    set approval_status = case when decision = ''return'' then ''Returned for Revision'' else ''Rejected'' end,
        updated_at = now()
    where id = request_row.offer_id;
    insert into public.notifications(user_id, type, title, message, link, is_read, related_entity_id, dedupe_key)
    values (
      request_row.requester_user_id::text, ''OFFER_APPROVAL_'' || upper(decision),
      case when decision = ''return'' then ''Offer approval returned for revision'' else ''Offer approval rejected'' end,
      format(''The offer approval package for %s was %s. %s'', coalesce(candidate_name, ''the candidate''),
        case when decision = ''return'' then ''returned for revision'' else ''rejected'' end, coalesce(p_comments, '''')),
      ''/recruitment/offers?approval='' || request_row.id::text, false, request_row.id::text,
      ''offer-approval-decision:'' || request_row.id::text || '':'' || request_row.revision::text
    );
    return jsonb_build_object(''requestId'', request_row.id, ''status'', case when decision = ''return'' then ''Returned for Revision'' else ''Rejected'' end);
  end if;

  update public.job_offer_approval_assignments
  set status = ''Cancelled'', comments = ''Closed after another approval in this stage.'', decided_at = now()
  where request_id = request_row.id and status = ''Pending'';

  if request_row.approval_stage = ''HR_MANAGER'' then
    next_stage := ''BOD_GM'';
    update public.job_offer_approval_requests
    set status = ''Pending Approval'', approval_stage = next_stage, updated_at = now(), completed_at = null
    where id = request_row.id;
    insert into public.job_offer_approval_assignments (request_id, approver_user_id, approver_role, approval_stage)
    select request_row.id, user_row.id,
      case when private.offer_user_has_role(user_row.id, ''Board of Director'') then ''Board of Director'' else ''General Manager'' end,
      next_stage
    from public.hris_users user_row
    where lower(btrim(coalesce(user_row.status, ''''))) = ''active''
      and (private.offer_user_has_role(user_row.id, ''Board of Director'') or private.offer_user_has_role(user_row.id, ''GeneralManager''));
    select count(*) into next_assigned_count
    from public.job_offer_approval_assignments assignment
    where assignment.request_id = request_row.id and assignment.approval_stage = next_stage and assignment.status = ''Pending'';
    if next_assigned_count = 0 then
      raise exception ''No active BOD or General Manager approver is configured'' using errcode = ''22023'';
    end if;
    update public.job_offers set approval_status = ''Pending Approval'', updated_at = now() where id = request_row.offer_id;
    insert into public.job_offer_approval_history (
      request_id, approval_stage, approver_user_id, approver_role, action,
      status_before, status_after, comments, documents_reviewed
    ) values (
      request_row.id, next_stage, null, ''BOD / General Manager Pool'', ''STAGE_ADVANCED'',
      ''Pending Approval'', ''Pending Approval'', null, request_row.attachment_snapshot
    );
    insert into public.notifications(user_id, type, title, message, link, is_read, related_entity_id, dedupe_key)
    select assignment.approver_user_id::text, ''OFFER_APPROVAL'',
      ''Offer approval package ready for final review'',
      format(''The HR review is complete. The offer package for %s is awaiting your BOD / GM approval.'', coalesce(candidate_name, ''the candidate'')),
      ''/approvals?type=offer&item='' || request_row.id::text, false, request_row.id::text,
      ''offer-approval-stage:'' || request_row.id::text || '':'' || request_row.revision::text || '':'' || assignment.approver_user_id::text
    from public.job_offer_approval_assignments assignment
    where assignment.request_id = request_row.id and assignment.approval_stage = next_stage;
    return jsonb_build_object(''requestId'', request_row.id, ''status'', ''Pending Approval'', ''approvalStage'', next_stage);
  end if;

  update public.job_offer_approval_requests
  set status = ''Approved'', updated_at = now(), completed_at = now()
  where id = request_row.id;
  update public.job_offers
  set approval_status = ''Approved'', updated_at = now()
  where id = request_row.offer_id;
  insert into public.notifications(user_id, type, title, message, link, is_read, related_entity_id, dedupe_key)
  values (
    request_row.requester_user_id::text, ''OFFER_APPROVAL_APPROVED'', ''Offer approval completed'',
    format(''The offer approval package for %s was approved by %s.'', coalesce(candidate_name, ''the candidate''), coalesce(actor_email, ''an approver'')),
    ''/recruitment/offers?approval='' || request_row.id::text, false, request_row.id::text,
    ''offer-approval-complete:'' || request_row.id::text || '':'' || request_row.revision::text
  );
  return jsonb_build_object(''requestId'', request_row.id, ''status'', ''Approved'', ''approvalStage'', request_row.approval_stage);
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."get_my_pending_offer_approval_ids"()') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.get_my_pending_offer_approval_ids()
 RETURNS TABLE(request_id uuid, offer_id uuid, approval_stage text, assigned_at timestamp with time zone)
 LANGUAGE sql
 SET search_path TO ''public'', ''pg_temp''
AS $function$
  select assignment.request_id, request.offer_id, assignment.approval_stage, assignment.assigned_at
  from public.job_offer_approval_assignments assignment
  join public.job_offer_approval_requests request on request.id = assignment.request_id
  where assignment.approver_user_id = public.current_hris_user_id()
    and assignment.status = ''Pending''
    and request.status = ''Pending Approval''
    and request.approval_stage = assignment.approval_stage
  order by assignment.assigned_at asc;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"private"."can_issue_nte"()') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION private.can_issue_nte()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''''
AS $function$
  select exists (
    select 1
    from public.user_roles ur
    join public.roles r on r.id = ur.role_id and r.is_active
    where ur.user_id = public.current_hris_user_id()
      and ur.is_active
      and ur.role_id in (''HR Manager'', ''HR Staff'', ''Admin'')
  ) and (
    public.has_feature_permission(''NTEs'', ''create'')
    or public.has_feature_permission(''NTEs'', ''manage'')
  )
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."remove_job_candidate_document"(uuid)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.remove_job_candidate_document(p_document_id uuid)
 RETURNS job_candidate_documents
 LANGUAGE plpgsql
 SET search_path TO ''''
AS $function$
declare
  actor_id uuid := (select public.current_hris_user_id());
  actor_email text;
  document_row public.job_candidate_documents%rowtype;
begin
  if actor_id is null or not (select public.has_recruitment_admin_access()) then
    raise exception ''Only authorized recruitment users can remove candidate documents'' using errcode = ''42501'';
  end if;

  select * into document_row
  from public.job_candidate_documents
  where id = p_document_id
  for update;
  if not found then
    raise exception ''Candidate document was not found'' using errcode = ''22023'';
  end if;

  if document_row.archived_at is null then
    update public.job_candidate_documents
    set archived_at = now()
    where id = document_row.id
    returning * into document_row;

    select email into actor_email from public.hris_users where id = actor_id;
    insert into public.audit_logs(user_id, user_email, action, entity, entity_id, details)
    values (
      actor_id::text,
      actor_email,
      ''CANDIDATE_DOCUMENT_ARCHIVED'',
      ''job_candidate_documents'',
      document_row.id::text,
      jsonb_build_object(
        ''candidate_id'', document_row.candidate_id,
        ''application_id'', document_row.application_id,
        ''document_type'', document_row.document_type,
        ''file_name'', document_row.file_name
      )::text
    );
  end if;

  return document_row;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."create_job_offer_approval_request"(uuid, jsonb, jsonb, boolean, text)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.create_job_offer_approval_request(p_offer_id uuid, p_attachment_snapshot jsonb, p_package_snapshot jsonb DEFAULT ''{}''::jsonb, p_override_incomplete_ratings boolean DEFAULT false, p_override_reason text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''public'', ''pg_temp''
AS $function$
declare
  actor_id uuid := public.current_hris_user_id();
  actor_email text;
  offer_row public.job_offers%rowtype;
  application_row public.job_applications%rowtype;
  request_row public.job_offer_approval_requests%rowtype;
  document jsonb;
  document_type text;
  source_kind text;
  source_id text;
  rating_id text;
  total_ratings integer;
  submitted_ratings integer;
  has_resume boolean := false;
  has_offer boolean := false;
  has_interview_rating boolean := false;
  initial_stage text;
  v_request_id uuid;
  revision_number integer;
  assigned_count integer;
  approver_role text;
begin
  if actor_id is null
     or not public.has_recruitment_admin_access()
     or not (public.has_workflow_permission(''RecruitmentOffers'', ''submit'') or public.is_system_admin()) then
    raise exception ''Only authorized recruitment users can request offer approval'' using errcode = ''42501'';
  end if;
  if p_attachment_snapshot is null or jsonb_typeof(p_attachment_snapshot) <> ''array'' then
    raise exception ''The approval package must include its selected documents'' using errcode = ''22023'';
  end if;

  select * into offer_row from public.job_offers where id = p_offer_id for update;
  if not found then raise exception ''Offer was not found'' using errcode = ''22023''; end if;
  select * into application_row from public.job_applications where id = offer_row.application_id;
  if not found then raise exception ''Offer application was not found'' using errcode = ''22023''; end if;

  select count(*) into total_ratings
  from public.job_interview_rating_records rating
  where rating.candidate_id = application_row.candidate_id
    and rating.application_id = application_row.id;
  select count(*) into submitted_ratings
  from public.job_interview_rating_records rating
  where rating.candidate_id = application_row.candidate_id
    and rating.application_id = application_row.id
    and rating.status in (''Submitted'', ''Locked'');

  for document in select value from jsonb_array_elements(p_attachment_snapshot) loop
    document_type := btrim(coalesce(document->>''documentType'', ''''));
    source_kind := btrim(coalesce(document->>''source'', ''''));
    source_id := btrim(coalesce(document->>''sourceId'', ''''));
    rating_id := btrim(coalesce(document->>''ratingId'', source_id));

    if document_type = ''Resume'' then
      if source_kind = ''resume'' and source_id = application_row.id::text
         and (nullif(application_row.resume_file_url, '''') is not null
           or nullif(application_row.resume_file_path, '''') is not null
           or nullif(application_row.resume_link, '''') is not null
           or nullif(application_row.resume_url, '''') is not null) then
        has_resume := true;
      elsif source_kind = ''candidate_document''
        and exists (
          select 1 from public.job_candidate_documents candidate_document
          where candidate_document.id::text = source_id
            and candidate_document.candidate_id = application_row.candidate_id
            and candidate_document.document_type = ''Resume''
            and candidate_document.archived_at is null
        ) then
        has_resume := true;
      else
        raise exception ''The selected resume does not belong to this candidate'' using errcode = ''42501'';
      end if;
    elsif document_type = ''Interview Rating'' then
      if source_kind = ''rating'' and exists (
        select 1 from public.job_interview_rating_records rating
        where rating.id::text = source_id
          and rating.candidate_id = application_row.candidate_id
          and rating.application_id = application_row.id
          and rating.status in (''Submitted'', ''Locked'')
      ) then
        has_interview_rating := true;
      elsif source_kind = ''rating_attachment'' and exists (
        select 1
        from public.job_interview_rating_attachments attachment
        join public.job_interview_rating_records rating on rating.id = attachment.rating_id
        where attachment.id::text = source_id
          and rating.id::text = rating_id
          and rating.candidate_id = application_row.candidate_id
          and rating.application_id = application_row.id
          and rating.status in (''Submitted'', ''Locked'')
      ) then
        has_interview_rating := true;
      elsif source_kind = ''candidate_document''
        and exists (
          select 1 from public.job_candidate_documents candidate_document
          where candidate_document.id::text = source_id
            and candidate_document.candidate_id = application_row.candidate_id
            and candidate_document.document_type = ''Interview Rating''
            and candidate_document.archived_at is null
        ) then
        has_interview_rating := true;
      else
        raise exception ''The selected interview rating is not a submitted rating for this candidate'' using errcode = ''42501'';
      end if;
    elsif document_type = ''Offer'' then
      if source_kind = ''offer'' and source_id = offer_row.id::text then
        has_offer := true;
      else
        raise exception ''The selected offer document does not match this offer'' using errcode = ''42501'';
      end if;
    elsif document_type = ''Other Supporting Document'' then
      if source_kind <> ''candidate_document'' or not exists (
        select 1 from public.job_candidate_documents candidate_document
        where candidate_document.id::text = source_id
          and candidate_document.candidate_id = application_row.candidate_id
          and candidate_document.document_type = ''Other Supporting Document''
          and candidate_document.archived_at is null
      ) then
        raise exception ''The selected supporting document does not belong to this candidate'' using errcode = ''42501'';
      end if;
    else
      raise exception ''Every package item must have a valid document type'' using errcode = ''22023'';
    end if;
  end loop;

  if not has_resume then raise exception ''Attach a resume before requesting offer approval'' using errcode = ''22023''; end if;
  if not has_offer then raise exception ''Attach the offer before requesting offer approval'' using errcode = ''22023''; end if;
  if not has_interview_rating and not p_override_incomplete_ratings then
    raise exception ''Attach at least one submitted interview rating, or use an authorized override'' using errcode = ''22023'';
  end if;
  if total_ratings = 0 and not p_override_incomplete_ratings then
    raise exception ''Interview ratings are required before requesting offer approval'' using errcode = ''22023'';
  end if;
  if total_ratings > submitted_ratings and not p_override_incomplete_ratings then
    raise exception ''All assigned interview ratings must be submitted before requesting offer approval'' using errcode = ''22023'';
  end if;
  if p_override_incomplete_ratings then
    if not (public.is_system_admin() or public.has_active_role(''HR Manager'')) then
      raise exception ''Only an Admin or HR Manager can override incomplete interview ratings'' using errcode = ''42501'';
    end if;
    if nullif(btrim(p_override_reason), '''') is null then
      raise exception ''An explanation is required for an incomplete-ratings override'' using errcode = ''22023'';
    end if;
  end if;

  initial_stage := case
    when public.has_active_role(''HR Staff'') and not public.has_active_role(''HR Manager'') then ''HR_MANAGER''
    else ''BOD_GM''
  end;
  select email into actor_email from public.hris_users where id = actor_id;

  select * into request_row
  from public.job_offer_approval_requests request
  where request.offer_id = p_offer_id
    and request.status = ''Returned for Revision''
  for update;

  if request_row.id is not null then
    v_request_id := request_row.id;
    revision_number := request_row.revision + 1;
    delete from public.job_offer_approval_assignments assignment
    where assignment.request_id = v_request_id;
    update public.job_offer_approval_requests
    set application_id = application_row.id,
        candidate_id = application_row.candidate_id,
        requester_user_id = actor_id,
        status = ''Pending Approval'',
        approval_stage = initial_stage,
        revision = revision_number,
        attachment_snapshot = p_attachment_snapshot,
        package_snapshot = coalesce(p_package_snapshot, ''{}''::jsonb),
        override_incomplete_ratings = coalesce(p_override_incomplete_ratings, false),
        override_reason = nullif(btrim(p_override_reason), ''''),
        submitted_at = now(), updated_at = now(), completed_at = null
    where id = v_request_id
    returning * into request_row;
  else
    select * into request_row
    from public.job_offer_approval_requests request
    where request.offer_id = p_offer_id
      and request.status = ''Pending Approval''
    for update;
    if request_row.id is not null then
      raise exception ''This offer already has a pending approval request'' using errcode = ''23505'';
    end if;
    insert into public.job_offer_approval_requests (
      offer_id, application_id, candidate_id, requester_user_id, status, approval_stage,
      attachment_snapshot, package_snapshot, override_incomplete_ratings, override_reason
    ) values (
      p_offer_id, application_row.id, application_row.candidate_id, actor_id, ''Pending Approval'', initial_stage,
      p_attachment_snapshot, coalesce(p_package_snapshot, ''{}''::jsonb), coalesce(p_override_incomplete_ratings, false),
      nullif(btrim(p_override_reason), '''')
    ) returning * into request_row;
    v_request_id := request_row.id;
    revision_number := request_row.revision;
  end if;

  if initial_stage = ''HR_MANAGER'' then
    insert into public.job_offer_approval_assignments (request_id, approver_user_id, approver_role, approval_stage)
    select v_request_id, user_row.id, ''HR Manager'', ''HR_MANAGER''
    from public.hris_users user_row
    where lower(btrim(coalesce(user_row.status, ''''))) = ''active''
      and private.offer_user_has_role(user_row.id, ''HR Manager'');
  else
    insert into public.job_offer_approval_assignments (request_id, approver_user_id, approver_role, approval_stage)
    select v_request_id, user_row.id,
      case when private.offer_user_has_role(user_row.id, ''Board of Director'') then ''Board of Director'' else ''General Manager'' end,
      ''BOD_GM''
    from public.hris_users user_row
    where lower(btrim(coalesce(user_row.status, ''''))) = ''active''
      and (private.offer_user_has_role(user_row.id, ''Board of Director'') or private.offer_user_has_role(user_row.id, ''GeneralManager''));
  end if;
  select count(*) into assigned_count from public.job_offer_approval_assignments where request_id = request_row.id;
  if assigned_count = 0 then
    delete from public.job_offer_approval_requests where id = request_row.id;
    raise exception ''No active approver is configured for this offer approval stage'' using errcode = ''22023'';
  end if;

  update public.job_offers
  set approval_status = ''Pending Approval'', approval_request_id = request_row.id, updated_at = now()
  where id = p_offer_id;

  insert into public.job_offer_approval_history (
    request_id, approval_stage, approver_user_id, approver_role, action,
    status_before, status_after, comments, documents_reviewed
  ) values (
    request_row.id, initial_stage, actor_id, ''Requester'',
    case when revision_number > 1 then ''RESUBMITTED'' else ''SUBMITTED'' end,
    case when revision_number > 1 then ''Returned for Revision'' else ''Not Requested'' end,
    ''Pending Approval'', nullif(btrim(p_override_reason), ''''), p_attachment_snapshot
  );

  insert into public.audit_logs(user_id, user_email, action, entity, entity_id, details)
  values (
    actor_id::text, actor_email,
    case when revision_number > 1 then ''OFFER_APPROVAL_RESUBMITTED'' else ''OFFER_APPROVAL_SUBMITTED'' end,
    ''job_offer_approval_requests'', request_row.id::text,
    jsonb_build_object(''offer_id'', p_offer_id, ''candidate_id'', application_row.candidate_id,
      ''approval_stage'', initial_stage, ''revision'', revision_number,
      ''override_incomplete_ratings'', coalesce(p_override_incomplete_ratings, false),
      ''override_reason'', nullif(btrim(p_override_reason), ''''), ''documents_reviewed'', p_attachment_snapshot)::text
  );

  insert into public.notifications(user_id, type, title, message, link, is_read, related_entity_id, dedupe_key)
  select assignment.approver_user_id::text, ''OFFER_APPROVAL'',
    ''Offer approval request'',
    format(''An offer approval package for %s is awaiting your %s review.'', candidate.first_name || ''candidate'',
      case when initial_stage = ''HR_MANAGER'' then ''HR Manager'' else ''BOD / GM'' end),
    ''/approvals?type=offer&item='' || request_row.id::text, false, request_row.id::text,
    ''offer-approval:'' || request_row.id::text || '':'' || revision_number::text || '':'' || assignment.approver_user_id::text
  from public.job_offer_approval_assignments assignment
  join public.job_candidates candidate on candidate.id = application_row.candidate_id
  where assignment.request_id = request_row.id;

  return request_row.id;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."upload_job_candidate_document"(uuid, uuid, text, text, text, text, text, bigint)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.upload_job_candidate_document(p_candidate_id uuid, p_application_id uuid, p_document_type text, p_file_name text, p_storage_bucket text, p_storage_path text, p_mime_type text, p_file_size bigint)
 RETURNS job_candidate_documents
 LANGUAGE plpgsql
 SET search_path TO ''public'', ''pg_temp''
AS $function$
declare
  actor_id uuid := public.current_hris_user_id();
  document_row public.job_candidate_documents%rowtype;
begin
  if actor_id is null or not public.has_recruitment_admin_access() then
    raise exception ''Only authorized recruitment users can add candidate documents'' using errcode = ''42501'';
  end if;
  if p_document_type not in (''Resume'', ''Interview Rating'', ''Offer'', ''Other Supporting Document'') then
    raise exception ''Invalid candidate document type'' using errcode = ''22023'';
  end if;
  if not exists (select 1 from public.job_candidates candidate where candidate.id = p_candidate_id) then
    raise exception ''Candidate was not found'' using errcode = ''22023'';
  end if;
  if p_application_id is not null and not exists (
    select 1 from public.job_applications application
    where application.id = p_application_id and application.candidate_id = p_candidate_id
  ) then
    raise exception ''Application does not belong to candidate'' using errcode = ''22023'';
  end if;
  if nullif(btrim(p_file_name), '''') is null or nullif(btrim(p_storage_path), '''') is null then
    raise exception ''Candidate document name and storage path are required'' using errcode = ''22023'';
  end if;
  if p_storage_bucket <> ''candidate-recruitment-documents''
     or p_storage_path !~ (''^candidate-documents/'' || p_candidate_id::text || ''/[^/]+$'') then
    raise exception ''Invalid candidate document storage path'' using errcode = ''22023'';
  end if;
  if p_file_size is null or p_file_size < 1 or p_file_size > 20971520 then
    raise exception ''Candidate documents must be between 1 byte and 20 MB'' using errcode = ''22023'';
  end if;

  insert into public.job_candidate_documents (
    candidate_id, application_id, document_type, file_name, mime_type, file_size,
    storage_bucket, storage_path, uploaded_by_user_id
  ) values (
    p_candidate_id, p_application_id, p_document_type, btrim(p_file_name),
    coalesce(nullif(btrim(p_mime_type), ''''), ''application/octet-stream''), p_file_size,
    p_storage_bucket, p_storage_path, actor_id
  ) returning * into document_row;

  insert into public.audit_logs(user_id, user_email, action, entity, entity_id, details)
  select actor_id::text, user_row.email, ''CANDIDATE_DOCUMENT_ADDED'', ''job_candidate_documents'', document_row.id::text,
    jsonb_build_object(''candidate_id'', p_candidate_id, ''application_id'', p_application_id,
      ''document_type'', p_document_type, ''file_name'', p_file_name)::text
  from public.hris_users user_row
  where user_row.id = actor_id;
  return document_row;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"private"."user_can_handle_incident_case"(uuid)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION private.user_can_handle_incident_case(p_user_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''''
AS $function$
  select exists (
    select 1
    from private.effective_role_ids(p_user_id) effective_role
    join public.incident_case_handler_roles capability
      on capability.role_id = effective_role.role_id
     and capability.is_active
  )
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"private"."user_is_within_current_scope"(uuid)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION private.user_is_within_current_scope(p_target_user_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  viewer public.hris_users%rowtype;
  target_user public.hris_users%rowtype;
  scope jsonb := public.current_data_scope();
  scope_type text := scope->>''type'';
begin
  select * into viewer from public.hris_users where id = public.current_hris_user_id();
  select * into target_user from public.hris_users where id = p_target_user_id;

  if viewer.id is null or target_user.id is null then return false; end if;
  if viewer.id = target_user.id then return true; end if;
  if scope_type = ''GLOBAL'' then return true; end if;
  if scope_type = ''SPECIFIC'' then
    return target_user.business_unit_id::text in (
      select jsonb_array_elements_text(coalesce(scope->''allowedBuIds'', ''[]''::jsonb))
    );
  end if;
  if scope_type = ''HOME_ONLY'' then
    return viewer.business_unit_id is not null and viewer.business_unit_id = target_user.business_unit_id;
  end if;
  if scope_type = ''DEPARTMENT'' then
    return viewer.department_id is not null and viewer.department_id = target_user.department_id;
  end if;
  if scope_type = ''DIRECT_REPORTS'' then
    return target_user.reports_to in (
      viewer.id::text, viewer.auth_user_id::text, viewer.employee_id, viewer.full_name
    );
  end if;
  return false;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."get_assignable_incident_case_handlers"()') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.get_assignable_incident_case_handlers()
 RETURNS TABLE(id uuid, full_name text, email text, job_title text, business_unit text, business_unit_id uuid, role_id text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''''
AS $function$
  select
    candidate.id,
    candidate.full_name,
    candidate.email,
    candidate.position as job_title,
    candidate.business_unit,
    candidate.business_unit_id,
    primary_assignment.role_id
  from public.hris_users candidate
  join lateral (
    select ur.role_id
    from public.user_roles ur
    join public.roles r on r.id = ur.role_id and r.is_active
    where ur.user_id = candidate.id
      and ur.is_active
    order by ur.is_primary desc, ur.role_id
    limit 1
  ) primary_assignment on true
  where public.current_hris_user_id() is not null
    and (
      public.has_feature_permission(''IncidentReports'', ''assign'')
      or public.has_feature_permission(''IncidentReports'', ''manage'')
    )
    and private.is_employee_self_service_eligible(candidate.id)
    and private.user_can_handle_incident_case(candidate.id)
    and private.user_is_within_current_scope(candidate.id)
  order by candidate.full_name, candidate.id
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"private"."can_access_incident_for_nte"(uuid, uuid)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION private.can_access_incident_for_nte(p_incident_report_id uuid, p_recipient_employee_id uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  actor public.hris_users%rowtype;
  incident public.incident_reports%rowtype;
  scope jsonb := public.current_data_scope();
  scope_type text := scope->>''type'';
begin
  select * into actor from public.hris_users where id = public.current_hris_user_id();
  select * into incident from public.incident_reports where id = p_incident_report_id;
  if actor.id is null or incident.id is null then return false; end if;
  if p_recipient_employee_id is not null
     and not (p_recipient_employee_id = any(incident.involved_employee_ids)) then
    return false;
  end if;
  if scope_type = ''GLOBAL'' then return true; end if;
  if scope_type = ''SPECIFIC'' then
    return incident.business_unit_id::text in (
      select jsonb_array_elements_text(coalesce(scope->''allowedBuIds'', ''[]''::jsonb))
    );
  end if;
  if scope_type = ''HOME_ONLY'' then
    return actor.business_unit_id is not null and actor.business_unit_id = incident.business_unit_id;
  end if;
  if p_recipient_employee_id is not null then
    return private.user_is_within_current_scope(p_recipient_employee_id);
  end if;
  return false;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"private"."can_view_nte"(uuid)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION private.can_view_nte(p_nte_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''''
AS $function$
  select exists (
    select 1
    from public.ntes n
    left join public.incident_reports ir on ir.id = n.incident_report_id
    where n.id = p_nte_id
      and (
        n.recipient_employee_id = public.current_hris_user_id()
        or n.issued_by_user_id = public.current_hris_user_id()
        or ir.assigned_to_id = public.current_hris_user_id()
        or exists (
          select 1 from public.nte_approvals a
          where a.nte_id = n.id and a.approver_user_id = public.current_hris_user_id()
        )
        or (
          private.can_issue_nte()
          and private.can_access_incident_for_nte(n.incident_report_id, n.recipient_employee_id)
        )
      )
  )
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"private"."refresh_incident_nte_summary_trigger"()') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION private.refresh_incident_nte_summary_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
begin
  perform private.refresh_incident_nte_summary(coalesce(new.incident_report_id, old.incident_report_id));
  return coalesce(new, old);
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"private"."enforce_employee_specific_nte"()') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION private.enforce_employee_specific_nte()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
begin
  new.recipient_employee_id := coalesce(new.recipient_employee_id, new.recipients[1]);
  new.recipient_name_snapshot := coalesce(nullif(new.recipient_name_snapshot, ''''), nullif(new.recipient_names[1], ''''));

  if new.recipient_employee_id is null then
    raise exception ''Exactly one NTE recipient is required.'' using errcode = ''23502'';
  end if;
  if cardinality(coalesce(new.recipients, ''{}''::uuid[])) <> 1
     or new.recipients[1] <> new.recipient_employee_id then
    raise exception ''An NTE must contain exactly one recipient employee.'' using errcode = ''23514'';
  end if;
  if not exists (
    select 1 from public.incident_reports ir
    where ir.id = new.incident_report_id
      and new.recipient_employee_id = any(ir.involved_employee_ids)
  ) then
    raise exception ''The NTE recipient must be an involved employee on the linked Incident Report.'' using errcode = ''23514'';
  end if;
  if tg_op = ''UPDATE'' and (
    new.incident_report_id is distinct from old.incident_report_id
    or new.recipient_employee_id is distinct from old.recipient_employee_id
  ) then
    raise exception ''The linked Incident Report and NTE recipient cannot be changed after creation.'' using errcode = ''23514'';
  end if;
  if tg_op = ''UPDATE''
     and old.status = ''PendingApproval''::public.nte_status
     and new.status is distinct from old.status
     and coalesce(current_setting(''app.nte_workflow_rpc'', true), ''off'') <> ''on'' then
    raise exception ''Pending NTE approval outcomes must use the assigned approval action.'' using errcode = ''42501'';
  end if;
  if tg_op = ''UPDATE''
     and new.status = ''PendingApproval''::public.nte_status
     and new.status is distinct from old.status
     and coalesce(current_setting(''app.nte_workflow_rpc'', true), ''off'') <> ''on'' then
    raise exception ''NTE submission must use the protected workflow action.'' using errcode = ''42501'';
  end if;
  if tg_op = ''UPDATE''
     and old.status = ''Draft''::public.nte_status
     and new.status = ''Issued''::public.nte_status then
    raise exception ''An NTE cannot be issued without completing required approvals.'' using errcode = ''42501'';
  end if;
  if new.status = ''PendingApproval''::public.nte_status then
    if not exists (
      select 1 from public.nte_approvals a
      where a.nte_id = new.id and a.is_required and a.is_bod_role
        and a.status in (''Pending'', ''Approved'')
    ) then
      raise exception ''At least one selected Board of Director approver is required.'' using errcode = ''23514'';
    end if;
    if not exists (
      select 1 from public.nte_approvals a
      where a.nte_id = new.id and a.is_required
        and a.status in (''Pending'', ''Approved'')
    ) then
      raise exception ''At least one required NTE approver is required.'' using errcode = ''23514'';
    end if;
  end if;
  return new;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."act_on_nte_approval"(uuid, text, text)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.act_on_nte_approval(p_nte_id uuid, p_action text, p_comments text DEFAULT NULL::text)
 RETURNS ntes
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  actor_id uuid := public.current_hris_user_id();
  actor public.hris_users%rowtype;
  current_nte public.ntes;
  current_approval public.nte_approvals;
  previous_nte_status public.nte_status;
  normalized_action text := lower(trim(coalesce(p_action, '''')));
  note text := trim(coalesce(p_comments, ''''));
  all_required_approved boolean;
  bod_approved boolean;
  next_status public.nte_status;
begin
  if actor_id is null then raise exception ''Authentication is required.'' using errcode = ''42501''; end if;
  if normalized_action not in (''approve'', ''return'', ''reject'') then
    raise exception ''Choose Approve, Return for Revision, or Reject.'' using errcode = ''22023'';
  end if;
  if normalized_action in (''return'', ''reject'') and length(note) < 3 then
    raise exception ''Comments are required and must contain at least 3 characters.'' using errcode = ''22023'';
  end if;

  select * into current_nte from public.ntes where id = p_nte_id for update;
  if current_nte.id is null then raise exception ''NTE not found.'' using errcode = ''P0002''; end if;
  if current_nte.status <> ''PendingApproval''::public.nte_status then
    raise exception ''This NTE is no longer pending approval.'' using errcode = ''22023'';
  end if;
  previous_nte_status := current_nte.status;
  select * into current_approval
  from public.nte_approvals
  where nte_id = p_nte_id and approver_user_id = actor_id
  for update;
  if current_approval.id is null then
    raise exception ''This NTE is not assigned to you.'' using errcode = ''42501'';
  end if;
  if current_approval.status <> ''Pending'' then
    raise exception ''This approval task has already been processed.'' using errcode = ''22023'';
  end if;
  select * into actor from public.hris_users
  where id = actor_id and lower(status) = ''active'';
  if actor.id is null then raise exception ''Your active employee profile could not be resolved.'' using errcode = ''42501''; end if;

  if normalized_action = ''approve'' then
    update public.nte_approvals
    set status = ''Approved'', actioned_at = now(), comments = nullif(note, ''''), updated_at = now()
    where id = current_approval.id;
  elsif normalized_action = ''return'' then
    update public.nte_approvals
    set status = ''Returned for Revision'', actioned_at = now(), comments = note, updated_at = now()
    where id = current_approval.id;
    update public.nte_approvals
    set status = ''Cancelled'', actioned_at = now(), comments = ''Cancelled because another required approver returned the NTE for revision.'', updated_at = now()
    where nte_id = p_nte_id and id <> current_approval.id and status = ''Pending'';
  else
    update public.nte_approvals
    set status = ''Rejected'', actioned_at = now(), comments = note, updated_at = now()
    where id = current_approval.id;
    update public.nte_approvals
    set status = ''Cancelled'', actioned_at = now(), comments = ''Cancelled because another required approver rejected the NTE.'', updated_at = now()
    where nte_id = p_nte_id and id <> current_approval.id and status = ''Pending'';
  end if;

  select
    bool_and(status = ''Approved'') filter (where is_required),
    bool_or(status = ''Approved'') filter (where is_required and is_bod_role)
  into all_required_approved, bod_approved
  from public.nte_approvals where nte_id = p_nte_id;

  next_status := case
    when normalized_action = ''return'' then ''Draft''::public.nte_status
    when normalized_action = ''reject'' then ''Rejected''::public.nte_status
    when coalesce(all_required_approved, false) and coalesce(bod_approved, false) then ''Issued''::public.nte_status
    else ''PendingApproval''::public.nte_status
  end;

  perform set_config(''app.nte_workflow_rpc'', ''on'', true);
  update public.ntes
  set status = next_status,
      revision_note = case when normalized_action = ''return'' then note else revision_note end,
      revision_requested_at = case when normalized_action = ''return'' then now() else revision_requested_at end,
      revision_requested_by = case when normalized_action = ''return'' then actor.id else revision_requested_by end,
      workflow_history = coalesce(workflow_history, ''[]''::jsonb) || jsonb_build_array(jsonb_build_object(
        ''action'', upper(normalized_action),
        ''note'', nullif(note, ''''),
        ''actorId'', actor.id,
        ''actorName'', actor.full_name,
        ''actorRole'', current_approval.role_snapshot,
        ''approvalStage'', ''NTE Approval'',
        ''previousStatus'', previous_nte_status::text,
        ''newStatus'', next_status::text,
        ''timestamp'', now()
      )),
      updated_at = now()
  where id = p_nte_id returning * into current_nte;
  perform private.sync_nte_approval_snapshot(p_nte_id);
  select * into current_nte from public.ntes where id = p_nte_id;

  if next_status = ''Issued''::public.nte_status then
    insert into public.notifications(user_id, type, title, message, link, related_entity_id, dedupe_key)
    values (
      current_nte.recipient_employee_id::text, ''NTE_ISSUED'', ''Notice to Explain Issued'',
      format(''Notice to Explain %s has completed approval and requires your response.'', coalesce(current_nte.nte_code, current_nte.nte_number)),
      ''/feedback/nte/'' || current_nte.id::text, current_nte.id::text,
      ''nte:'' || current_nte.id::text || '':issued''
    ) on conflict (user_id, dedupe_key) do nothing;
  elsif next_status in (''Draft''::public.nte_status, ''Rejected''::public.nte_status) then
    insert into public.notifications(user_id, type, title, message, link, related_entity_id, dedupe_key)
    select recipient_id::text, ''GENERAL'',
           case when next_status = ''Draft''::public.nte_status then ''NTE Returned for Revision'' else ''NTE Rejected'' end,
           format(''%s acted on NTE %s. Comments: %s'', actor.full_name, coalesce(current_nte.nte_code, current_nte.nte_number), note),
           ''/feedback/nte/'' || current_nte.id::text, current_nte.id::text,
           ''nte:'' || current_nte.id::text || '':'' || lower(next_status::text) || '':'' || extract(epoch from now())::bigint::text || '':'' || recipient_id::text
    from (
      select current_nte.issued_by_user_id recipient_id
      union
      select ir.assigned_to_id from public.incident_reports ir where ir.id = current_nte.incident_report_id
    ) recipients
    where recipient_id is not null and recipient_id <> actor.id;
  end if;

  insert into public.audit_logs(user_id, user_email, action, entity, entity_id, details)
  values (
    actor.id::text, actor.email, upper(normalized_action), ''NTE'', p_nte_id::text,
    jsonb_build_object(
      ''role'', current_approval.role_snapshot,
      ''approvalStage'', ''NTE Approval'',
      ''previousStatus'', previous_nte_status::text,
      ''newStatus'', next_status::text,
      ''comments'', nullif(note, '''')
    )::text
  );
  perform private.refresh_incident_nte_summary(current_nte.incident_report_id);
  return current_nte;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."get_eligible_nte_approvers"(uuid, uuid)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.get_eligible_nte_approvers(p_incident_report_id uuid, p_recipient_employee_id uuid)
 RETURNS TABLE(id uuid, full_name text, email text, job_position text, business_unit_id uuid, business_unit text, eligible_role_ids text[], eligible_role_labels text[], has_bod_role boolean, preferred_role_id text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''''
AS $function$
begin
  if not private.can_issue_nte() then
    raise exception ''You are not authorized to issue an NTE.'' using errcode = ''42501'';
  end if;
  if not private.can_access_incident_for_nte(p_incident_report_id, p_recipient_employee_id) then
    raise exception ''The Incident Report or recipient is outside your authorized scope.'' using errcode = ''42501'';
  end if;

  return query
  with incident as (
    select ir.business_unit_id from public.incident_reports ir where ir.id = p_incident_report_id
  ), candidates as (
    select
      u.id,
      u.full_name,
      u.email,
      u.position,
      u.business_unit_id,
      coalesce(bu.name, u.business_unit) business_unit,
      array_agg(distinct ur.role_id order by ur.role_id) role_ids,
      array_agg(distinct coalesce(r.display_name, r.id) order by coalesce(r.display_name, r.id)) role_labels,
      bool_or(capability.is_bod_role) has_bod,
      (array_agg(ur.role_id order by capability.is_bod_role desc, ur.is_primary desc, ur.role_id))[1] preferred_role
    from public.hris_users u
    join public.user_roles ur on ur.user_id = u.id and ur.is_active
    join public.roles r on r.id = ur.role_id and r.is_active
    join public.nte_approver_roles capability on capability.role_id = ur.role_id and capability.is_active
    left join public.business_units bu on bu.id = u.business_unit_id
    cross join incident
    left join auth.users au on au.id = u.auth_user_id
    where u.id <> p_recipient_employee_id
      and lower(coalesce(u.status, '''')) = ''active''
      and lower(coalesce(u.employment_status, ''active'')) not in (''inactive'', ''terminated'', ''archived'', ''separated'')
      and coalesce(u.end_date, current_date) >= current_date
      and u.auth_user_id is not null
      and au.id is not null
      and au.deleted_at is null
      and coalesce(au.banned_until, ''-infinity''::timestamptz) <= now()
      and (
        public.current_data_scope()->>''type'' = ''GLOBAL''
        or private.user_is_within_current_scope(u.id)
      )
    group by u.id, u.full_name, u.email, u.position, u.business_unit_id, bu.name, u.business_unit, incident.business_unit_id
  )
  select c.id, c.full_name, c.email, c.position, c.business_unit_id, c.business_unit,
         c.role_ids, c.role_labels, c.has_bod, c.preferred_role
  from candidates c
  cross join incident
  order by (c.business_unit_id = incident.business_unit_id) desc, c.has_bod desc, c.full_name;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."create_nte_for_employee"(uuid, uuid, uuid, timestamp with time zone, text, text, text, text[], text[], jsonb, text)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.create_nte_for_employee(p_incident_report_id uuid, p_recipient_employee_id uuid, p_template_id uuid, p_response_deadline timestamp with time zone, p_details text, p_body text, p_evidence_link text DEFAULT NULL::text, p_memo_ids text[] DEFAULT ''{}''::text[], p_discipline_code_ids text[] DEFAULT ''{}''::text[], p_approvers jsonb DEFAULT ''[]''::jsonb, p_nte_number text DEFAULT NULL::text)
 RETURNS ntes
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  actor_id uuid := public.current_hris_user_id();
  actor public.hris_users%rowtype;
  recipient public.hris_users%rowtype;
  incident public.incident_reports%rowtype;
  created_nte public.ntes;
  approver_input record;
  selected_role record;
  approver_user public.hris_users%rowtype;
  selected_count integer := 0;
  selected_bod_count integer := 0;
  approver_snapshot jsonb := ''[]''::jsonb;
begin
  if actor_id is null or not private.can_issue_nte() then
    raise exception ''You are not authorized to issue an NTE.'' using errcode = ''42501'';
  end if;
  select * into actor from public.hris_users where id = actor_id;
  select * into incident from public.incident_reports where id = p_incident_report_id for update;
  if incident.id is null then raise exception ''Incident Report not found.'' using errcode = ''P0002''; end if;
  if not private.can_access_incident_for_nte(p_incident_report_id, p_recipient_employee_id) then
    raise exception ''The Incident Report or recipient is outside your authorized scope.'' using errcode = ''42501'';
  end if;
  select * into recipient from public.hris_users where id = p_recipient_employee_id;
  if recipient.id is null or not (recipient.id = any(incident.involved_employee_ids)) then
    raise exception ''The selected employee is not involved in this Incident Report.'' using errcode = ''22023'';
  end if;
  if p_response_deadline is null then raise exception ''A response deadline is required.'' using errcode = ''22023''; end if;
  if length(trim(coalesce(p_details, ''''))) = 0 then raise exception ''NTE allegations/details are required.'' using errcode = ''22023''; end if;
  if jsonb_typeof(coalesce(p_approvers, ''[]''::jsonb)) <> ''array'' then
    raise exception ''The approver list must be an array.'' using errcode = ''22023'';
  end if;
  if exists (
    select 1 from public.ntes n
    where n.incident_report_id = p_incident_report_id
      and n.recipient_employee_id = p_recipient_employee_id
      and n.status not in (''Rejected''::public.nte_status, ''Closed''::public.nte_status)
  ) then
    raise exception ''An active NTE already exists for this employee and Incident Report.'' using errcode = ''23505'';
  end if;
  if exists (
    select 1
    from jsonb_array_elements(coalesce(p_approvers, ''[]''::jsonb)) entry
    group by entry->>''userId''
    having count(*) > 1
  ) then
    raise exception ''The same approver cannot be selected more than once.'' using errcode = ''23505'';
  end if;
  if nullif(trim(coalesce(p_nte_number, '''')), '''') is not null and exists (
    select 1 from public.ntes n where trim(n.nte_number::text) = trim(p_nte_number)
  ) then
    raise exception ''The requested NTE number is already in use.'' using errcode = ''23505'';
  end if;

  insert into public.ntes(
    incident_report_id, template_id, issued_by_user_id, issued_by_name,
    recipients, recipient_names, recipient_employee_id, recipient_name_snapshot,
    response_deadline, details, evidence_link, status, body, memo_ids,
    discipline_code_ids, nte_number
  ) values (
    incident.id, p_template_id, actor.id, actor.full_name,
    array[recipient.id], array[recipient.full_name], recipient.id, recipient.full_name,
    p_response_deadline, trim(p_details), p_evidence_link, ''Draft''::public.nte_status,
    p_body, coalesce(p_memo_ids, ''{}''), coalesce(p_discipline_code_ids, ''{}''),
    coalesce(nullif(trim(p_nte_number), ''''), nextval(''public.ntes_nte_number_seq'')::text)
  ) returning * into created_nte;

  for approver_input in
    select entry->>''userId'' user_id, entry->>''roleId'' role_id,
           nullif(trim(entry->>''selectionReason''), '''') selection_reason
    from jsonb_array_elements(coalesce(p_approvers, ''[]''::jsonb)) entry
  loop
    if approver_input.user_id is null or approver_input.role_id is null then
      raise exception ''Every selected approver requires a user and role.'' using errcode = ''22023'';
    end if;
    if approver_input.user_id::uuid = recipient.id then
      raise exception ''The NTE recipient cannot approve their own NTE.'' using errcode = ''22023'';
    end if;

    select ur.role_id, coalesce(r.display_name, r.id) display_name, capability.is_bod_role
    into selected_role
    from public.user_roles ur
    join public.roles r on r.id = ur.role_id and r.is_active
    join public.nte_approver_roles capability on capability.role_id = ur.role_id and capability.is_active
    where ur.user_id = approver_input.user_id::uuid
      and ur.role_id = approver_input.role_id
      and ur.is_active;
    if selected_role.role_id is null then
      raise exception ''A selected approver no longer has the eligible role used for selection.'' using errcode = ''42501'';
    end if;

    select u.* into approver_user
    from public.hris_users u
    left join auth.users au on au.id = u.auth_user_id
    where u.id = approver_input.user_id::uuid
      and lower(coalesce(u.status, '''')) = ''active''
      and lower(coalesce(u.employment_status, ''active'')) not in (''inactive'', ''terminated'', ''archived'', ''separated'')
      and coalesce(u.end_date, current_date) >= current_date
      and au.id is not null and au.deleted_at is null
      and coalesce(au.banned_until, ''-infinity''::timestamptz) <= now();
    if approver_user.id is null then
      raise exception ''A selected approver is not an active eligible user.'' using errcode = ''42501'';
    end if;
    if public.current_data_scope()->>''type'' <> ''GLOBAL''
       and not private.user_is_within_current_scope(approver_user.id)
       then
      raise exception ''A selected approver is outside your authorized scope.'' using errcode = ''42501'';
    end if;

    insert into public.nte_approvals(
      nte_id, approver_user_id, approver_employee_id, selection_role_id,
      role_snapshot, is_bod_role, is_required, status, selected_by,
      selection_source, selection_reason
    ) values (
      created_nte.id, approver_user.id, approver_user.id, selected_role.role_id,
      selected_role.display_name, selected_role.is_bod_role, true, ''Pending'', actor.id,
      ''manual'', approver_input.selection_reason
    );
    selected_count := selected_count + 1;
    if selected_role.is_bod_role then selected_bod_count := selected_bod_count + 1; end if;
    approver_snapshot := approver_snapshot || jsonb_build_array(jsonb_build_object(
      ''userId'', approver_user.id,
      ''name'', approver_user.full_name,
      ''roleId'', selected_role.role_id,
      ''role'', selected_role.display_name,
      ''isBod'', selected_role.is_bod_role
    ));
  end loop;

  if selected_count = 0 then raise exception ''At least one NTE approver is required.'' using errcode = ''23514''; end if;
  if selected_bod_count = 0 then raise exception ''At least one Board of Director is required.'' using errcode = ''23514''; end if;

  perform private.sync_nte_approval_snapshot(created_nte.id);
  perform set_config(''app.nte_workflow_rpc'', ''on'', true);
  update public.ntes set status = ''PendingApproval''::public.nte_status, updated_at = now()
  where id = created_nte.id returning * into created_nte;

  insert into public.notifications(user_id, type, title, message, link, related_entity_id, dedupe_key)
  select a.approver_user_id::text, ''NTE_ISSUED'', ''NTE Approval Required'',
         format(''You have been selected to approve %s for %s.'', coalesce(created_nte.nte_code, created_nte.nte_number), recipient.full_name),
         ''/feedback/nte/'' || created_nte.id::text, created_nte.id::text,
         ''nte:'' || created_nte.id::text || '':approval:'' || a.approver_user_id::text || '':v1''
  from public.nte_approvals a where a.nte_id = created_nte.id
  on conflict (user_id, dedupe_key) do nothing;

  insert into public.audit_logs(user_id, user_email, action, entity, entity_id, details)
  values (
    actor.id::text, actor.email, ''CREATE'', ''NTE'', created_nte.id::text,
    jsonb_build_object(
      ''incidentReportId'', incident.id,
      ''recipientEmployeeId'', recipient.id,
      ''recipientName'', recipient.full_name,
      ''selectedApprovers'', approver_snapshot,
      ''status'', ''PendingApproval''
    )::text
  );
  perform private.refresh_incident_nte_summary(incident.id);
  return created_nte;
exception when others then
  raise;
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."get_my_pending_nte_approvals"()') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.get_my_pending_nte_approvals()
 RETURNS TABLE(id uuid, incident_report_id uuid, recipient_employee_id uuid, recipient_name text, response_deadline timestamp with time zone, status text, created_at timestamp with time zone, updated_at timestamp with time zone, nte_number text, nte_code text, approval_id uuid, approval_role text, approval_assigned_at timestamp with time zone, case_number integer, category text, business_unit_id uuid, business_unit_name text, assigned_to_name text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''''
AS $function$
  select n.id, n.incident_report_id, n.recipient_employee_id,
         coalesce(n.recipient_name_snapshot, n.recipient_names[1]),
         n.response_deadline, n.status::text, n.created_at, n.updated_at,
         n.nte_number, n.nte_code, a.id, a.role_snapshot, a.assigned_at,
         ir.case_number, ir.category, ir.business_unit_id, ir.business_unit_name,
         ir.assigned_to_name
  from public.nte_approvals a
  join public.ntes n on n.id = a.nte_id
  join public.incident_reports ir on ir.id = n.incident_report_id
  where a.approver_user_id = public.current_hris_user_id()
    and a.status = ''Pending''
    and n.status = ''PendingApproval''::public.nte_status
  order by a.assigned_at desc
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regprocedure('"public"."process_nte_bod_outcome"(uuid, text, text)') IS NULL THEN
    EXECUTE 'CREATE OR REPLACE FUNCTION public.process_nte_bod_outcome(p_nte_id uuid, p_outcome text, p_note text)
 RETURNS ntes
 LANGUAGE plpgsql
 SET search_path TO ''''
AS $function$
begin
  return public.act_on_nte_approval(
    p_nte_id,
    case lower(trim(coalesce(p_outcome, '''')))
      when ''revision'' then ''return''
      when ''closure'' then ''reject''
      else p_outcome
    end,
    p_note
  );
end;
$function$
';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regclass('"public"."demand_type_configs"') IS NULL THEN
    EXECUTE 'CREATE VIEW "public"."demand_type_configs" WITH (security_invoker=true) AS  SELECT id,
    business_unit_id,
    tier,
    label,
    color,
    description,
    created_at,
    updated_at
   FROM demand_types;';
  END IF;
END
$parity$;


DO $parity$
BEGIN
  IF to_regclass('"public"."audit_feed"') IS NULL THEN
    EXECUTE 'CREATE VIEW "public"."audit_feed" WITH (security_invoker=true) AS  SELECT u.id,
    u.created_at AS "timestamp",
    u.full_name AS user_email,
    ''REGISTER''::text AS action,
    ''Auth''::text AS entity,
