    EXECUTE 'CREATE POLICY "candidate_recruitment_documents_storage_select" ON "storage"."objects" AS PERMISSIVE FOR SELECT TO "authenticated" USING (((bucket_id = ''candidate-recruitment-documents''::text) AND (( SELECT has_recruitment_admin_access() AS has_recruitment_admin_access) OR (EXISTS ( SELECT 1
   FROM ((job_candidate_documents document
     JOIN job_offer_approval_requests request ON ((request.candidate_id = document.candidate_id)))
     JOIN job_offer_approval_assignments assignment ON ((assignment.request_id = request.id)))
  WHERE ((document.storage_bucket = objects.bucket_id) AND (document.storage_path = objects.name) AND (assignment.approver_user_id = ( SELECT current_hris_user_id() AS current_hris_user_id)) AND (EXISTS ( SELECT 1
           FROM jsonb_array_elements(request.attachment_snapshot) attachment(value)
          WHERE (((attachment.value ->> ''source''::text) = ''candidate_document''::text) AND ((attachment.value ->> ''sourceId''::text) = (document.id)::text))))))))));';
  END IF;
END
