     CROSS JOIN LATERAL jsonb_array_elements(COALESCE(envelope.attachments, ''[]''::jsonb)) attachment(value))
  WHERE (((attachment.value ->> ''path''::text) = objects.name) AND ((envelope.employee_id = current_hris_user_id()) OR (envelope.created_by_user_id = current_hris_user_id()) OR (EXISTS ( SELECT 1
           FROM jsonb_array_elements(COALESCE(envelope.routing_steps, ''[]''::jsonb)) routing_step(value)
          WHERE ((routing_step.value ->> ''userId''::text) = (current_hris_user_id())::text))) OR (has_feature_permission(''ContractsSigning''::text, ''view''::text) AND can_access_hris_user(envelope.employee_id))))))));';
